INSERT INTO light_cones (name, path, rarity, icon_path, passive_json) VALUES
  ('Abenteuer der Urlaubsbäder', 'Die Nichtigkeit', 4, 'assets/images/light_cones/holiday_thermae_escapade.png', '{"name": "Chillen", "text": ["Erhöht den vom Träger verursachten SCH um 16%. Nachdem der Träger angegriffen hat, besteht eine Grundchance von 100%, dem Angriffsziel für 2 Rd. Anfälligkeit zuzufügen und seinen erlittenen SCH um 10% zu erhöhen. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den vom Träger verursachten SCH um 20%. Nachdem der Träger angegriffen hat, besteht eine Grundchance von 100%, dem Angriffsziel für 2 Rd. Anfälligkeit zuzufügen und seinen erlittenen SCH um 12% zu erhöhen. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den vom Träger verursachten SCH um 24%. Nachdem der Träger angegriffen hat, besteht eine Grundchance von 100%, dem Angriffsziel für 2 Rd. Anfälligkeit zuzufügen und seinen erlittenen SCH um 13% zu erhöhen. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den vom Träger verursachten SCH um 28%. Nachdem der Träger angegriffen hat, besteht eine Grundchance von 100%, dem Angriffsziel für 2 Rd. Anfälligkeit zuzufügen und seinen erlittenen SCH um 15% zu erhöhen. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den vom Träger verursachten SCH um 32%. Nachdem der Träger angegriffen hat, besteht eine Grundchance von 100%, dem Angriffsziel für 2 Rd. Anfälligkeit zuzufügen und seinen erlittenen SCH um 16% zu erhöhen. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Abenteuer in Traumstadt', 'Die Harmonie', 4, 'assets/images/light_cones/dreamville_adventure.png', '{"name": "Solidarität", "text": ["Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates des Trägers erhalten alle Verbündeten „Kindliches Gemüt“, wodurch der SCH der jeweiligen verwendeten Fähigkeit um 12% erhöht wird. Kindliches Gemüt wirkt nur auf die letzte vom Träger eingesetzte Fähigkeit und ist nicht stapelbar.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates des Trägers erhalten alle Verbündeten „Kindliches Gemüt“, wodurch der SCH der jeweiligen verwendeten Fähigkeit um 14% erhöht wird. Kindliches Gemüt wirkt nur auf die letzte vom Träger eingesetzte Fähigkeit und ist nicht stapelbar.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates des Trägers erhalten alle Verbündeten „Kindliches Gemüt“, wodurch der SCH der jeweiligen verwendeten Fähigkeit um 16% erhöht wird. Kindliches Gemüt wirkt nur auf die letzte vom Träger eingesetzte Fähigkeit und ist nicht stapelbar.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates des Trägers erhalten alle Verbündeten „Kindliches Gemüt“, wodurch der SCH der jeweiligen verwendeten Fähigkeit um 18% erhöht wird. Kindliches Gemüt wirkt nur auf die letzte vom Träger eingesetzte Fähigkeit und ist nicht stapelbar.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates des Trägers erhalten alle Verbündeten „Kindliches Gemüt“, wodurch der SCH der jeweiligen verwendeten Fähigkeit um 20% erhöht wird. Kindliches Gemüt wirkt nur auf die letzte vom Träger eingesetzte Fähigkeit und ist nicht stapelbar."]}'),
  ('Abonniere für mehr!', 'Die Jagd', 4, 'assets/images/light_cones/subscribe_for_more.png', '{"name": "Gib uns einen Like, bevor du gehst!", "text": ["Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 24%. Dieser Effekt wird zusätzlich um 24% erhöht, wenn die aktuelle Energie des Trägers den Höchstwert erreicht.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 30%. Dieser Effekt wird zusätzlich um 30% erhöht, wenn die aktuelle Energie des Trägers den Höchstwert erreicht.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 36%. Dieser Effekt wird zusätzlich um 36% erhöht, wenn die aktuelle Energie des Trägers den Höchstwert erreicht.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 42%. Dieser Effekt wird zusätzlich um 42% erhöht, wenn die aktuelle Energie des Trägers den Höchstwert erreicht.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 48%. Dieser Effekt wird zusätzlich um 48% erhöht, wenn die aktuelle Energie des Trägers den Höchstwert erreicht."]}'),
  ('Auf das Sternenlicht der langen Nacht', 'Das Gedenken', 5, 'assets/images/light_cones/to_evernight_s_stars.png', '{"name": "Schlaflos", "text": ["Erhöht die max. LP des Trägers um 30%. Wenn der Memogeist des Trägers eine Fähigkeit einsetzt, erhält der Träger „Nachtschimmer“. Während der Träger Nachtschimmer besitzt, ignorieren alle verbündeten Memogeister beim Verursachen von SCH 20% der VTD des Ziels, und der verursachte SCH des Trägers und seines Memogeists wird um 30% erhöht. Wenn der Memogeist des Trägers verschwindet, stellt der Träger 8 Pkt. Energie wieder her. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die max. LP des Trägers um 38%. Wenn der Memogeist des Trägers eine Fähigkeit einsetzt, erhält der Träger „Nachtschimmer“. Während der Träger Nachtschimmer besitzt, ignorieren alle verbündeten Memogeister beim Verursachen von SCH 23% der VTD des Ziels, und der verursachte SCH des Trägers und seines Memogeists wird um 38% erhöht. Wenn der Memogeist des Trägers verschwindet, stellt der Träger 10 Pkt. Energie wieder her. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die max. LP des Trägers um 45%. Wenn der Memogeist des Trägers eine Fähigkeit einsetzt, erhält der Träger „Nachtschimmer“. Während der Träger Nachtschimmer besitzt, ignorieren alle verbündeten Memogeister beim Verursachen von SCH 25% der VTD des Ziels, und der verursachte SCH des Trägers und seines Memogeists wird um 45% erhöht. Wenn der Memogeist des Trägers verschwindet, stellt der Träger 12 Pkt. Energie wieder her. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die max. LP des Trägers um 53%. Wenn der Memogeist des Trägers eine Fähigkeit einsetzt, erhält der Träger „Nachtschimmer“. Während der Träger Nachtschimmer besitzt, ignorieren alle verbündeten Memogeister beim Verursachen von SCH 28% der VTD des Ziels, und der verursachte SCH des Trägers und seines Memogeists wird um 53% erhöht. Wenn der Memogeist des Trägers verschwindet, stellt der Träger 14 Pkt. Energie wieder her. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die max. LP des Trägers um 60%. Wenn der Memogeist des Trägers eine Fähigkeit einsetzt, erhält der Träger „Nachtschimmer“. Während der Träger Nachtschimmer besitzt, ignorieren alle verbündeten Memogeister beim Verursachen von SCH 30% der VTD des Ziels, und der verursachte SCH des Trägers und seines Memogeists wird um 60% erhöht. Wenn der Memogeist des Trägers verschwindet, stellt der Träger 16 Pkt. Energie wieder her. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Auf zu einem zweiten Leben', 'Die Jagd', 5, 'assets/images/light_cones/sailing_towards_a_second_life.png', '{"name": "Starker Wellengang", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Vom Träger verursachter Bruch-SCH ignoriert 20% der VTD des Ziels. Wenn der Brucheffekt des Trägers im Kampf 150% oder mehr beträgt, wird seine GES um 12% erhöht.", "Erhöht den Brucheffekt des Trägers um 70%. Vom Träger verursachter Bruch-SCH ignoriert 23% der VTD des Ziels. Wenn der Brucheffekt des Trägers im Kampf 150% oder mehr beträgt, wird seine GES um 14% erhöht.", "Erhöht den Brucheffekt des Trägers um 80%. Vom Träger verursachter Bruch-SCH ignoriert 26% der VTD des Ziels. Wenn der Brucheffekt des Trägers im Kampf 150% oder mehr beträgt, wird seine GES um 16% erhöht.", "Erhöht den Brucheffekt des Trägers um 90%. Vom Träger verursachter Bruch-SCH ignoriert 29% der VTD des Ziels. Wenn der Brucheffekt des Trägers im Kampf 150% oder mehr beträgt, wird seine GES um 18% erhöht.", "Erhöht den Brucheffekt des Trägers um 100%. Vom Träger verursachter Bruch-SCH ignoriert 32% der VTD des Ziels. Wenn der Brucheffekt des Trägers im Kampf 150% oder mehr beträgt, wird seine GES um 20% erhöht."]}'),
  ('Auf zu unerklärlichen Orten', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/into_the_unreachable_veil.png', '{"name": "Denkspiel", "text": ["Erhöht die KRIT-Rate des Trägers um 12%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte Fertigkeits- und Ultimate-SCH für 3 Rd. um 60% erhöht. Wenn nach dem Einsatz des Ultimates 140 Pkt. oder mehr Energie verbraucht wird, wird 1 Fertigkeitspunkt wiederhergestellt.", "Erhöht die KRIT-Rate des Trägers um 14%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte Fertigkeits- und Ultimate-SCH für 3 Rd. um 70% erhöht. Wenn nach dem Einsatz des Ultimates 140 Pkt. oder mehr Energie verbraucht wird, wird 1 Fertigkeitspunkt wiederhergestellt.", "Erhöht die KRIT-Rate des Trägers um 16%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte Fertigkeits- und Ultimate-SCH für 3 Rd. um 80% erhöht. Wenn nach dem Einsatz des Ultimates 140 Pkt. oder mehr Energie verbraucht wird, wird 1 Fertigkeitspunkt wiederhergestellt.", "Erhöht die KRIT-Rate des Trägers um 18%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte Fertigkeits- und Ultimate-SCH für 3 Rd. um 90% erhöht. Wenn nach dem Einsatz des Ultimates 140 Pkt. oder mehr Energie verbraucht wird, wird 1 Fertigkeitspunkt wiederhergestellt.", "Erhöht die KRIT-Rate des Trägers um 20%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte Fertigkeits- und Ultimate-SCH für 3 Rd. um 100% erhöht. Wenn nach dem Einsatz des Ultimates 140 Pkt. oder mehr Energie verbraucht wird, wird 1 Fertigkeitspunkt wiederhergestellt."]}'),
  ('Aufschwung', 'Der Überfluss', 3, 'assets/images/light_cones/multiplication.png', '{"name": "Wesen des Überflusses", "text": ["Nach dem Einsatz des Standardangriffs wird die nächste Aktion des Trägers um 12% vorgezogen.", "Nach dem Einsatz des Standardangriffs wird die nächste Aktion des Trägers um 14% vorgezogen.", "Nach dem Einsatz des Standardangriffs wird die nächste Aktion des Trägers um 16% vorgezogen.", "Nach dem Einsatz des Standardangriffs wird die nächste Aktion des Trägers um 18% vorgezogen.", "Nach dem Einsatz des Standardangriffs wird die nächste Aktion des Trägers um 20% vorgezogen."]}'),
  ('Begegnung in der nächsten Blütezeit', 'Das Hochgefühl', 5, 'assets/images/light_cones/until_the_flowers_bloom_again.png', '{"name": "Tagträumerei", "text": ["Erhöht den KRIT-SCH des Trägers um 60% und die Energie-Wiederherstellungsrate um 10%. Wenn die max. Energie des Trägers höher als 120 ist, wird die Energie-Wiederherstellungsrate für je 10 überschüssige Pkt. an max. Energie zusätzlich um 0,3% erhöht, wobei höchstens 360 überschüssige Pkt. an max. Energie gezählt werden. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, wird der von allen Gegnern erlittene SCH für 2 Rd. um 15% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 75% und die Energie-Wiederherstellungsrate um 11,5%. Wenn die max. Energie des Trägers höher als 120 ist, wird die Energie-Wiederherstellungsrate für je 10 überschüssige Pkt. an max. Energie zusätzlich um 0,3% erhöht, wobei höchstens 360 überschüssige Pkt. an max. Energie gezählt werden. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, wird der von allen Gegnern erlittene SCH für 2 Rd. um 18,8% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 90% und die Energie-Wiederherstellungsrate um 13%. Wenn die max. Energie des Trägers höher als 120 ist, wird die Energie-Wiederherstellungsrate für je 10 überschüssige Pkt. an max. Energie zusätzlich um 0,3% erhöht, wobei höchstens 360 überschüssige Pkt. an max. Energie gezählt werden. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, wird der von allen Gegnern erlittene SCH für 2 Rd. um 22,5% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 105% und die Energie-Wiederherstellungsrate um 14,5%. Wenn die max. Energie des Trägers höher als 120 ist, wird die Energie-Wiederherstellungsrate für je 10 überschüssige Pkt. an max. Energie zusätzlich um 0,3% erhöht, wobei höchstens 360 überschüssige Pkt. an max. Energie gezählt werden. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, wird der von allen Gegnern erlittene SCH für 2 Rd. um 26,2% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 120% und die Energie-Wiederherstellungsrate um 16%. Wenn die max. Energie des Trägers höher als 120 ist, wird die Energie-Wiederherstellungsrate für je 10 überschüssige Pkt. an max. Energie zusätzlich um 0,3% erhöht, wobei höchstens 360 überschüssige Pkt. an max. Energie gezählt werden. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, wird der von allen Gegnern erlittene SCH für 2 Rd. um 30% erhöht. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Bei der Jagd nach dem Wind', 'Die Harmonie', 4, 'assets/images/light_cones/in_pursuit_of_the_wind.png', '{"name": "Außer sich", "text": ["Erhöht nach Kampfeintritt den von allen Verbündeten verursachten Bruch-SCH um 16%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den von allen Verbündeten verursachten Bruch-SCH um 18%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den von allen Verbündeten verursachten Bruch-SCH um 20%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den von allen Verbündeten verursachten Bruch-SCH um 22%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den von allen Verbündeten verursachten Bruch-SCH um 24%. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Beim ersten Echo von Aha', 'Das Hochgefühl', 5, 'assets/images/light_cones/upon_the_first_echo_of_aha.png', '{"name": "Impro-Tour", "text": ["Erhöht die Basis-GES des Trägers um 12. Wenn die Fertigkeit auf einen anderen Verbündeten angewendet wird, erhält der Träger 10 Lachpunkte. Dieser Effekt kann in einem Abstand von jeweils 1 Rd. bis zu einmal ausgelöst werden. Danach ignorieren alle Verbündeten in diesem Kampf beim Verursachen von SCH 16% der VTD des Gegners. Dieser Effekt ist nicht stapelbar.", "Erhöht die Basis-GES des Trägers um 14. Wenn die Fertigkeit auf einen anderen Verbündeten angewendet wird, erhält der Träger 12 Lachpunkte. Dieser Effekt kann in einem Abstand von jeweils 1 Rd. bis zu einmal ausgelöst werden. Danach ignorieren alle Verbündeten in diesem Kampf beim Verursachen von SCH 18% der VTD des Gegners. Dieser Effekt ist nicht stapelbar.", "Erhöht die Basis-GES des Trägers um 16. Wenn die Fertigkeit auf einen anderen Verbündeten angewendet wird, erhält der Träger 14 Lachpunkte. Dieser Effekt kann in einem Abstand von jeweils 1 Rd. bis zu einmal ausgelöst werden. Danach ignorieren alle Verbündeten in diesem Kampf beim Verursachen von SCH 20% der VTD des Gegners. Dieser Effekt ist nicht stapelbar.", "Erhöht die Basis-GES des Trägers um 18. Wenn die Fertigkeit auf einen anderen Verbündeten angewendet wird, erhält der Träger 16 Lachpunkte. Dieser Effekt kann in einem Abstand von jeweils 1 Rd. bis zu einmal ausgelöst werden. Danach ignorieren alle Verbündeten in diesem Kampf beim Verursachen von SCH 22% der VTD des Gegners. Dieser Effekt ist nicht stapelbar.", "Erhöht die Basis-GES des Trägers um 20. Wenn die Fertigkeit auf einen anderen Verbündeten angewendet wird, erhält der Träger 18 Lachpunkte. Dieser Effekt kann in einem Abstand von jeweils 1 Rd. bis zu einmal ausgelöst werden. Danach ignorieren alle Verbündeten in diesem Kampf beim Verursachen von SCH 24% der VTD des Gegners. Dieser Effekt ist nicht stapelbar."]}'),
  ('Bernstein', 'Die Bewahrung', 3, 'assets/images/light_cones/amber.png', '{"name": "Stillstand", "text": ["Erhöht die VTD des Trägers um 16%. Liegt der LP-Prozentsatz des Trägers niedriger als 50%, wird die VTD zusätzlich um 16% erhöht.", "Erhöht die VTD des Trägers um 20%. Liegt der LP-Prozentsatz des Trägers niedriger als 50%, wird die VTD zusätzlich um 20% erhöht.", "Erhöht die VTD des Trägers um 24%. Liegt der LP-Prozentsatz des Trägers niedriger als 50%, wird die VTD zusätzlich um 24% erhöht.", "Erhöht die VTD des Trägers um 28%. Liegt der LP-Prozentsatz des Trägers niedriger als 50%, wird die VTD zusätzlich um 28% erhöht.", "Erhöht die VTD des Trägers um 32%. Liegt der LP-Prozentsatz des Trägers niedriger als 50%, wird die VTD zusätzlich um 32% erhöht."]}'),
  ('Besorgt doch glückselig', 'Die Jagd', 5, 'assets/images/light_cones/worrisome_blissful.png', '{"name": "Einer nach dem Anderen", "text": ["Erhöht die KRIT-Rate des Trägers um 18% und den durch Folgeangriffe verursachten SCH um 30%. Wenn der Träger einen Folgeangriff ausführt, wird das Ziel in den Status „Zähmen“ versetzt. Dieser Effekt ist bis zu 2-fach stapelbar. Wenn Verbündete Gegner im Status „Zähmen“ treffen, erhöht jede Stapelung von „Zähmen“ den verursachten KRIT-SCH um 12%.", "Erhöht die KRIT-Rate des Trägers um 21% und den durch Folgeangriffe verursachten SCH um 35%. Wenn der Träger einen Folgeangriff ausführt, wird das Ziel in den Status „Zähmen“ versetzt. Dieser Effekt ist bis zu 2-fach stapelbar. Wenn Verbündete Gegner im Status „Zähmen“ treffen, erhöht jede Stapelung von „Zähmen“ den verursachten KRIT-SCH um 14%.", "Erhöht die KRIT-Rate des Trägers um 24% und den durch Folgeangriffe verursachten SCH um 40%. Wenn der Träger einen Folgeangriff ausführt, wird das Ziel in den Status „Zähmen“ versetzt. Dieser Effekt ist bis zu 2-fach stapelbar. Wenn Verbündete Gegner im Status „Zähmen“ treffen, erhöht jede Stapelung von „Zähmen“ den verursachten KRIT-SCH um 16%.", "Erhöht die KRIT-Rate des Trägers um 27% und den durch Folgeangriffe verursachten SCH um 45%. Wenn der Träger einen Folgeangriff ausführt, wird das Ziel in den Status „Zähmen“ versetzt. Dieser Effekt ist bis zu 2-fach stapelbar. Wenn Verbündete Gegner im Status „Zähmen“ treffen, erhöht jede Stapelung von „Zähmen“ den verursachten KRIT-SCH um 18%.", "Erhöht die KRIT-Rate des Trägers um 30% und den durch Folgeangriffe verursachten SCH um 50%. Wenn der Träger einen Folgeangriff ausführt, wird das Ziel in den Status „Zähmen“ versetzt. Dieser Effekt ist bis zu 2-fach stapelbar. Wenn Verbündete Gegner im Status „Zähmen“ treffen, erhöht jede Stapelung von „Zähmen“ den verursachten KRIT-SCH um 20%."]}'),
  ('Bevor das Tutorial beginnt', 'Die Nichtigkeit', 4, 'assets/images/light_cones/before_the_tutorial_mission_starts.png', '{"name": "Flinke Hände", "text": ["Erhöht die Effekt-Trefferrate des Trägers um 20%. Wenn der Träger Gegner mit reduzierter VTD angreift, wird 4 Pkt. Energie wiederhergestellt.", "Erhöht die Effekt-Trefferrate des Trägers um 25%. Wenn der Träger Gegner mit reduzierter VTD angreift, wird 5 Pkt. Energie wiederhergestellt.", "Erhöht die Effekt-Trefferrate des Trägers um 30%. Wenn der Träger Gegner mit reduzierter VTD angreift, wird 6 Pkt. Energie wiederhergestellt.", "Erhöht die Effekt-Trefferrate des Trägers um 35%. Wenn der Träger Gegner mit reduzierter VTD angreift, wird 7 Pkt. Energie wiederhergestellt.", "Erhöht die Effekt-Trefferrate des Trägers um 40%. Wenn der Träger Gegner mit reduzierter VTD angreift, wird 8 Pkt. Energie wiederhergestellt."]}'),
  ('Bezaubert von einer blumigen Welt', 'Das Hochgefühl', 5, 'assets/images/light_cones/dazzled_by_a_flowery_world.png', '{"name": "Blickfang", "text": ["Erhöht den KRIT-SCH des Trägers um 48%. Wenn sich der Träger auf dem Kampffeld befindet, werden die max. Fertigkeitspunkte für jede Figur auf dem Pfad des Hochgefühls im Team um 1 Pkt. erhöht, bis zu einer Erhöhung von 3 Pkt. Für jeden Fertigkeitspunkt, den der Träger verbraucht, ignoriert der von ihm verursachte Hochgefühl-SCH 5% der VTD des Gegners. Dieser Effekt ist bis zu 4-fach stapelbar. Werden in derselben Runde mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger „Streamwerbung“. Wenn der Träger Streamwerbung besitzt, wird das Hochgefühl aller Verbündeten um 20% erhöht. Lichtkegel-Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 56%. Wenn sich der Träger auf dem Kampffeld befindet, werden die max. Fertigkeitspunkte für jede Figur auf dem Pfad des Hochgefühls im Team um 1 Pkt. erhöht, bis zu einer Erhöhung von 3 Pkt. Für jeden Fertigkeitspunkt, den der Träger verbraucht, ignoriert der von ihm verursachte Hochgefühl-SCH 6% der VTD des Gegners. Dieser Effekt ist bis zu 4-fach stapelbar. Werden in derselben Runde mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger „Streamwerbung“. Wenn der Träger Streamwerbung besitzt, wird das Hochgefühl aller Verbündeten um 24% erhöht. Lichtkegel-Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 64%. Wenn sich der Träger auf dem Kampffeld befindet, werden die max. Fertigkeitspunkte für jede Figur auf dem Pfad des Hochgefühls im Team um 1 Pkt. erhöht, bis zu einer Erhöhung von 3 Pkt. Für jeden Fertigkeitspunkt, den der Träger verbraucht, ignoriert der von ihm verursachte Hochgefühl-SCH 7% der VTD des Gegners. Dieser Effekt ist bis zu 4-fach stapelbar. Werden in derselben Runde mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger „Streamwerbung“. Wenn der Träger Streamwerbung besitzt, wird das Hochgefühl aller Verbündeten um 28% erhöht. Lichtkegel-Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 72%. Wenn sich der Träger auf dem Kampffeld befindet, werden die max. Fertigkeitspunkte für jede Figur auf dem Pfad des Hochgefühls im Team um 1 Pkt. erhöht, bis zu einer Erhöhung von 3 Pkt. Für jeden Fertigkeitspunkt, den der Träger verbraucht, ignoriert der von ihm verursachte Hochgefühl-SCH 8% der VTD des Gegners. Dieser Effekt ist bis zu 4-fach stapelbar. Werden in derselben Runde mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger „Streamwerbung“. Wenn der Träger Streamwerbung besitzt, wird das Hochgefühl aller Verbündeten um 32% erhöht. Lichtkegel-Effekte desselben Typs sind nicht stapelbar.", "Erhöht den KRIT-SCH des Trägers um 80%. Wenn sich der Träger auf dem Kampffeld befindet, werden die max. Fertigkeitspunkte für jede Figur auf dem Pfad des Hochgefühls im Team um 1 Pkt. erhöht, bis zu einer Erhöhung von 3 Pkt. Für jeden Fertigkeitspunkt, den der Träger verbraucht, ignoriert der von ihm verursachte Hochgefühl-SCH 9% der VTD des Gegners. Dieser Effekt ist bis zu 4-fach stapelbar. Werden in derselben Runde mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger „Streamwerbung“. Wenn der Träger Streamwerbung besitzt, wird das Hochgefühl aller Verbündeten um 36% erhöht. Lichtkegel-Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Bis zum Übermorgen', 'Der Überfluss', 4, 'assets/images/light_cones/unto_tomorrow_s_morrow.png', '{"name": "Lebwohl", "text": ["Erhöht die bewirkte Heilung des Trägers um 12%. Wenn der LP-Prozentsatz eines Verbündeten bei 50% oder höher liegt, wird der verursachte SCH um 12% erhöht.", "Erhöht die bewirkte Heilung des Trägers um 15%. Wenn der LP-Prozentsatz eines Verbündeten bei 50% oder höher liegt, wird der verursachte SCH um 14% erhöht.", "Erhöht die bewirkte Heilung des Trägers um 18%. Wenn der LP-Prozentsatz eines Verbündeten bei 50% oder höher liegt, wird der verursachte SCH um 16% erhöht.", "Erhöht die bewirkte Heilung des Trägers um 21%. Wenn der LP-Prozentsatz eines Verbündeten bei 50% oder höher liegt, wird der verursachte SCH um 18% erhöht.", "Erhöht die bewirkte Heilung des Trägers um 24%. Wenn der LP-Prozentsatz eines Verbündeten bei 50% oder höher liegt, wird der verursachte SCH um 20% erhöht."]}'),
  ('Blutzeichen aus der Vergangenheit', 'Die Zerstörung', 4, 'assets/images/light_cones/a_trail_of_bygone_blood.png', '{"name": "Blutbad", "text": ["Erhöht die KRIT-Rate des Trägers um 12%. Erhöht den verursachten Fertigkeits- und Ultimate-SCH des Trägers um 24%.", "Erhöht die KRIT-Rate des Trägers um 14%. Erhöht den verursachten Fertigkeits- und Ultimate-SCH des Trägers um 28%.", "Erhöht die KRIT-Rate des Trägers um 16%. Erhöht den verursachten Fertigkeits- und Ultimate-SCH des Trägers um 32%.", "Erhöht die KRIT-Rate des Trägers um 18%. Erhöht den verursachten Fertigkeits- und Ultimate-SCH des Trägers um 36%.", "Erhöht die KRIT-Rate des Trägers um 20%. Erhöht den verursachten Fertigkeits- und Ultimate-SCH des Trägers um 40%."]}'),
  ('Brennender Schatten', 'Das Gedenken', 3, 'assets/images/light_cones/shadowburn.png', '{"name": "Verschönerung", "text": ["Stellt 1 Fertigkeitspunkt und 12 Pkt. der Energie des Trägers wieder her, wenn er zum ersten Mal einen Memogeist beschwört.", "Stellt 1 Fertigkeitspunkt und 14 Pkt. der Energie des Trägers wieder her, wenn er zum ersten Mal einen Memogeist beschwört.", "Stellt 1 Fertigkeitspunkt und 16 Pkt. der Energie des Trägers wieder her, wenn er zum ersten Mal einen Memogeist beschwört.", "Stellt 1 Fertigkeitspunkt und 18 Pkt. der Energie des Trägers wieder her, wenn er zum ersten Mal einen Memogeist beschwört.", "Stellt 1 Fertigkeitspunkt und 20 Pkt. der Energie des Trägers wieder her, wenn er zum ersten Mal einen Memogeist beschwört."]}'),
  ('Chor', 'Die Harmonie', 3, 'assets/images/light_cones/chorus.png', '{"name": "Vereint", "text": ["Erhöht nach Kampfeintritt den ANG aller Verbündeten um 8%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den ANG aller Verbündeten um 9%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den ANG aller Verbündeten um 10%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den ANG aller Verbündeten um 11%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht nach Kampfeintritt den ANG aller Verbündeten um 12%. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Das Finale einer Lüge', 'Die Jagd', 5, 'assets/images/light_cones/the_finale_of_a_lie.png', '{"name": "Verschlingen", "text": ["Erhöht die KRIT-Rate des Trägers um 18%. Zu Beginn des Kampfes oder jedes Mal, nachdem der Träger 4-mal einen Folgeangriff ausgeführt hat, erhält er für 3 Rd. „Schattenverschlinger“. Wenn der Träger Schattenverschlinger besitzt, wird sein ANG um 40% und der von allen Gegnern erlittene SCH um 20% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 21%. Zu Beginn des Kampfes oder jedes Mal, nachdem der Träger 4-mal einen Folgeangriff ausgeführt hat, erhält er für 3 Rd. „Schattenverschlinger“. Wenn der Träger Schattenverschlinger besitzt, wird sein ANG um 50% und der von allen Gegnern erlittene SCH um 23% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 24%. Zu Beginn des Kampfes oder jedes Mal, nachdem der Träger 4-mal einen Folgeangriff ausgeführt hat, erhält er für 3 Rd. „Schattenverschlinger“. Wenn der Träger Schattenverschlinger besitzt, wird sein ANG um 60% und der von allen Gegnern erlittene SCH um 25% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 27%. Zu Beginn des Kampfes oder jedes Mal, nachdem der Träger 4-mal einen Folgeangriff ausgeführt hat, erhält er für 3 Rd. „Schattenverschlinger“. Wenn der Träger Schattenverschlinger besitzt, wird sein ANG um 70% und der von allen Gegnern erlittene SCH um 28% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 30%. Zu Beginn des Kampfes oder jedes Mal, nachdem der Träger 4-mal einen Folgeangriff ausgeführt hat, erhält er für 3 Rd. „Schattenverschlinger“. Wenn der Träger Schattenverschlinger besitzt, wird sein ANG um 80% und der von allen Gegnern erlittene SCH um 30% erhöht. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Das Ich im Spiegel', 'Die Harmonie', 5, 'assets/images/light_cones/past_self_in_mirror.png', '{"name": "Pflaumenduft", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte SCH aller Verbündeten für 3 Rd. um 24% erhöht. Wenn der Brucheffekt des Trägers 150% oder mehr beträgt, wird 1 Fertigkeitspunkt wiederhergestellt.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten 10 Pkt. Energie wiederhergestellt. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 70%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte SCH aller Verbündeten für 3 Rd. um 28% erhöht. Wenn der Brucheffekt des Trägers 150% oder mehr beträgt, wird 1 Fertigkeitspunkt wiederhergestellt.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten 12,5 Pkt. Energie wiederhergestellt. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 80%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte SCH aller Verbündeten für 3 Rd. um 32% erhöht. Wenn der Brucheffekt des Trägers 150% oder mehr beträgt, wird 1 Fertigkeitspunkt wiederhergestellt.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten 15 Pkt. Energie wiederhergestellt. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 90%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte SCH aller Verbündeten für 3 Rd. um 36% erhöht. Wenn der Brucheffekt des Trägers 150% oder mehr beträgt, wird 1 Fertigkeitspunkt wiederhergestellt.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten 17,5 Pkt. Energie wiederhergestellt. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 100%. Wenn der Träger seinen Ultimate einsetzt, wird der verursachte SCH aller Verbündeten für 3 Rd. um 40% erhöht. Wenn der Brucheffekt des Trägers 150% oder mehr beträgt, wird 1 Fertigkeitspunkt wiederhergestellt.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten 20 Pkt. Energie wiederhergestellt. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Das Leben sollte in Flammen aufgehen', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/life_should_be_cast_to_flames.png', '{"name": "Schmelzen", "text": ["Der Träger stellt zu Beginn der Runde 10 Pkt. Energie wieder her. Wenn ein Gegner eine vom Träger implantierte Schwäche besitzt, wird der ihm zugefügte SCH durch den Träger um 60% erhöht.\\nWenn ein Gegner vom Träger angegriffen wird, verringert der Träger seine VTD für 2 Rd. um 12%. Effekte der gleichen Art sind nicht stapelbar.", "Der Träger stellt zu Beginn der Runde 10 Pkt. Energie wieder her. Wenn ein Gegner eine vom Träger implantierte Schwäche besitzt, wird der ihm zugefügte SCH durch den Träger um 70% erhöht.\\nWenn ein Gegner vom Träger angegriffen wird, verringert der Träger seine VTD für 2 Rd. um 15%. Effekte der gleichen Art sind nicht stapelbar.", "Der Träger stellt zu Beginn der Runde 10 Pkt. Energie wieder her. Wenn ein Gegner eine vom Träger implantierte Schwäche besitzt, wird der ihm zugefügte SCH durch den Träger um 80% erhöht.\\nWenn ein Gegner vom Träger angegriffen wird, verringert der Träger seine VTD für 2 Rd. um 18%. Effekte der gleichen Art sind nicht stapelbar.", "Der Träger stellt zu Beginn der Runde 10 Pkt. Energie wieder her. Wenn ein Gegner eine vom Träger implantierte Schwäche besitzt, wird der ihm zugefügte SCH durch den Träger um 90% erhöht.\\nWenn ein Gegner vom Träger angegriffen wird, verringert der Träger seine VTD für 2 Rd. um 21%. Effekte der gleichen Art sind nicht stapelbar.", "Der Träger stellt zu Beginn der Runde 10 Pkt. Energie wieder her. Wenn ein Gegner eine vom Träger implantierte Schwäche besitzt, wird der ihm zugefügte SCH durch den Träger um 100% erhöht.\\nWenn ein Gegner vom Träger angegriffen wird, verringert der Träger seine VTD für 2 Rd. um 24%. Effekte der gleichen Art sind nicht stapelbar."]}'),
  ('Das bin ich!', 'Die Bewahrung', 4, 'assets/images/light_cones/this_is_me.png', '{"name": "Neues Kapitel", "text": ["Erhöht die VTD des Trägers um 16%. Erhöht den durch Ultimate verursachten SCH um 60% seiner VTD. Dieser Effekt wird bei jedem Einsatz des Ultimates nur 1-mal pro gegnerischem Ziel wirksam.", "Erhöht die VTD des Trägers um 20%. Erhöht den durch Ultimate verursachten SCH um 75% seiner VTD. Dieser Effekt wird bei jedem Einsatz des Ultimates nur 1-mal pro gegnerischem Ziel wirksam.", "Erhöht die VTD des Trägers um 24%. Erhöht den durch Ultimate verursachten SCH um 90% seiner VTD. Dieser Effekt wird bei jedem Einsatz des Ultimates nur 1-mal pro gegnerischem Ziel wirksam.", "Erhöht die VTD des Trägers um 28%. Erhöht den durch Ultimate verursachten SCH um 105% seiner VTD. Dieser Effekt wird bei jedem Einsatz des Ultimates nur 1-mal pro gegnerischem Ziel wirksam.", "Erhöht die VTD des Trägers um 32%. Erhöht den durch Ultimate verursachten SCH um 120% seiner VTD. Dieser Effekt wird bei jedem Einsatz des Ultimates nur 1-mal pro gegnerischem Ziel wirksam."]}'),
  ('Das große kosmische Geschäft', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/the_great_cosmic_enterprise.png', '{"name": "Gegenseitiger Nutzen", "text": ["Erhöht den ANG des Trägers um 8%. Für jede Schwäche des Gegners eines anderen Typs wird der ihm zugefügte SCH durch den Träger um 4% erhöht, bis zu 7 Schwächetypen.", "Erhöht den ANG des Trägers um 10%. Für jede Schwäche des Gegners eines anderen Typs wird der ihm zugefügte SCH durch den Träger um 5% erhöht, bis zu 7 Schwächetypen.", "Erhöht den ANG des Trägers um 12%. Für jede Schwäche des Gegners eines anderen Typs wird der ihm zugefügte SCH durch den Träger um 6% erhöht, bis zu 7 Schwächetypen.", "Erhöht den ANG des Trägers um 14%. Für jede Schwäche des Gegners eines anderen Typs wird der ihm zugefügte SCH durch den Träger um 7% erhöht, bis zu 7 Schwächetypen.", "Erhöht den ANG des Trägers um 16%. Für jede Schwäche des Gegners eines anderen Typs wird der ihm zugefügte SCH durch den Träger um 8% erhöht, bis zu 7 Schwächetypen."]}'),
  ('Datenbank', 'Die Gelehrsamkeit', 3, 'assets/images/light_cones/data_bank.png', '{"name": "Gelehrt", "text": ["Erhöht den durch den Ultimate des Trägers verursachten SCH um 28%.", "Erhöht den durch den Ultimate des Trägers verursachten SCH um 35%.", "Erhöht den durch den Ultimate des Trägers verursachten SCH um 42%.", "Erhöht den durch den Ultimate des Trägers verursachten SCH um 49%.", "Erhöht den durch den Ultimate des Trägers verursachten SCH um 56%."]}'),
  ('Den Mond schnitzen, die Wolken weben', 'Die Harmonie', 4, 'assets/images/light_cones/carve_the_moon_weave_the_clouds.png', '{"name": "Geheimnis", "text": ["Zu Beginn des Kampfes und zu Beginn der Runde des Trägers wird zufällig einer der folgenden Effekte ausgelöst: Erhöht den ANG aller Verbündeten um 10%; Erhöht den KRIT-SCH aller Verbündeten um 12%; Erhöht die Energie-Regenerationsrate aller Verbündeten um 6%. Der ausgelöste Effekt kann nicht mit dem zuletzt ausgelösten Effekt identisch sein und ersetzt den vorherigen Effekt. Effekte der gleichen Art sind nicht stapelbar. Der Effekt wird entfernt, wenn der Träger handlungsunfähig ist.", "Zu Beginn des Kampfes und zu Beginn der Runde des Trägers wird zufällig einer der folgenden Effekte ausgelöst: Erhöht den ANG aller Verbündeten um 13%; Erhöht den KRIT-SCH aller Verbündeten um 15%; Erhöht die Energie-Regenerationsrate aller Verbündeten um 8%. Der ausgelöste Effekt kann nicht mit dem zuletzt ausgelösten Effekt identisch sein und ersetzt den vorherigen Effekt. Effekte der gleichen Art sind nicht stapelbar. Der Effekt wird entfernt, wenn der Träger handlungsunfähig ist.", "Zu Beginn des Kampfes und zu Beginn der Runde des Trägers wird zufällig einer der folgenden Effekte ausgelöst: Erhöht den ANG aller Verbündeten um 15%; Erhöht den KRIT-SCH aller Verbündeten um 18%; Erhöht die Energie-Regenerationsrate aller Verbündeten um 9%. Der ausgelöste Effekt kann nicht mit dem zuletzt ausgelösten Effekt identisch sein und ersetzt den vorherigen Effekt. Effekte der gleichen Art sind nicht stapelbar. Der Effekt wird entfernt, wenn der Träger handlungsunfähig ist.", "Zu Beginn des Kampfes und zu Beginn der Runde des Trägers wird zufällig einer der folgenden Effekte ausgelöst: Erhöht den ANG aller Verbündeten um 18%; Erhöht den KRIT-SCH aller Verbündeten um 21%; Erhöht die Energie-Regenerationsrate aller Verbündeten um 11%. Der ausgelöste Effekt kann nicht mit dem zuletzt ausgelösten Effekt identisch sein und ersetzt den vorherigen Effekt. Effekte der gleichen Art sind nicht stapelbar. Der Effekt wird entfernt, wenn der Träger handlungsunfähig ist.", "Zu Beginn des Kampfes und zu Beginn der Runde des Trägers wird zufällig einer der folgenden Effekte ausgelöst: Erhöht den ANG aller Verbündeten um 20%; Erhöht den KRIT-SCH aller Verbündeten um 24%; Erhöht die Energie-Regenerationsrate aller Verbündeten um 12%. Der ausgelöste Effekt kann nicht mit dem zuletzt ausgelösten Effekt identisch sein und ersetzt den vorherigen Effekt. Effekte der gleichen Art sind nicht stapelbar. Der Effekt wird entfernt, wenn der Träger handlungsunfähig ist."]}'),
  ('Der Entschluss zu sehen', 'Das Hochgefühl', 5, 'assets/images/light_cones/when_she_decided_to_see.png', '{"name": "Wendepunkt", "text": ["Erhöht die GES des Trägers um 18%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate auf Verbündete einsetzt, erhält er für 3 Rd. „Großes Glück“. Während der Träger Großes Glück besitzt, wird die KRIT-Rate aller Verbündeten um 10%, der KRIT-SCH um 30% und die Energie-Wiederherstellungsrate des Trägers um 12% erhöht.\\nZu Beginn jeder Kampfwelle stellt der Träger eine feste Anzahl von 15 Pkt. Energie wieder her.", "Erhöht die GES des Trägers um 21%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate auf Verbündete einsetzt, erhält er für 3 Rd. „Großes Glück“. Während der Träger Großes Glück besitzt, wird die KRIT-Rate aller Verbündeten um 11%, der KRIT-SCH um 38% und die Energie-Wiederherstellungsrate des Trägers um 14% erhöht.\\nZu Beginn jeder Kampfwelle stellt der Träger eine feste Anzahl von 15 Pkt. Energie wieder her.", "Erhöht die GES des Trägers um 24%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate auf Verbündete einsetzt, erhält er für 3 Rd. „Großes Glück“. Während der Träger Großes Glück besitzt, wird die KRIT-Rate aller Verbündeten um 12%, der KRIT-SCH um 45% und die Energie-Wiederherstellungsrate des Trägers um 16% erhöht.\\nZu Beginn jeder Kampfwelle stellt der Träger eine feste Anzahl von 15 Pkt. Energie wieder her.", "Erhöht die GES des Trägers um 27%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate auf Verbündete einsetzt, erhält er für 3 Rd. „Großes Glück“. Während der Träger Großes Glück besitzt, wird die KRIT-Rate aller Verbündeten um 13%, der KRIT-SCH um 53% und die Energie-Wiederherstellungsrate des Trägers um 18% erhöht.\\nZu Beginn jeder Kampfwelle stellt der Träger eine feste Anzahl von 15 Pkt. Energie wieder her.", "Erhöht die GES des Trägers um 30%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate auf Verbündete einsetzt, erhält er für 3 Rd. „Großes Glück“. Während der Träger Großes Glück besitzt, wird die KRIT-Rate aller Verbündeten um 14%, der KRIT-SCH um 60% und die Energie-Wiederherstellungsrate des Trägers um 20% erhöht.\\nZu Beginn jeder Kampfwelle stellt der Träger eine feste Anzahl von 15 Pkt. Energie wieder her."]}'),
  ('Der Gruß der Genies', 'Das Gedenken', 4, 'assets/images/light_cones/geniuses_greetings.png', '{"name": "Glückwunsch", "text": ["Erhöht den ANG des Trägers um 16%. Nachdem er seinen Ultimate eingesetzt hat, wird der verursachte Standardangriff-SCH des Trägers und des Memogeists für 3 Rd. um 20% erhöht.", "Erhöht den ANG des Trägers um 20%. Nachdem er seinen Ultimate eingesetzt hat, wird der verursachte Standardangriff-SCH des Trägers und des Memogeists für 3 Rd. um 25% erhöht.", "Erhöht den ANG des Trägers um 24%. Nachdem er seinen Ultimate eingesetzt hat, wird der verursachte Standardangriff-SCH des Trägers und des Memogeists für 3 Rd. um 30% erhöht.", "Erhöht den ANG des Trägers um 28%. Nachdem er seinen Ultimate eingesetzt hat, wird der verursachte Standardangriff-SCH des Trägers und des Memogeists für 3 Rd. um 35% erhöht.", "Erhöht den ANG des Trägers um 32%. Nachdem er seinen Ultimate eingesetzt hat, wird der verursachte Standardangriff-SCH des Trägers und des Memogeists für 3 Rd. um 40% erhöht."]}'),
  ('Der Kampf ist nicht vorbei', 'Die Harmonie', 5, 'assets/images/light_cones/but_the_battle_isn_t_over.png', '{"name": "Erbin", "text": ["Erhöht die Energie-Wiederherstellungsrate des Trägers um 10% und stellt beim Einsatz des Ultimates auf Verbündete 1 Fertigkeitspunkt wieder her. Dieser Effekt kann nach jeweils 2 Einsätzen des Ultimates ausgelöst werden. Nach dem Einsatz der Fertigkeit wird der verursachte SCH des Verbündeten, der als nächstes eine Aktion ausführt (außer dem Träger), für 1 Rd. um 30% erhöht.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 12% und stellt beim Einsatz des Ultimates auf Verbündete 1 Fertigkeitspunkt wieder her. Dieser Effekt kann nach jeweils 2 Einsätzen des Ultimates ausgelöst werden. Nach dem Einsatz der Fertigkeit wird der verursachte SCH des Verbündeten, der als nächstes eine Aktion ausführt (außer dem Träger), für 1 Rd. um 35% erhöht.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 14% und stellt beim Einsatz des Ultimates auf Verbündete 1 Fertigkeitspunkt wieder her. Dieser Effekt kann nach jeweils 2 Einsätzen des Ultimates ausgelöst werden. Nach dem Einsatz der Fertigkeit wird der verursachte SCH des Verbündeten, der als nächstes eine Aktion ausführt (außer dem Träger), für 1 Rd. um 40% erhöht.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 16% und stellt beim Einsatz des Ultimates auf Verbündete 1 Fertigkeitspunkt wieder her. Dieser Effekt kann nach jeweils 2 Einsätzen des Ultimates ausgelöst werden. Nach dem Einsatz der Fertigkeit wird der verursachte SCH des Verbündeten, der als nächstes eine Aktion ausführt (außer dem Träger), für 1 Rd. um 45% erhöht.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 18% und stellt beim Einsatz des Ultimates auf Verbündete 1 Fertigkeitspunkt wieder her. Dieser Effekt kann nach jeweils 2 Einsätzen des Ultimates ausgelöst werden. Nach dem Einsatz der Fertigkeit wird der verursachte SCH des Verbündeten, der als nächstes eine Aktion ausführt (außer dem Träger), für 1 Rd. um 50% erhöht."]}'),
  ('Der Niedergang eines Äons', 'Die Zerstörung', 5, 'assets/images/light_cones/on_the_fall_of_an_aeon.png', '{"name": "Wie Motten ins Licht", "text": ["Wenn der Träger angreift, wird sein ANG im Kampf um 8% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar. Verursacht der Träger Schwächebruch an einem Gegner, wird sein verursachter SCH für 2 Rd. um 12% erhöht.", "Wenn der Träger angreift, wird sein ANG im Kampf um 10% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar. Verursacht der Träger Schwächebruch an einem Gegner, wird sein verursachter SCH für 2 Rd. um 15% erhöht.", "Wenn der Träger angreift, wird sein ANG im Kampf um 12% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar. Verursacht der Träger Schwächebruch an einem Gegner, wird sein verursachter SCH für 2 Rd. um 18% erhöht.", "Wenn der Träger angreift, wird sein ANG im Kampf um 14% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar. Verursacht der Träger Schwächebruch an einem Gegner, wird sein verursachter SCH für 2 Rd. um 21% erhöht.", "Wenn der Träger angreift, wird sein ANG im Kampf um 16% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar. Verursacht der Träger Schwächebruch an einem Gegner, wird sein verursachter SCH für 2 Rd. um 24% erhöht."]}'),
  ('Der Vorhang der Erinnerung fällt nie', 'Das Gedenken', 5, 'assets/images/light_cones/memory_s_curtain_never_falls.png', '{"name": "Empfang", "text": ["Erhöht die GES des Trägers um 6%. Nach dem Einsatz der Fertigkeit des Trägers wird der verursachte SCH aller Verbündeten für 3 Rd. um 8% erhöht.", "Erhöht die GES des Trägers um 7,5%. Nach dem Einsatz der Fertigkeit des Trägers wird der verursachte SCH aller Verbündeten für 3 Rd. um 10% erhöht.", "Erhöht die GES des Trägers um 9%. Nach dem Einsatz der Fertigkeit des Trägers wird der verursachte SCH aller Verbündeten für 3 Rd. um 12% erhöht.", "Erhöht die GES des Trägers um 10,5%. Nach dem Einsatz der Fertigkeit des Trägers wird der verursachte SCH aller Verbündeten für 3 Rd. um 14% erhöht.", "Erhöht die GES des Trägers um 12%. Nach dem Einsatz der Fertigkeit des Trägers wird der verursachte SCH aller Verbündeten für 3 Rd. um 16% erhöht."]}'),
  ('Der erste Tag meines neuen Lebens', 'Die Bewahrung', 4, 'assets/images/light_cones/day_one_of_my_new_life.png', '{"name": "Genau in diesem Moment", "text": ["Erhöht die VTD des Trägers um 16%. Erhöht nach Kampfeintritt den WDS aller Typen von allen Verbündeten um 8%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die VTD des Trägers um 18%. Erhöht nach Kampfeintritt den WDS aller Typen von allen Verbündeten um 9%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die VTD des Trägers um 20%. Erhöht nach Kampfeintritt den WDS aller Typen von allen Verbündeten um 10%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die VTD des Trägers um 22%. Erhöht nach Kampfeintritt den WDS aller Typen von allen Verbündeten um 11%. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die VTD des Trägers um 24%. Erhöht nach Kampfeintritt den WDS aller Typen von allen Verbündeten um 12%. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Die Abenteuer des pilzigen Pilzes', 'Das Hochgefühl', 4, 'assets/images/light_cones/mushy_shroomy_s_adventures.png', '{"name": "Kampfchaos", "text": ["Erhöht das Hochgefühl des Trägers um 12%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird der erlittene Hochgefühl-SCH aller Gegner für 2 Rd. um 6% erhöht.", "Erhöht das Hochgefühl des Trägers um 14%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird der erlittene Hochgefühl-SCH aller Gegner für 2 Rd. um 7% erhöht.", "Erhöht das Hochgefühl des Trägers um 16%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird der erlittene Hochgefühl-SCH aller Gegner für 2 Rd. um 8% erhöht.", "Erhöht das Hochgefühl des Trägers um 18%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird der erlittene Hochgefühl-SCH aller Gegner für 2 Rd. um 9% erhöht.", "Erhöht das Hochgefühl des Trägers um 20%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird der erlittene Hochgefühl-SCH aller Gegner für 2 Rd. um 10% erhöht."]}'),
  ('Die Augen der Beute', 'Die Nichtigkeit', 4, 'assets/images/light_cones/eyes_of_the_prey.png', '{"name": "Selbstvertrauen", "text": ["Erhöht die Effekt-Trefferrate des Trägers um 20% und den verursachten DoT um 24%.", "Erhöht die Effekt-Trefferrate des Trägers um 25% und den verursachten DoT um 30%.", "Erhöht die Effekt-Trefferrate des Trägers um 30% und den verursachten DoT um 36%.", "Erhöht die Effekt-Trefferrate des Trägers um 35% und den verursachten DoT um 42%.", "Erhöht die Effekt-Trefferrate des Trägers um 40% und den verursachten DoT um 48%."]}'),
  ('Die Blumen werden nicht vergessen', 'Das Gedenken', 4, 'assets/images/light_cones/the_flower_remembers.png', '{"name": "Gegenseitige Abhängigkeit", "text": ["Erhöht den KRIT-SCH des Trägers um 24%. Erhöht den KRIT-SCH des Memogeists des Trägers zusätzlich um 24%.", "Erhöht den KRIT-SCH des Trägers um 28%. Erhöht den KRIT-SCH des Memogeists des Trägers zusätzlich um 30%.", "Erhöht den KRIT-SCH des Trägers um 32%. Erhöht den KRIT-SCH des Memogeists des Trägers zusätzlich um 36%.", "Erhöht den KRIT-SCH des Trägers um 36%. Erhöht den KRIT-SCH des Memogeists des Trägers zusätzlich um 42%.", "Erhöht den KRIT-SCH des Trägers um 40%. Erhöht den KRIT-SCH des Memogeists des Trägers zusätzlich um 48%."]}'),
  ('Die Entschlusskraft glitzert als Schweißperlen', 'Die Nichtigkeit', 4, 'assets/images/light_cones/resolution_shines_as_pearls_of_sweat.png', '{"name": "Zurückblicken", "text": ["Beim Treffer eines nicht verstrickten Gegners besteht eine Grundchance von 60%, dem Ziel Verstrickung zu verursachen. Die VTD des verstrickten Gegners wird für 1 Rd. um 12% reduziert.", "Beim Treffer eines nicht verstrickten Gegners besteht eine Grundchance von 70%, dem Ziel Verstrickung zu verursachen. Die VTD des verstrickten Gegners wird für 1 Rd. um 13% reduziert.", "Beim Treffer eines nicht verstrickten Gegners besteht eine Grundchance von 80%, dem Ziel Verstrickung zu verursachen. Die VTD des verstrickten Gegners wird für 1 Rd. um 14% reduziert.", "Beim Treffer eines nicht verstrickten Gegners besteht eine Grundchance von 90%, dem Ziel Verstrickung zu verursachen. Die VTD des verstrickten Gegners wird für 1 Rd. um 15% reduziert.", "Beim Treffer eines nicht verstrickten Gegners besteht eine Grundchance von 100%, dem Ziel Verstrickung zu verursachen. Die VTD des verstrickten Gegners wird für 1 Rd. um 16% reduziert."]}'),
  ('Die Ernsthaftigkeit des Frühstücks', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/the_seriousness_of_breakfast.png', '{"name": "Mach dich bereit", "text": ["Erhöht den SCH des Trägers um 12%. Für jeden besiegten Gegner wird der ANG des Trägers um 4% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar.", "Erhöht den SCH des Trägers um 15%. Für jeden besiegten Gegner wird der ANG des Trägers um 5% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar.", "Erhöht den SCH des Trägers um 18%. Für jeden besiegten Gegner wird der ANG des Trägers um 6% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar.", "Erhöht den SCH des Trägers um 21%. Für jeden besiegten Gegner wird der ANG des Trägers um 7% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar.", "Erhöht den SCH des Trägers um 24%. Für jeden besiegten Gegner wird der ANG des Trägers um 8% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar."]}'),
  ('Die Geburt des Selbst', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/the_birth_of_the_self.png', '{"name": "Die Jungfrau im Gemälde", "text": ["Erhöht den durch Folgeangriffe verursachten SCH des Trägers um 24%. Liegt der LP-Prozentsatz des Ziels aktuell bei 50% oder niedriger, wird der durch Folgeangriffe verursachte SCH zusätzlich um 24% erhöht.", "Erhöht den durch Folgeangriffe verursachten SCH des Trägers um 30%. Liegt der LP-Prozentsatz des Ziels aktuell bei 50% oder niedriger, wird der durch Folgeangriffe verursachte SCH zusätzlich um 30% erhöht.", "Erhöht den durch Folgeangriffe verursachten SCH des Trägers um 36%. Liegt der LP-Prozentsatz des Ziels aktuell bei 50% oder niedriger, wird der durch Folgeangriffe verursachte SCH zusätzlich um 36% erhöht.", "Erhöht den durch Folgeangriffe verursachten SCH des Trägers um 42%. Liegt der LP-Prozentsatz des Ziels aktuell bei 50% oder niedriger, wird der durch Folgeangriffe verursachte SCH zusätzlich um 42% erhöht.", "Erhöht den durch Folgeangriffe verursachten SCH des Trägers um 48%. Liegt der LP-Prozentsatz des Ziels aktuell bei 50% oder niedriger, wird der durch Folgeangriffe verursachte SCH zusätzlich um 48% erhöht."]}'),
  ('Die Maulwürfe heißen dich willkommen', 'Die Zerstörung', 4, 'assets/images/light_cones/the_moles_welcome_you.png', '{"name": "Fantastisches Abenteuer", "text": ["Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates erhält der Träger jeweils 1 Stapelung Schelmisch. Für jede Stapelung wird ANG des Trägers um 12% erhöht.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates erhält der Träger jeweils 1 Stapelung Schelmisch. Für jede Stapelung wird ANG des Trägers um 15% erhöht.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates erhält der Träger jeweils 1 Stapelung Schelmisch. Für jede Stapelung wird ANG des Trägers um 18% erhöht.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates erhält der Träger jeweils 1 Stapelung Schelmisch. Für jede Stapelung wird ANG des Trägers um 21% erhöht.", "Nach dem Einsatz des Standardangriffs, der Fertigkeit oder des Ultimates erhält der Träger jeweils 1 Stapelung Schelmisch. Für jede Stapelung wird ANG des Trägers um 24% erhöht."]}'),
  ('Die Nacht der langen Schatten', 'Die Jagd', 4, 'assets/images/light_cones/shadowed_by_night.png', '{"name": "Verstecken", "text": ["Erhöht den Brucheffekt des Trägers um 28%. Beim Kampfeintritt oder nach dem Verursachen von Bruch-SCH wird die GES für 2 Rd. um 8% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 35%. Beim Kampfeintritt oder nach dem Verursachen von Bruch-SCH wird die GES für 2 Rd. um 9% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 42%. Beim Kampfeintritt oder nach dem Verursachen von Bruch-SCH wird die GES für 2 Rd. um 10% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 49%. Beim Kampfeintritt oder nach dem Verursachen von Bruch-SCH wird die GES für 2 Rd. um 11% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 56%. Beim Kampfeintritt oder nach dem Verursachen von Bruch-SCH wird die GES für 2 Rd. um 12% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Die Rast der Genies', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/geniuses_repose.png', '{"name": "Jeder muss jetzt eine Rolle spielen", "text": ["Erhöht den ANG des Trägers um 16%. Besiegt der Träger einen Gegner, wird sein KRIT-SCH für 3 Rd. um 24% erhöht.", "Erhöht den ANG des Trägers um 20%. Besiegt der Träger einen Gegner, wird sein KRIT-SCH für 3 Rd. um 30% erhöht.", "Erhöht den ANG des Trägers um 24%. Besiegt der Träger einen Gegner, wird sein KRIT-SCH für 3 Rd. um 36% erhöht.", "Erhöht den ANG des Trägers um 28%. Besiegt der Träger einen Gegner, wird sein KRIT-SCH für 3 Rd. um 42% erhöht.", "Erhöht den ANG des Trägers um 32%. Besiegt der Träger einen Gegner, wird sein KRIT-SCH für 3 Rd. um 48% erhöht."]}'),
  ('Die Welt in Aufruhr versetzen', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/make_the_world_clamor.png', '{"name": "Die Macht des Klangs", "text": ["Stellt beim Kampfeintritt sofort 20 Pkt. Energie des Trägers wieder her und erhöht den durch Ultimates verursachten SCH um 32%.", "Stellt beim Kampfeintritt sofort 23 Pkt. Energie des Trägers wieder her und erhöht den durch Ultimates verursachten SCH um 40%.", "Stellt beim Kampfeintritt sofort 26 Pkt. Energie des Trägers wieder her und erhöht den durch Ultimates verursachten SCH um 48%.", "Stellt beim Kampfeintritt sofort 29 Pkt. Energie des Trägers wieder her und erhöht den durch Ultimates verursachten SCH um 56%.", "Stellt beim Kampfeintritt sofort 32 Pkt. Energie des Trägers wieder her und erhöht den durch Ultimates verursachten SCH um 64%."]}'),
  ('Die Zeit wartet auf niemanden', 'Der Überfluss', 5, 'assets/images/light_cones/time_waits_for_no_one.png', '{"name": "Morgens, mittags, abends und nachts", "text": ["Erhöht die max. LP des Trägers um 18% und seine bewirkte Heilung um 12%. Wenn der Träger Verbündete heilt, wird die bewirkte Heilung gespeichert. Wenn ein Verbündeter angreift, erleidet ein zufällig angegriffener Gegner zusätzlichen SCH in Höhe von 36% der gespeicherten bewirkten Heilung. Dieser zusätzliche SCH ist desselben Typs wie der SCH des Trägers, wird nicht von anderen Buffs beeinflusst und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 21% und seine bewirkte Heilung um 14%. Wenn der Träger Verbündete heilt, wird die bewirkte Heilung gespeichert. Wenn ein Verbündeter angreift, erleidet ein zufällig angegriffener Gegner zusätzlichen SCH in Höhe von 42% der gespeicherten bewirkten Heilung. Dieser zusätzliche SCH ist desselben Typs wie der SCH des Trägers, wird nicht von anderen Buffs beeinflusst und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 24% und seine bewirkte Heilung um 16%. Wenn der Träger Verbündete heilt, wird die bewirkte Heilung gespeichert. Wenn ein Verbündeter angreift, erleidet ein zufällig angegriffener Gegner zusätzlichen SCH in Höhe von 48% der gespeicherten bewirkten Heilung. Dieser zusätzliche SCH ist desselben Typs wie der SCH des Trägers, wird nicht von anderen Buffs beeinflusst und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 27% und seine bewirkte Heilung um 18%. Wenn der Träger Verbündete heilt, wird die bewirkte Heilung gespeichert. Wenn ein Verbündeter angreift, erleidet ein zufällig angegriffener Gegner zusätzlichen SCH in Höhe von 54% der gespeicherten bewirkten Heilung. Dieser zusätzliche SCH ist desselben Typs wie der SCH des Trägers, wird nicht von anderen Buffs beeinflusst und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 30% und seine bewirkte Heilung um 20%. Wenn der Träger Verbündete heilt, wird die bewirkte Heilung gespeichert. Wenn ein Verbündeter angreift, erleidet ein zufällig angegriffener Gegner zusätzlichen SCH in Höhe von 60% der gespeicherten bewirkten Heilung. Dieser zusätzliche SCH ist desselben Typs wie der SCH des Trägers, wird nicht von anderen Buffs beeinflusst und kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Die leise flackernde Sternenflamme', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/flickering_stars.png', '{"name": "Keim", "text": ["Erhöht die KRIT-Rate des Trägers um 18%. Wenn eine beliebige verbündete Figur in ihrer eigenen Runde insgesamt mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger für 3 Rd. „Strahlende Krone“. Wenn der Träger Strahlende Krone besitzt, ignoriert der von allen Verbündeten verursachte SCH 20% der VTD des Ziels und der vom Träger verursachte Fertigkeits-SCH wird um 72% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 21%. Wenn eine beliebige verbündete Figur in ihrer eigenen Runde insgesamt mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger für 3 Rd. „Strahlende Krone“. Wenn der Träger Strahlende Krone besitzt, ignoriert der von allen Verbündeten verursachte SCH 24% der VTD des Ziels und der vom Träger verursachte Fertigkeits-SCH wird um 84% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 24%. Wenn eine beliebige verbündete Figur in ihrer eigenen Runde insgesamt mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger für 3 Rd. „Strahlende Krone“. Wenn der Träger Strahlende Krone besitzt, ignoriert der von allen Verbündeten verursachte SCH 28% der VTD des Ziels und der vom Träger verursachte Fertigkeits-SCH wird um 96% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 27%. Wenn eine beliebige verbündete Figur in ihrer eigenen Runde insgesamt mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger für 3 Rd. „Strahlende Krone“. Wenn der Träger Strahlende Krone besitzt, ignoriert der von allen Verbündeten verursachte SCH 32% der VTD des Ziels und der vom Träger verursachte Fertigkeits-SCH wird um 108% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht die KRIT-Rate des Trägers um 30%. Wenn eine beliebige verbündete Figur in ihrer eigenen Runde insgesamt mindestens 4 Fertigkeitspunkte verbraucht, erhält der Träger für 3 Rd. „Strahlende Krone“. Wenn der Träger Strahlende Krone besitzt, ignoriert der von allen Verbündeten verursachte SCH 36% der VTD des Ziels und der vom Träger verursachte Fertigkeits-SCH wird um 120% erhöht. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Die nächste Seite der Geschichte', 'Das Gedenken', 4, 'assets/images/light_cones/the_story_s_next_page.png', '{"name": "Niederschreiben", "text": ["Erhöht die max. LP des Trägers um 16%. Nachdem der Memogeist des Trägers angegriffen hat, wird die bewirkte Heilung des Trägers und seines Memogeists für 1 Rd. um 12% erhöht.", "Erhöht die max. LP des Trägers um 20%. Nachdem der Memogeist des Trägers angegriffen hat, wird die bewirkte Heilung des Trägers und seines Memogeists für 1 Rd. um 15% erhöht.", "Erhöht die max. LP des Trägers um 24%. Nachdem der Memogeist des Trägers angegriffen hat, wird die bewirkte Heilung des Trägers und seines Memogeists für 1 Rd. um 18% erhöht.", "Erhöht die max. LP des Trägers um 28%. Nachdem der Memogeist des Trägers angegriffen hat, wird die bewirkte Heilung des Trägers und seines Memogeists für 1 Rd. um 21% erhöht.", "Erhöht die max. LP des Trägers um 32%. Nachdem der Memogeist des Trägers angegriffen hat, wird die bewirkte Heilung des Trägers und seines Memogeists für 1 Rd. um 24% erhöht."]}'),
  ('Doch Hoffnung ist unbezahlbar', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/yet_hope_is_priceless.png', '{"name": "Versprechen", "text": ["Erhöht die KRIT-Rate des Trägers um 16%. Liegt der KRIT-SCH des Trägers im Kampf über 120%, wird für je weitere 20% der durch Folgeangriffe verursachte SCH des Trägers um 12% erhöht. Dieser Effekt ist 4-fach stapelbar. Zu Beginn des Kampfes und nachdem der Träger einen Standardangriff ausgeführt hat, ignoriert der durch Ultimates oder Folgeangriffe verursachte SCH für 2 Rd. 20% der VTD des Ziels.", "Erhöht die KRIT-Rate des Trägers um 19%. Liegt der KRIT-SCH des Trägers im Kampf über 120%, wird für je weitere 20% der durch Folgeangriffe verursachte SCH des Trägers um 14% erhöht. Dieser Effekt ist 4-fach stapelbar. Zu Beginn des Kampfes und nachdem der Träger einen Standardangriff ausgeführt hat, ignoriert der durch Ultimates oder Folgeangriffe verursachte SCH für 2 Rd. 24% der VTD des Ziels.", "Erhöht die KRIT-Rate des Trägers um 22%. Liegt der KRIT-SCH des Trägers im Kampf über 120%, wird für je weitere 20% der durch Folgeangriffe verursachte SCH des Trägers um 16% erhöht. Dieser Effekt ist 4-fach stapelbar. Zu Beginn des Kampfes und nachdem der Träger einen Standardangriff ausgeführt hat, ignoriert der durch Ultimates oder Folgeangriffe verursachte SCH für 2 Rd. 28% der VTD des Ziels.", "Erhöht die KRIT-Rate des Trägers um 25%. Liegt der KRIT-SCH des Trägers im Kampf über 120%, wird für je weitere 20% der durch Folgeangriffe verursachte SCH des Trägers um 18% erhöht. Dieser Effekt ist 4-fach stapelbar. Zu Beginn des Kampfes und nachdem der Träger einen Standardangriff ausgeführt hat, ignoriert der durch Ultimates oder Folgeangriffe verursachte SCH für 2 Rd. 32% der VTD des Ziels.", "Erhöht die KRIT-Rate des Trägers um 28%. Liegt der KRIT-SCH des Trägers im Kampf über 120%, wird für je weitere 20% der durch Folgeangriffe verursachte SCH des Trägers um 20% erhöht. Dieser Effekt ist 4-fach stapelbar. Zu Beginn des Kampfes und nachdem der Träger einen Standardangriff ausgeführt hat, ignoriert der durch Ultimates oder Folgeangriffe verursachte SCH für 2 Rd. 36% der VTD des Ziels."]}'),
  ('Echos des Sarges', 'Der Überfluss', 5, 'assets/images/light_cones/echoes_of_the_coffin.png', '{"name": "Dornen", "text": ["Erhöht den ANG des Trägers um 24%. Wenn der Träger angreift, stellt er für jeden verschiedenen getroffenen Gegner 3 Pkt. Energie wieder her. Jeder Angriff kann auf diese Weise bis zu 3-mal Energie wiederherstellen. Nachdem der Träger den Ultimate eingesetzt hat, wird die GES aller Verbündeten für 1 Rd. um 12 Pkt. erhöht.", "Erhöht den ANG des Trägers um 28%. Wenn der Träger angreift, stellt er für jeden verschiedenen getroffenen Gegner 3,5 Pkt. Energie wieder her. Jeder Angriff kann auf diese Weise bis zu 3-mal Energie wiederherstellen. Nachdem der Träger den Ultimate eingesetzt hat, wird die GES aller Verbündeten für 1 Rd. um 14 Pkt. erhöht.", "Erhöht den ANG des Trägers um 32%. Wenn der Träger angreift, stellt er für jeden verschiedenen getroffenen Gegner 4 Pkt. Energie wieder her. Jeder Angriff kann auf diese Weise bis zu 3-mal Energie wiederherstellen. Nachdem der Träger den Ultimate eingesetzt hat, wird die GES aller Verbündeten für 1 Rd. um 16 Pkt. erhöht.", "Erhöht den ANG des Trägers um 36%. Wenn der Träger angreift, stellt er für jeden verschiedenen getroffenen Gegner 4,5 Pkt. Energie wieder her. Jeder Angriff kann auf diese Weise bis zu 3-mal Energie wiederherstellen. Nachdem der Träger den Ultimate eingesetzt hat, wird die GES aller Verbündeten für 1 Rd. um 18 Pkt. erhöht.", "Erhöht den ANG des Trägers um 40%. Wenn der Träger angreift, stellt er für jeden verschiedenen getroffenen Gegner 5 Pkt. Energie wieder her. Jeder Angriff kann auf diese Weise bis zu 3-mal Energie wiederherstellen. Nachdem der Träger den Ultimate eingesetzt hat, wird die GES aller Verbündeten für 1 Rd. um 20 Pkt. erhöht."]}'),
  ('Ein Gespräch nach der OP', 'Der Überfluss', 4, 'assets/images/light_cones/post_op_conversation.png', '{"name": "Gegenseitiges Heilen", "text": ["Erhöht die Energie-Regenerationsrate des Trägers um 8% und die bewirkte Heilung beim Einsatz des Ultimates um 12%.", "Erhöht die Energie-Regenerationsrate des Trägers um 10% und die bewirkte Heilung beim Einsatz des Ultimates um 15%.", "Erhöht die Energie-Regenerationsrate des Trägers um 12% und die bewirkte Heilung beim Einsatz des Ultimates um 18%.", "Erhöht die Energie-Regenerationsrate des Trägers um 14% und die bewirkte Heilung beim Einsatz des Ultimates um 21%.", "Erhöht die Energie-Regenerationsrate des Trägers um 16% und die bewirkte Heilung beim Einsatz des Ultimates um 24%."]}'),
  ('Ein geheimes Gelübde', 'Die Zerstörung', 4, 'assets/images/light_cones/a_secret_vow.png', '{"name": "Keine Mühen scheuen", "text": ["Erhöht den vom Träger verursachten SCH um 20%. Der Träger fügt außerdem Gegnern, deren aktueller LP-Prozentsatz gleich oder höher als der aktuelle LP-Prozentsatz des Trägers ist, zusätzlich 20% SCH zu.", "Erhöht den vom Träger verursachten SCH um 25%. Der Träger fügt außerdem Gegnern, deren aktueller LP-Prozentsatz gleich oder höher als der aktuelle LP-Prozentsatz des Trägers ist, zusätzlich 25% SCH zu.", "Erhöht den vom Träger verursachten SCH um 30%. Der Träger fügt außerdem Gegnern, deren aktueller LP-Prozentsatz gleich oder höher als der aktuelle LP-Prozentsatz des Trägers ist, zusätzlich 30% SCH zu.", "Erhöht den vom Träger verursachten SCH um 35%. Der Träger fügt außerdem Gegnern, deren aktueller LP-Prozentsatz gleich oder höher als der aktuelle LP-Prozentsatz des Trägers ist, zusätzlich 35% SCH zu.", "Erhöht den vom Träger verursachten SCH um 40%. Der Träger fügt außerdem Gegnern, deren aktueller LP-Prozentsatz gleich oder höher als der aktuelle LP-Prozentsatz des Trägers ist, zusätzlich 40% SCH zu."]}'),
  ('Ein noch schönerer Abschied', 'Das Gedenken', 5, 'assets/images/light_cones/make_farewells_more_beautiful.png', '{"name": "Schnitzen", "text": ["Erhöht die max. LP des Trägers um 30%. Wenn der Träger oder sein Memogeist während der eigenen Runde LP verlieren, erhält der Träger „Blüte der Unterwelt“, mit der der Träger und sein Memogeist beim Verursachen von SCH für 2 Rd. 30% der VTD des Ziels ignorieren.\\nWenn der Memogeist des Trägers verschwindet, wird die Aktion des Trägers um 12% vorgezogen. Dieser Effekt kann nur 1-mal ausgelöst werden. Die Auslösungsanzahl wird jedes Mal zurückgesetzt, wenn der Träger seinen Ultimate einsetzt.", "Erhöht die max. LP des Trägers um 38%. Wenn der Träger oder sein Memogeist während der eigenen Runde LP verlieren, erhält der Träger „Blüte der Unterwelt“, mit der der Träger und sein Memogeist beim Verursachen von SCH für 2 Rd. 35% der VTD des Ziels ignorieren.\\nWenn der Memogeist des Trägers verschwindet, wird die Aktion des Trägers um 15% vorgezogen. Dieser Effekt kann nur 1-mal ausgelöst werden. Die Auslösungsanzahl wird jedes Mal zurückgesetzt, wenn der Träger seinen Ultimate einsetzt.", "Erhöht die max. LP des Trägers um 45%. Wenn der Träger oder sein Memogeist während der eigenen Runde LP verlieren, erhält der Träger „Blüte der Unterwelt“, mit der der Träger und sein Memogeist beim Verursachen von SCH für 2 Rd. 40% der VTD des Ziels ignorieren.\\nWenn der Memogeist des Trägers verschwindet, wird die Aktion des Trägers um 18% vorgezogen. Dieser Effekt kann nur 1-mal ausgelöst werden. Die Auslösungsanzahl wird jedes Mal zurückgesetzt, wenn der Träger seinen Ultimate einsetzt.", "Erhöht die max. LP des Trägers um 53%. Wenn der Träger oder sein Memogeist während der eigenen Runde LP verlieren, erhält der Träger „Blüte der Unterwelt“, mit der der Träger und sein Memogeist beim Verursachen von SCH für 2 Rd. 45% der VTD des Ziels ignorieren.\\nWenn der Memogeist des Trägers verschwindet, wird die Aktion des Trägers um 21% vorgezogen. Dieser Effekt kann nur 1-mal ausgelöst werden. Die Auslösungsanzahl wird jedes Mal zurückgesetzt, wenn der Träger seinen Ultimate einsetzt.", "Erhöht die max. LP des Trägers um 60%. Wenn der Träger oder sein Memogeist während der eigenen Runde LP verlieren, erhält der Träger „Blüte der Unterwelt“, mit der der Träger und sein Memogeist beim Verursachen von SCH für 2 Rd. 50% der VTD des Ziels ignorieren.\\nWenn der Memogeist des Trägers verschwindet, wird die Aktion des Trägers um 24% vorgezogen. Dieser Effekt kann nur 1-mal ausgelöst werden. Die Auslösungsanzahl wird jedes Mal zurückgesetzt, wenn der Träger seinen Ultimate einsetzt."]}'),
  ('Ein unvergesslicher Augenblick', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/an_instant_before_a_gaze.png', '{"name": "Ritterreise", "text": ["Erhöht den KRIT-SCH des Trägers um 36%. Wenn der Träger Ultimate einsetzt, wird der durch seinen Ultimate verursachten SCH basierend auf seiner max. Energie erhöht: Jeder Pkt. Energie erhöht den SCH um 0,36%, bis max. 180 Pkt.", "Erhöht den KRIT-SCH des Trägers um 42%. Wenn der Träger Ultimate einsetzt, wird der durch seinen Ultimate verursachten SCH basierend auf seiner max. Energie erhöht: Jeder Pkt. Energie erhöht den SCH um 0,42%, bis max. 180 Pkt.", "Erhöht den KRIT-SCH des Trägers um 48%. Wenn der Träger Ultimate einsetzt, wird der durch seinen Ultimate verursachten SCH basierend auf seiner max. Energie erhöht: Jeder Pkt. Energie erhöht den SCH um 0,48%, bis max. 180 Pkt.", "Erhöht den KRIT-SCH des Trägers um 54%. Wenn der Träger Ultimate einsetzt, wird der durch seinen Ultimate verursachten SCH basierend auf seiner max. Energie erhöht: Jeder Pkt. Energie erhöht den SCH um 0,54%, bis max. 180 Pkt.", "Erhöht den KRIT-SCH des Trägers um 60%. Wenn der Träger Ultimate einsetzt, wird der durch seinen Ultimate verursachten SCH basierend auf seiner max. Energie erhöht: Jeder Pkt. Energie erhöht den SCH um 0,60%, bis max. 180 Pkt."]}'),
  ('Eine Krönung ohne Dank', 'Die Zerstörung', 5, 'assets/images/light_cones/a_thankless_coronation.png', '{"name": "König der Ritter", "text": ["Erhöht den KRIT-SCH des Trägers um 36%. Erhöht beim Einsatz des Ultimates den ANG des Trägers um 40%. Wenn die max. Energie des Trägers 300 Pkt. oder mehr beträgt, wird beim Träger eine feste Menge Energie in Höhe von 10% seiner max. Energie wiederhergestellt und sein ANG erneut um 40% erhöht. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 45%. Erhöht beim Einsatz des Ultimates den ANG des Trägers um 50%. Wenn die max. Energie des Trägers 300 Pkt. oder mehr beträgt, wird beim Träger eine feste Menge Energie in Höhe von 10% seiner max. Energie wiederhergestellt und sein ANG erneut um 50% erhöht. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 54%. Erhöht beim Einsatz des Ultimates den ANG des Trägers um 60%. Wenn die max. Energie des Trägers 300 Pkt. oder mehr beträgt, wird beim Träger eine feste Menge Energie in Höhe von 10% seiner max. Energie wiederhergestellt und sein ANG erneut um 60% erhöht. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 63%. Erhöht beim Einsatz des Ultimates den ANG des Trägers um 70%. Wenn die max. Energie des Trägers 300 Pkt. oder mehr beträgt, wird beim Träger eine feste Menge Energie in Höhe von 10% seiner max. Energie wiederhergestellt und sein ANG erneut um 70% erhöht. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 72%. Erhöht beim Einsatz des Ultimates den ANG des Trägers um 80%. Wenn die max. Energie des Trägers 300 Pkt. oder mehr beträgt, wird beim Träger eine feste Menge Energie in Höhe von 10% seiner max. Energie wiederhergestellt und sein ANG erneut um 80% erhöht. Dieser Effekt hält für 2 Rd. an."]}'),
  ('Einklang der Zahnräder', 'Die Harmonie', 3, 'assets/images/light_cones/meshing_cogs.png', '{"name": "Schneller Sieg", "text": ["Nachdem der Träger Angriffe einsetzt oder getroffen wurde, werden zusätzlich 4 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Nachdem der Träger Angriffe einsetzt oder getroffen wurde, werden zusätzlich 5 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Nachdem der Träger Angriffe einsetzt oder getroffen wurde, werden zusätzlich 6 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Nachdem der Träger Angriffe einsetzt oder getroffen wurde, werden zusätzlich 7 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Nachdem der Träger Angriffe einsetzt oder getroffen wurde, werden zusätzlich 8 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Eins mit dem Schwert', 'Die Zerstörung', 5, 'assets/images/light_cones/i_shall_be_my_own_sword.png', '{"name": "Mit dieser Abendjade", "text": ["Erhöht den KRIT-SCH des Trägers um 20%. Wenn Verbündete angegriffen werden oder ihre eigenen LP verbrauchen, erhält der Träger 1 Stapelung „Mondfinsternis“, bis zu 3-fach stapelbar. Jede Stapelung von „Mondfinsternis“ erhöht den verursachten SCH des nächsten Angriffs vom Träger um 14%. Wenn 3 Stapelungen erreicht sind, ignoriert dieser Angriff 12% der VTD des Ziels. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht den KRIT-SCH des Trägers um 23%. Wenn Verbündete angegriffen werden oder ihre eigenen LP verbrauchen, erhält der Träger 1 Stapelung „Mondfinsternis“, bis zu 3-fach stapelbar. Jede Stapelung von „Mondfinsternis“ erhöht den verursachten SCH des nächsten Angriffs vom Träger um 16,5%. Wenn 3 Stapelungen erreicht sind, ignoriert dieser Angriff 14% der VTD des Ziels. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht den KRIT-SCH des Trägers um 26%. Wenn Verbündete angegriffen werden oder ihre eigenen LP verbrauchen, erhält der Träger 1 Stapelung „Mondfinsternis“, bis zu 3-fach stapelbar. Jede Stapelung von „Mondfinsternis“ erhöht den verursachten SCH des nächsten Angriffs vom Träger um 19%. Wenn 3 Stapelungen erreicht sind, ignoriert dieser Angriff 16% der VTD des Ziels. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht den KRIT-SCH des Trägers um 29%. Wenn Verbündete angegriffen werden oder ihre eigenen LP verbrauchen, erhält der Träger 1 Stapelung „Mondfinsternis“, bis zu 3-fach stapelbar. Jede Stapelung von „Mondfinsternis“ erhöht den verursachten SCH des nächsten Angriffs vom Träger um 21,5%. Wenn 3 Stapelungen erreicht sind, ignoriert dieser Angriff 18% der VTD des Ziels. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht den KRIT-SCH des Trägers um 32%. Wenn Verbündete angegriffen werden oder ihre eigenen LP verbrauchen, erhält der Träger 1 Stapelung „Mondfinsternis“, bis zu 3-fach stapelbar. Jede Stapelung von „Mondfinsternis“ erhöht den verursachten SCH des nächsten Angriffs vom Träger um 24%. Wenn 3 Stapelungen erreicht sind, ignoriert dieser Angriff 20% der VTD des Ziels. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat."]}'),
  ('Einzelne Heilung', 'Die Nichtigkeit', 5, 'assets/images/light_cones/solitary_healing.png', '{"name": "Chaoselixier", "text": ["Erhöht den Brucheffekt des Trägers um 20%. Wenn der Träger seinen Ultimate einsetzt, wird sein verursachter DoT für 2 Rd. um 24% erhöht. Wird ein vom DoT durch den Träger betroffener Gegner besiegt, wird die Energie des Trägers um 4 Pkt. wiederhergestellt.", "Erhöht den Brucheffekt des Trägers um 25%. Wenn der Träger seinen Ultimate einsetzt, wird sein verursachter DoT für 2 Rd. um 30% erhöht. Wird ein vom DoT durch den Träger betroffener Gegner besiegt, wird die Energie des Trägers um 4,5 Pkt. wiederhergestellt.", "Erhöht den Brucheffekt des Trägers um 30%. Wenn der Träger seinen Ultimate einsetzt, wird sein verursachter DoT für 2 Rd. um 36% erhöht. Wird ein vom DoT durch den Träger betroffener Gegner besiegt, wird die Energie des Trägers um 5 Pkt. wiederhergestellt.", "Erhöht den Brucheffekt des Trägers um 35%. Wenn der Träger seinen Ultimate einsetzt, wird sein verursachter DoT für 2 Rd. um 42% erhöht. Wird ein vom DoT durch den Träger betroffener Gegner besiegt, wird die Energie des Trägers um 5,5 Pkt. wiederhergestellt.", "Erhöht den Brucheffekt des Trägers um 40%. Wenn der Träger seinen Ultimate einsetzt, wird sein verursachter DoT für 2 Rd. um 48% erhöht. Wird ein vom DoT durch den Träger betroffener Gegner besiegt, wird die Energie des Trägers um 6 Pkt. wiederhergestellt."]}'),
  ('Endgültiger Sieger', 'Die Jagd', 4, 'assets/images/light_cones/final_victor.png', '{"name": "Die Wette gilt", "text": ["Erhöht den ANG des Trägers um 12%. Wenn der Träger einem Gegner einen Kritischen Treffer zufügt, erhält er eine Stapelung „Viel Glück“ bis zu max. 4 Stapelungen. Jede Stapelung erhöht den KRIT-SCH des Trägers um 8%. Viel Glück wird am Ende der Runde des Trägers entfernt.", "Erhöht den ANG des Trägers um 14%. Wenn der Träger einem Gegner einen Kritischen Treffer zufügt, erhält er eine Stapelung „Viel Glück“ bis zu max. 4 Stapelungen. Jede Stapelung erhöht den KRIT-SCH des Trägers um 9%. Viel Glück wird am Ende der Runde des Trägers entfernt.", "Erhöht den ANG des Trägers um 16%. Wenn der Träger einem Gegner einen Kritischen Treffer zufügt, erhält er eine Stapelung „Viel Glück“ bis zu max. 4 Stapelungen. Jede Stapelung erhöht den KRIT-SCH des Trägers um 10%. Viel Glück wird am Ende der Runde des Trägers entfernt.", "Erhöht den ANG des Trägers um 18%. Wenn der Träger einem Gegner einen Kritischen Treffer zufügt, erhält er eine Stapelung „Viel Glück“ bis zu max. 4 Stapelungen. Jede Stapelung erhöht den KRIT-SCH des Trägers um 11%. Viel Glück wird am Ende der Runde des Trägers entfernt.", "Erhöht den ANG des Trägers um 20%. Wenn der Träger einem Gegner einen Kritischen Treffer zufügt, erhält er eine Stapelung „Viel Glück“ bis zu max. 4 Stapelungen. Jede Stapelung erhöht den KRIT-SCH des Trägers um 12%. Viel Glück wird am Ende der Runde des Trägers entfernt."]}'),
  ('Entlang am vorbeiziehenden Ufer', 'Die Nichtigkeit', 5, 'assets/images/light_cones/along_the_passing_shore.png', '{"name": "Fährmann", "text": ["Erhöht den KRIT-SCH des Trägers um 36%. Wenn der Träger einen Gegner trifft, wird das Ziel für 1 Rd. mit „Luftschloss“ belegt. Jedes Mal, wenn der Träger angreift, kann dieser Effekt bei jedem Ziel nur 1-mal ausgelöst werden. Der verursachte SCH des Trägers bei Gegnern mit Luftschloss wird um 24% und der durch Ultimates verursachte SCH zusätzlich um 24% erhöht.", "Erhöht den KRIT-SCH des Trägers um 42%. Wenn der Träger einen Gegner trifft, wird das Ziel für 1 Rd. mit „Luftschloss“ belegt. Jedes Mal, wenn der Träger angreift, kann dieser Effekt bei jedem Ziel nur 1-mal ausgelöst werden. Der verursachte SCH des Trägers bei Gegnern mit Luftschloss wird um 28% und der durch Ultimates verursachte SCH zusätzlich um 28% erhöht.", "Erhöht den KRIT-SCH des Trägers um 48%. Wenn der Träger einen Gegner trifft, wird das Ziel für 1 Rd. mit „Luftschloss“ belegt. Jedes Mal, wenn der Träger angreift, kann dieser Effekt bei jedem Ziel nur 1-mal ausgelöst werden. Der verursachte SCH des Trägers bei Gegnern mit Luftschloss wird um 32% und der durch Ultimates verursachte SCH zusätzlich um 32% erhöht.", "Erhöht den KRIT-SCH des Trägers um 54%. Wenn der Träger einen Gegner trifft, wird das Ziel für 1 Rd. mit „Luftschloss“ belegt. Jedes Mal, wenn der Träger angreift, kann dieser Effekt bei jedem Ziel nur 1-mal ausgelöst werden. Der verursachte SCH des Trägers bei Gegnern mit Luftschloss wird um 36% und der durch Ultimates verursachte SCH zusätzlich um 36% erhöht.", "Erhöht den KRIT-SCH des Trägers um 60%. Wenn der Träger einen Gegner trifft, wird das Ziel für 1 Rd. mit „Luftschloss“ belegt. Jedes Mal, wenn der Träger angreift, kann dieser Effekt bei jedem Ziel nur 1-mal ausgelöst werden. Der verursachte SCH des Trägers bei Gegnern mit Luftschloss wird um 40% und der durch Ultimates verursachte SCH zusätzlich um 40% erhöht."]}'),
  ('Erinnerungen an die Vergangenheit', 'Die Harmonie', 4, 'assets/images/light_cones/memories_of_the_past.png', '{"name": "Altes Foto", "text": ["Erhöht den Brucheffekt des Trägers um 28%. Nach dem Angriff werden zusätzlich 4 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 35%. Nach dem Angriff werden zusätzlich 5 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 42%. Nach dem Angriff werden zusätzlich 6 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 49%. Nach dem Angriff werden zusätzlich 7 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den Brucheffekt des Trägers um 56%. Nach dem Angriff werden zusätzlich 8 Pkt. Energie wiederhergestellt. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Eskapade auf Erden', 'Die Harmonie', 5, 'assets/images/light_cones/earthly_escapade.png', '{"name": "Wankelmut", "text": ["Erhöht den KRIT-SCH des Trägers um 32%. Zu Beginn des Kampfes erhält der Träger für 3 Rd. „Maske“. Während er Maske hat, wird bei allen Verbündeten des Trägers die KRIT-Rate um 10% und der KRIT-SCH um 28% erhöht. Wenn der Träger einen Fertigkeitspunkt wiederherstellt, erhält er eine Stapelung „Strahlende Flamme“; dabei zählen auch überschüssige Fertigkeitspunkte. Wenn der Träger 4 Stapelungen Strahlende Flamme besitzt, werden alle entfernt und für 4 Rd. Maske erhalten.", "Erhöht den KRIT-SCH des Trägers um 39%. Zu Beginn des Kampfes erhält der Träger für 3 Rd. „Maske“. Während er Maske hat, wird bei allen Verbündeten des Trägers die KRIT-Rate um 11% und der KRIT-SCH um 35% erhöht. Wenn der Träger einen Fertigkeitspunkt wiederherstellt, erhält er eine Stapelung „Strahlende Flamme“; dabei zählen auch überschüssige Fertigkeitspunkte. Wenn der Träger 4 Stapelungen Strahlende Flamme besitzt, werden alle entfernt und für 4 Rd. Maske erhalten.", "Erhöht den KRIT-SCH des Trägers um 46%. Zu Beginn des Kampfes erhält der Träger für 3 Rd. „Maske“. Während er Maske hat, wird bei allen Verbündeten des Trägers die KRIT-Rate um 12% und der KRIT-SCH um 42% erhöht. Wenn der Träger einen Fertigkeitspunkt wiederherstellt, erhält er eine Stapelung „Strahlende Flamme“; dabei zählen auch überschüssige Fertigkeitspunkte. Wenn der Träger 4 Stapelungen Strahlende Flamme besitzt, werden alle entfernt und für 4 Rd. Maske erhalten.", "Erhöht den KRIT-SCH des Trägers um 53%. Zu Beginn des Kampfes erhält der Träger für 3 Rd. „Maske“. Während er Maske hat, wird bei allen Verbündeten des Trägers die KRIT-Rate um 13% und der KRIT-SCH um 49% erhöht. Wenn der Träger einen Fertigkeitspunkt wiederherstellt, erhält er eine Stapelung „Strahlende Flamme“; dabei zählen auch überschüssige Fertigkeitspunkte. Wenn der Träger 4 Stapelungen Strahlende Flamme besitzt, werden alle entfernt und für 4 Rd. Maske erhalten.", "Erhöht den KRIT-SCH des Trägers um 60%. Zu Beginn des Kampfes erhält der Träger für 3 Rd. „Maske“. Während er Maske hat, wird bei allen Verbündeten des Trägers die KRIT-Rate um 14% und der KRIT-SCH um 56% erhöht. Wenn der Träger einen Fertigkeitspunkt wiederherstellt, erhält er eine Stapelung „Strahlende Flamme“; dabei zählen auch überschüssige Fertigkeitspunkte. Wenn der Träger 4 Stapelungen Strahlende Flamme besitzt, werden alle entfernt und für 4 Rd. Maske erhalten."]}'),
  ('Etwas Unersetzliches', 'Die Zerstörung', 5, 'assets/images/light_cones/something_irreplaceable.png', '{"name": "Teil der Familie", "text": ["Erhöht den ANG des Trägers um 24%. Besiegt der Träger einen Gegner oder wird angegriffen, werden sofort LP in Höhe von 8% seines ANG wiederhergestellt. Gleichzeitig wird sein verursachter SCH bis zum Ende seiner nächsten Runde um 24% erhöht. Dieser Effekt ist nicht stapelbar und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den ANG des Trägers um 28%. Besiegt der Träger einen Gegner oder wird angegriffen, werden sofort LP in Höhe von 9% seines ANG wiederhergestellt. Gleichzeitig wird sein verursachter SCH bis zum Ende seiner nächsten Runde um 28% erhöht. Dieser Effekt ist nicht stapelbar und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den ANG des Trägers um 32%. Besiegt der Träger einen Gegner oder wird angegriffen, werden sofort LP in Höhe von 10% seines ANG wiederhergestellt. Gleichzeitig wird sein verursachter SCH bis zum Ende seiner nächsten Runde um 32% erhöht. Dieser Effekt ist nicht stapelbar und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den ANG des Trägers um 36%. Besiegt der Träger einen Gegner oder wird angegriffen, werden sofort LP in Höhe von 11% seines ANG wiederhergestellt. Gleichzeitig wird sein verursachter SCH bis zum Ende seiner nächsten Runde um 36% erhöht. Dieser Effekt ist nicht stapelbar und kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht den ANG des Trägers um 40%. Besiegt der Träger einen Gegner oder wird angegriffen, werden sofort LP in Höhe von 12% seines ANG wiederhergestellt. Gleichzeitig wird sein verursachter SCH bis zum Ende seiner nächsten Runde um 40% erhöht. Dieser Effekt ist nicht stapelbar und kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Fahrt durch das Sternenmeer', 'Die Jagd', 5, 'assets/images/light_cones/cruising_in_the_stellar_sea.png', '{"name": "Jagen", "text": ["Erhöht die KRIT-Rate des Trägers um 8% und erhöht seine KRIT-Rate bei Gegnern, deren LP-Prozentsatz bei 50% oder niedriger liegt, zusätzlich um 8%. Besiegt der Träger einen Gegner, wird sein ANG für 2 Rd. um 20% erhöht.", "Erhöht die KRIT-Rate des Trägers um 10% und erhöht seine KRIT-Rate bei Gegnern, deren LP-Prozentsatz bei 50% oder niedriger liegt, zusätzlich um 10%. Besiegt der Träger einen Gegner, wird sein ANG für 2 Rd. um 25% erhöht.", "Erhöht die KRIT-Rate des Trägers um 12% und erhöht seine KRIT-Rate bei Gegnern, deren LP-Prozentsatz bei 50% oder niedriger liegt, zusätzlich um 12%. Besiegt der Träger einen Gegner, wird sein ANG für 2 Rd. um 30% erhöht.", "Erhöht die KRIT-Rate des Trägers um 14% und erhöht seine KRIT-Rate bei Gegnern, deren LP-Prozentsatz bei 50% oder niedriger liegt, zusätzlich um 14%. Besiegt der Träger einen Gegner, wird sein ANG für 2 Rd. um 35% erhöht.", "Erhöht die KRIT-Rate des Trägers um 16% und erhöht seine KRIT-Rate bei Gegnern, deren LP-Prozentsatz bei 50% oder niedriger liegt, zusätzlich um 16%. Besiegt der Träger einen Gegner, wird sein ANG für 2 Rd. um 40% erhöht."]}'),
  ('Farben für morgen', 'Das Hochgefühl', 5, 'assets/images/light_cones/colors_for_tomorrow.png', '{"name": "Tuscheschwung", "text": ["Erhöht die VTD des Trägers um 48%. Wenn der Träger eine Hochgefühl-Fähigkeit auf alle Verbündeten einsetzt, wird der erlittene SCH aller Gegner für 3 Rd. um 22% erhöht. Stellt außerdem beim Träger eine feste Menge von 10 Pkt. Energie sowie bei allen Verbündeten LP in Höhe von 10% der VTD des Trägers wieder her.", "Erhöht die VTD des Trägers um 60%. Wenn der Träger eine Hochgefühl-Fähigkeit auf alle Verbündeten einsetzt, wird der erlittene SCH aller Gegner für 3 Rd. um 28% erhöht. Stellt außerdem beim Träger eine feste Menge von 10 Pkt. Energie sowie bei allen Verbündeten LP in Höhe von 13% der VTD des Trägers wieder her.", "Erhöht die VTD des Trägers um 72%. Wenn der Träger eine Hochgefühl-Fähigkeit auf alle Verbündeten einsetzt, wird der erlittene SCH aller Gegner für 3 Rd. um 33% erhöht. Stellt außerdem beim Träger eine feste Menge von 10 Pkt. Energie sowie bei allen Verbündeten LP in Höhe von 15% der VTD des Trägers wieder her.", "Erhöht die VTD des Trägers um 84%. Wenn der Träger eine Hochgefühl-Fähigkeit auf alle Verbündeten einsetzt, wird der erlittene SCH aller Gegner für 3 Rd. um 39% erhöht. Stellt außerdem beim Träger eine feste Menge von 10 Pkt. Energie sowie bei allen Verbündeten LP in Höhe von 18% der VTD des Trägers wieder her.", "Erhöht die VTD des Trägers um 96%. Wenn der Träger eine Hochgefühl-Fähigkeit auf alle Verbündeten einsetzt, wird der erlittene SCH aller Gegner für 3 Rd. um 44% erhöht. Stellt außerdem beim Träger eine feste Menge von 10 Pkt. Energie sowie bei allen Verbündeten LP in Höhe von 20% der VTD des Trägers wieder her."]}'),
  ('Feines Obst', 'Der Überfluss', 3, 'assets/images/light_cones/fine_fruit.png', '{"name": "Geschmack", "text": ["Stellt zu Beginn des Kampfes sofort 6 Pkt. Energie für alle Verbündeten wieder her.", "Stellt zu Beginn des Kampfes sofort 8 Pkt. Energie für alle Verbündeten wieder her.", "Stellt zu Beginn des Kampfes sofort 9 Pkt. Energie für alle Verbündeten wieder her.", "Stellt zu Beginn des Kampfes sofort 11 Pkt. Energie für alle Verbündeten wieder her.", "Stellt zu Beginn des Kampfes sofort 12 Pkt. Energie für alle Verbündeten wieder her."]}'),
  ('Fermate', 'Die Nichtigkeit', 4, 'assets/images/light_cones/fermata.png', '{"name": "Semibrevis-Pause", "text": ["Erhöht den Brucheffekt des Trägers um 16%. Erhöht seinen verursachten SCH bei Gegnern, die Schock oder Windscherung erleiden, um 16%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den Brucheffekt des Trägers um 20%. Erhöht seinen verursachten SCH bei Gegnern, die Schock oder Windscherung erleiden, um 20%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den Brucheffekt des Trägers um 24%. Erhöht seinen verursachten SCH bei Gegnern, die Schock oder Windscherung erleiden, um 24%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den Brucheffekt des Trägers um 28%. Erhöht seinen verursachten SCH bei Gegnern, die Schock oder Windscherung erleiden, um 28%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den Brucheffekt des Trägers um 32%. Erhöht seinen verursachten SCH bei Gegnern, die Schock oder Windscherung erleiden, um 32%. Dieser Effekt gilt ebenfalls für DoT."]}'),
  ('Feuer in der Ferne', 'Die Zerstörung', 4, 'assets/images/light_cones/flames_afar.png', '{"name": "Deflagration", "text": ["Wenn die LP, die der Träger bei einem einzelnen Angriff verliert oder auf einmal verbraucht, 25% seiner max. LP überschreiten, werden sofort 15% seiner max. LP wiederhergestellt und gleichzeitig für 2 Rd. der verursachte SCH um 25% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Wenn die LP, die der Träger bei einem einzelnen Angriff verliert oder auf einmal verbraucht, 25% seiner max. LP überschreiten, werden sofort 15% seiner max. LP wiederhergestellt und gleichzeitig für 2 Rd. der verursachte SCH um 31% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Wenn die LP, die der Träger bei einem einzelnen Angriff verliert oder auf einmal verbraucht, 25% seiner max. LP überschreiten, werden sofort 15% seiner max. LP wiederhergestellt und gleichzeitig für 2 Rd. der verursachte SCH um 38% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Wenn die LP, die der Träger bei einem einzelnen Angriff verliert oder auf einmal verbraucht, 25% seiner max. LP überschreiten, werden sofort 15% seiner max. LP wiederhergestellt und gleichzeitig für 2 Rd. der verursachte SCH um 44% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Wenn die LP, die der Träger bei einem einzelnen Angriff verliert oder auf einmal verbraucht, 25% seiner max. LP überschreiten, werden sofort 15% seiner max. LP wiederhergestellt und gleichzeitig für 2 Rd. der verursachte SCH um 50% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden."]}'),
  ('Flamme des Blutes, entzünde meinen Pfad', 'Die Zerstörung', 5, 'assets/images/light_cones/flame_of_blood_blaze_my_path.png', '{"name": "Weitblick", "text": ["Erhöht die max. LP des Trägers um 18% und die erhaltene Heilung um 20%. Der Einsatz der Fertigkeit oder des Ultimates verbraucht LP in Höhe von 6% der max. LP des Trägers und erhöht den verursachten SCH dieses Angriffs um 30%. Wenn die dabei verbrauchten LP 500 Pkt. oder mehr betragen, wird der SCH zusätzlich um 30% erhöht.\\nWenn die aktuellen LP nicht ausreichen, werden die aktuellen LP des Trägers auf 1 reduziert.", "Erhöht die max. LP des Trägers um 21% und die erhaltene Heilung um 25%. Der Einsatz der Fertigkeit oder des Ultimates verbraucht LP in Höhe von 6,5% der max. LP des Trägers und erhöht den verursachten SCH dieses Angriffs um 35%. Wenn die dabei verbrauchten LP 500 Pkt. oder mehr betragen, wird der SCH zusätzlich um 35% erhöht.\\nWenn die aktuellen LP nicht ausreichen, werden die aktuellen LP des Trägers auf 1 reduziert.", "Erhöht die max. LP des Trägers um 24% und die erhaltene Heilung um 30%. Der Einsatz der Fertigkeit oder des Ultimates verbraucht LP in Höhe von 7% der max. LP des Trägers und erhöht den verursachten SCH dieses Angriffs um 40%. Wenn die dabei verbrauchten LP 500 Pkt. oder mehr betragen, wird der SCH zusätzlich um 40% erhöht.\\nWenn die aktuellen LP nicht ausreichen, werden die aktuellen LP des Trägers auf 1 reduziert.", "Erhöht die max. LP des Trägers um 27% und die erhaltene Heilung um 35%. Der Einsatz der Fertigkeit oder des Ultimates verbraucht LP in Höhe von 7,5% der max. LP des Trägers und erhöht den verursachten SCH dieses Angriffs um 45%. Wenn die dabei verbrauchten LP 500 Pkt. oder mehr betragen, wird der SCH zusätzlich um 45% erhöht.\\nWenn die aktuellen LP nicht ausreichen, werden die aktuellen LP des Trägers auf 1 reduziert.", "Erhöht die max. LP des Trägers um 30% und die erhaltene Heilung um 40%. Der Einsatz der Fertigkeit oder des Ultimates verbraucht LP in Höhe von 8% der max. LP des Trägers und erhöht den verursachten SCH dieses Angriffs um 50%. Wenn die dabei verbrauchten LP 500 Pkt. oder mehr betragen, wird der SCH zusätzlich um 50% erhöht.\\nWenn die aktuellen LP nicht ausreichen, werden die aktuellen LP des Trägers auf 1 reduziert."]}'),
  ('Flug in einen rosaroten Morgen', 'Das Gedenken', 4, 'assets/images/light_cones/fly_into_a_pink_tomorrow.png', '{"name": "Blick", "text": ["Erhöht den KRIT-SCH des Trägers um 12%. Bei der Ausrüstung durch die Trailblazerin/den Trailblazer (Das Gedenken) wird der verursachte SCH aller Verbündeten um 8% und der verursachte SCH des verstärkten Standardangriffs „Schreiben wir gemeinsam vom Morgen!“ um 60% erhöht.", "Erhöht den KRIT-SCH des Trägers um 15%. Bei der Ausrüstung durch die Trailblazerin/den Trailblazer (Das Gedenken) wird der verursachte SCH aller Verbündeten um 10% und der verursachte SCH des verstärkten Standardangriffs „Schreiben wir gemeinsam vom Morgen!“ um 70% erhöht.", "Erhöht den KRIT-SCH des Trägers um 18%. Bei der Ausrüstung durch die Trailblazerin/den Trailblazer (Das Gedenken) wird der verursachte SCH aller Verbündeten um 12% und der verursachte SCH des verstärkten Standardangriffs „Schreiben wir gemeinsam vom Morgen!“ um 80% erhöht.", "Erhöht den KRIT-SCH des Trägers um 21%. Bei der Ausrüstung durch die Trailblazerin/den Trailblazer (Das Gedenken) wird der verursachte SCH aller Verbündeten um 14% und der verursachte SCH des verstärkten Standardangriffs „Schreiben wir gemeinsam vom Morgen!“ um 90% erhöht.", "Erhöht den KRIT-SCH des Trägers um 24%. Bei der Ausrüstung durch die Trailblazerin/den Trailblazer (Das Gedenken) wird der verursachte SCH aller Verbündeten um 16% und der verursachte SCH des verstärkten Standardangriffs „Schreiben wir gemeinsam vom Morgen!“ um 100% erhöht."]}'),
  ('Flug zurück zur Erde', 'Die Harmonie', 5, 'assets/images/light_cones/a_grounded_ascent.png', '{"name": "Erneute Abreise", "text": ["Nachdem der Träger eine Fertigkeit oder einen Ultimate auf einen Verbündeten angewendet hat, stellt er 6 Pkt. Energie wieder her und das Ziel erhält für 3 Rd. 1 Stapelung „Heilige Hymne“, was den verursachten SCH um 15% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar. Nachdem Fertigkeit oder Ultimate des Trägers 2-mal auf Verbündete angewendet wurde, wird 1 Fertigkeitspunkt wiederhergestellt.", "Nachdem der Träger eine Fertigkeit oder einen Ultimate auf einen Verbündeten angewendet hat, stellt er 6,5 Pkt. Energie wieder her und das Ziel erhält für 3 Rd. 1 Stapelung „Heilige Hymne“, was den verursachten SCH um 17% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar. Nachdem Fertigkeit oder Ultimate des Trägers 2-mal auf Verbündete angewendet wurde, wird 1 Fertigkeitspunkt wiederhergestellt.", "Nachdem der Träger eine Fertigkeit oder einen Ultimate auf einen Verbündeten angewendet hat, stellt er 7 Pkt. Energie wieder her und das Ziel erhält für 3 Rd. 1 Stapelung „Heilige Hymne“, was den verursachten SCH um 20% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar. Nachdem Fertigkeit oder Ultimate des Trägers 2-mal auf Verbündete angewendet wurde, wird 1 Fertigkeitspunkt wiederhergestellt.", "Nachdem der Träger eine Fertigkeit oder einen Ultimate auf einen Verbündeten angewendet hat, stellt er 7,5 Pkt. Energie wieder her und das Ziel erhält für 3 Rd. 1 Stapelung „Heilige Hymne“, was den verursachten SCH um 22% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar. Nachdem Fertigkeit oder Ultimate des Trägers 2-mal auf Verbündete angewendet wurde, wird 1 Fertigkeitspunkt wiederhergestellt.", "Nachdem der Träger eine Fertigkeit oder einen Ultimate auf einen Verbündeten angewendet hat, stellt er 8 Pkt. Energie wieder her und das Ziel erhält für 3 Rd. 1 Stapelung „Heilige Hymne“, was den verursachten SCH um 24% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar. Nachdem Fertigkeit oder Ultimate des Trägers 2-mal auf Verbündete angewendet wurde, wird 1 Fertigkeitspunkt wiederhergestellt."]}'),
  ('Flüsse plätschern im Frühling', 'Die Jagd', 4, 'assets/images/light_cones/river_flows_in_spring.png', '{"name": "Die nachklingende Kälte abwehren", "text": ["Erhöht nach Kampfeintritt die GES des Trägers um 8% und verursachten SCH um 12%. Wenn der Träger SCH erleidet, wird dieser Effekt aufgehoben und nach dem Ende der nächsten Runde wieder aktiviert.", "Erhöht nach Kampfeintritt die GES des Trägers um 9% und verursachten SCH um 15%. Wenn der Träger SCH erleidet, wird dieser Effekt aufgehoben und nach dem Ende der nächsten Runde wieder aktiviert.", "Erhöht nach Kampfeintritt die GES des Trägers um 10% und verursachten SCH um 18%. Wenn der Träger SCH erleidet, wird dieser Effekt aufgehoben und nach dem Ende der nächsten Runde wieder aktiviert.", "Erhöht nach Kampfeintritt die GES des Trägers um 11% und verursachten SCH um 21%. Wenn der Träger SCH erleidet, wird dieser Effekt aufgehoben und nach dem Ende der nächsten Runde wieder aktiviert.", "Erhöht nach Kampfeintritt die GES des Trägers um 12% und verursachten SCH um 24%. Wenn der Träger SCH erleidet, wird dieser Effekt aufgehoben und nach dem Ende der nächsten Runde wieder aktiviert."]}'),
  ('Füllhorn', 'Der Überfluss', 3, 'assets/images/light_cones/cornucopia.png', '{"name": "Gedeihen", "text": ["Erhöht beim Einsatz der Fertigkeit und des Ultimates die bewirkte Heilung des Trägers um 12%.", "Erhöht beim Einsatz der Fertigkeit und des Ultimates die bewirkte Heilung des Trägers um 15%.", "Erhöht beim Einsatz der Fertigkeit und des Ultimates die bewirkte Heilung des Trägers um 18%.", "Erhöht beim Einsatz der Fertigkeit und des Ultimates die bewirkte Heilung des Trägers um 21%.", "Erhöht beim Einsatz der Fertigkeit und des Ultimates die bewirkte Heilung des Trägers um 24%."]}'),
  ('Für die Reise von morgen', 'Die Harmonie', 4, 'assets/images/light_cones/for_tomorrow_s_journey.png', '{"name": "Verketten", "text": ["Erhöht den ANG des Trägers um 16%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird der verursachte SCH für 1 Rd. um 18% erhöht.", "Erhöht den ANG des Trägers um 20%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird der verursachte SCH für 1 Rd. um 21% erhöht.", "Erhöht den ANG des Trägers um 24%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird der verursachte SCH für 1 Rd. um 24% erhöht.", "Erhöht den ANG des Trägers um 28%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird der verursachte SCH für 1 Rd. um 27% erhöht.", "Erhöht den ANG des Trägers um 32%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird der verursachte SCH für 1 Rd. um 30% erhöht."]}'),
  ('Gefühl der Gemeinsamkeit', 'Der Überfluss', 4, 'assets/images/light_cones/shared_feeling.png', '{"name": "Heilung und Reparatur", "text": ["Erhöht die bewirkte Heilung des Trägers um 10%. Stellt beim Einsatz der Fertigkeit für alle Verbündeten 2 Pkt. Energie wieder her.", "Erhöht die bewirkte Heilung des Trägers um 13%. Stellt beim Einsatz der Fertigkeit für alle Verbündeten 2,5 Pkt. Energie wieder her.", "Erhöht die bewirkte Heilung des Trägers um 15%. Stellt beim Einsatz der Fertigkeit für alle Verbündeten 3 Pkt. Energie wieder her.", "Erhöht die bewirkte Heilung des Trägers um 18%. Stellt beim Einsatz der Fertigkeit für alle Verbündeten 3,5 Pkt. Energie wieder her.", "Erhöht die bewirkte Heilung des Trägers um 20%. Stellt beim Einsatz der Fertigkeit für alle Verbündeten 4 Pkt. Energie wieder her."]}'),
  ('Gegensätzliches', 'Die Jagd', 3, 'assets/images/light_cones/adversarial.png', '{"name": "Allianz", "text": ["Erhöht die GES des Trägers für 2 Rd. um 10%, nachdem er einen Gegner besiegt hat.", "Erhöht die GES des Trägers für 2 Rd. um 12%, nachdem er einen Gegner besiegt hat.", "Erhöht die GES des Trägers für 2 Rd. um 14%, nachdem er einen Gegner besiegt hat.", "Erhöht die GES des Trägers für 2 Rd. um 16%, nachdem er einen Gegner besiegt hat.", "Erhöht die GES des Trägers für 2 Rd. um 18%, nachdem er einen Gegner besiegt hat."]}'),
  ('Gemeinsam in die Zukunft', 'Das Hochgefühl', 4, 'assets/images/light_cones/tomorrow_together.png', '{"name": "Gefährte", "text": ["Erhöht den KRIT-SCH des Trägers um 12%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird das Hochgefühl aller Verbündeten für 1 Rd. um 8% erhöht.", "Erhöht den KRIT-SCH des Trägers um 15%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird das Hochgefühl aller Verbündeten für 1 Rd. um 9% erhöht.", "Erhöht den KRIT-SCH des Trägers um 18%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird das Hochgefühl aller Verbündeten für 1 Rd. um 10% erhöht.", "Erhöht den KRIT-SCH des Trägers um 21%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird das Hochgefühl aller Verbündeten für 1 Rd. um 11% erhöht.", "Erhöht den KRIT-SCH des Trägers um 24%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird das Hochgefühl aller Verbündeten für 1 Rd. um 12% erhöht."]}'),
  ('Gemeinsamer Untergang', 'Die Zerstörung', 3, 'assets/images/light_cones/mutual_demise.png', '{"name": "Legion", "text": ["Liegt der LP-Prozentsatz des Trägers niedriger als 80%, wird seine KRIT-Rate um 12% erhöht.", "Liegt der LP-Prozentsatz des Trägers niedriger als 80%, wird seine KRIT-Rate um 15% erhöht.", "Liegt der LP-Prozentsatz des Trägers niedriger als 80%, wird seine KRIT-Rate um 18% erhöht.", "Liegt der LP-Prozentsatz des Trägers niedriger als 80%, wird seine KRIT-Rate um 21% erhöht.", "Liegt der LP-Prozentsatz des Trägers niedriger als 80%, wird seine KRIT-Rate um 24% erhöht."]}'),
  ('Generalschlüssel', 'Die Gelehrsamkeit', 3, 'assets/images/light_cones/passkey.png', '{"name": "Erleuchtung", "text": ["Stellt nach dem Einsatz der Fertigkeit zusätzlich 8 Pkt. Energie wieder her. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Stellt nach dem Einsatz der Fertigkeit zusätzlich 9 Pkt. Energie wieder her. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Stellt nach dem Einsatz der Fertigkeit zusätzlich 10 Pkt. Energie wieder her. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Stellt nach dem Einsatz der Fertigkeit zusätzlich 11 Pkt. Energie wieder her. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Stellt nach dem Einsatz der Fertigkeit zusätzlich 12 Pkt. Energie wieder her. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Glück des Tages', 'Das Hochgefühl', 4, 'assets/images/light_cones/today_s_good_luck.png', '{"name": "Entscheidung", "text": ["Erhöht die KRIT-Rate des Trägers um 12%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird sein Hochgefühl um 12% erhöht. Dieser Effekt ist bis zu 2-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 14%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird sein Hochgefühl um 14% erhöht. Dieser Effekt ist bis zu 2-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 16%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird sein Hochgefühl um 16% erhöht. Dieser Effekt ist bis zu 2-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 18%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird sein Hochgefühl um 18% erhöht. Dieser Effekt ist bis zu 2-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 20%. Wenn der Träger seine Hochgefühl-Fähigkeit einsetzt, wird sein Hochgefühl um 20% erhöht. Dieser Effekt ist bis zu 2-mal stapelbar."]}'),
  ('Grenzenloser Tanz', 'Die Nichtigkeit', 4, 'assets/images/light_cones/boundless_choreo.png', '{"name": "Prüfen", "text": ["Erhöht die KRIT-Rate des Trägers um 8%. Der Träger verursacht 24% mehr KRIT-SCH bei Gegnern, die verringerte VTD besitzen oder verlangsamt sind.", "Erhöht die KRIT-Rate des Trägers um 10%. Der Träger verursacht 30% mehr KRIT-SCH bei Gegnern, die verringerte VTD besitzen oder verlangsamt sind.", "Erhöht die KRIT-Rate des Trägers um 12%. Der Träger verursacht 36% mehr KRIT-SCH bei Gegnern, die verringerte VTD besitzen oder verlangsamt sind.", "Erhöht die KRIT-Rate des Trägers um 14%. Der Träger verursacht 42% mehr KRIT-SCH bei Gegnern, die verringerte VTD besitzen oder verlangsamt sind.", "Erhöht die KRIT-Rate des Trägers um 16%. Der Träger verursacht 48% mehr KRIT-SCH bei Gegnern, die verringerte VTD besitzen oder verlangsamt sind."]}'),
  ('Gute Nacht, schlaf schön', 'Die Nichtigkeit', 4, 'assets/images/light_cones/good_night_and_sleep_well.png', '{"name": "Malocher", "text": ["Erhöht für jeden Debuff des anvisierten Gegners den zugefügten SCH des Trägers um 12%. Dieser Effekt ist bis zu 3-mal stapelbar und gilt auch für DoT.", "Erhöht für jeden Debuff des anvisierten Gegners den zugefügten SCH des Trägers um 15%. Dieser Effekt ist bis zu 3-mal stapelbar und gilt auch für DoT.", "Erhöht für jeden Debuff des anvisierten Gegners den zugefügten SCH des Trägers um 18%. Dieser Effekt ist bis zu 3-mal stapelbar und gilt auch für DoT.", "Erhöht für jeden Debuff des anvisierten Gegners den zugefügten SCH des Trägers um 21%. Dieser Effekt ist bis zu 3-mal stapelbar und gilt auch für DoT.", "Erhöht für jeden Debuff des anvisierten Gegners den zugefügten SCH des Trägers um 24%. Dieser Effekt ist bis zu 3-mal stapelbar und gilt auch für DoT."]}'),
  ('Heller als die Sonne', 'Die Zerstörung', 5, 'assets/images/light_cones/brighter_than_the_sun.png', '{"name": "Dem Tode trotzend", "text": ["Erhöht die KRIT-Rate des Trägers um 18%. Wenn der Träger seinen Standardangriff ausführt, erhält er 1 Stapelung „Drachenruf“ für 2 Rd. Jede Stapelung Drachenruf erhöht den ANG des Trägers um 18% und seine Energie-Wiederherstellungsrate um 6%. Drachenruf ist bis zu 2-fach stapelbar.", "Erhöht die KRIT-Rate des Trägers um 21%. Wenn der Träger seinen Standardangriff ausführt, erhält er 1 Stapelung „Drachenruf“ für 2 Rd. Jede Stapelung Drachenruf erhöht den ANG des Trägers um 21% und seine Energie-Wiederherstellungsrate um 7%. Drachenruf ist bis zu 2-fach stapelbar.", "Erhöht die KRIT-Rate des Trägers um 24%. Wenn der Träger seinen Standardangriff ausführt, erhält er 1 Stapelung „Drachenruf“ für 2 Rd. Jede Stapelung Drachenruf erhöht den ANG des Trägers um 24% und seine Energie-Wiederherstellungsrate um 8%. Drachenruf ist bis zu 2-fach stapelbar.", "Erhöht die KRIT-Rate des Trägers um 27%. Wenn der Träger seinen Standardangriff ausführt, erhält er 1 Stapelung „Drachenruf“ für 2 Rd. Jede Stapelung Drachenruf erhöht den ANG des Trägers um 27% und seine Energie-Wiederherstellungsrate um 9%. Drachenruf ist bis zu 2-fach stapelbar.", "Erhöht die KRIT-Rate des Trägers um 30%. Wenn der Träger seinen Standardangriff ausführt, erhält er 1 Stapelung „Drachenruf“ für 2 Rd. Jede Stapelung Drachenruf erhöht den ANG des Trägers um 30% und seine Energie-Wiederherstellungsrate um 10%. Drachenruf ist bis zu 2-fach stapelbar."]}'),
  ('Heute ist wieder ein friedlicher Tag', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/today_is_another_peaceful_day.png', '{"name": "Ein Sturm zieht auf", "text": ["Erhöht den verursachten SCH des Trägers nach Kampfeintritt basierend auf seiner max. Energie. Sein SCH wird für jede Energie um 0,20% erhöht. Dabei zählen bis zu 160 Pkt. Energie.", "Erhöht den verursachten SCH des Trägers nach Kampfeintritt basierend auf seiner max. Energie. Sein SCH wird für jede Energie um 0,25% erhöht. Dabei zählen bis zu 160 Pkt. Energie.", "Erhöht den verursachten SCH des Trägers nach Kampfeintritt basierend auf seiner max. Energie. Sein SCH wird für jede Energie um 0,30% erhöht. Dabei zählen bis zu 160 Pkt. Energie.", "Erhöht den verursachten SCH des Trägers nach Kampfeintritt basierend auf seiner max. Energie. Sein SCH wird für jede Energie um 0,35% erhöht. Dabei zählen bis zu 160 Pkt. Energie.", "Erhöht den verursachten SCH des Trägers nach Kampfeintritt basierend auf seiner max. Energie. Sein SCH wird für jede Energie um 0,40% erhöht. Dabei zählen bis zu 160 Pkt. Energie."]}'),
  ('Hey, ich bin hier', 'Der Überfluss', 4, 'assets/images/light_cones/hey_over_here.png', '{"name": "Hab keine Angst", "text": ["Erhöht die max. LP des Trägers um 8%. Erhöht beim Einsatz der Fertigkeit die bewirkte Heilung für 2 Rd. um 16%.", "Erhöht die max. LP des Trägers um 9%. Erhöht beim Einsatz der Fertigkeit die bewirkte Heilung für 2 Rd. um 19%.", "Erhöht die max. LP des Trägers um 10%. Erhöht beim Einsatz der Fertigkeit die bewirkte Heilung für 2 Rd. um 22%.", "Erhöht die max. LP des Trägers um 11%. Erhöht beim Einsatz der Fertigkeit die bewirkte Heilung für 2 Rd. um 25%.", "Erhöht die max. LP des Trägers um 12%. Erhöht beim Einsatz der Fertigkeit die bewirkte Heilung für 2 Rd. um 28%."]}'),
  ('Hochgefühl voller Segen', 'Das Hochgefühl', 5, 'assets/images/light_cones/elation_brimming_with_blessings.png', '{"name": "Eröffnung", "text": ["Erhöht den ANG des Trägers um 20%. Nachdem der Träger seine Fertigkeit oder seinen Ultimate auf einen Verbündeten eingesetzt hat, wird das Hochgefühl des Ziels für 2 Rd. um 12% erhöht.", "Erhöht den ANG des Trägers um 25%. Nachdem der Träger seine Fertigkeit oder seinen Ultimate auf einen Verbündeten eingesetzt hat, wird das Hochgefühl des Ziels für 2 Rd. um 15% erhöht.", "Erhöht den ANG des Trägers um 30%. Nachdem der Träger seine Fertigkeit oder seinen Ultimate auf einen Verbündeten eingesetzt hat, wird das Hochgefühl des Ziels für 2 Rd. um 18% erhöht.", "Erhöht den ANG des Trägers um 35%. Nachdem der Träger seine Fertigkeit oder seinen Ultimate auf einen Verbündeten eingesetzt hat, wird das Hochgefühl des Ziels für 2 Rd. um 21% erhöht.", "Erhöht den ANG des Trägers um 40%. Nachdem der Träger seine Fertigkeit oder seinen Ultimate auf einen Verbündeten eingesetzt hat, wird das Hochgefühl des Ziels für 2 Rd. um 24% erhöht."]}'),
  ('Hochsommer auf den Wellen', 'Das Hochgefühl', 5, 'assets/images/light_cones/summer_rides_the_surf.png', '{"name": "Wellenreiten", "text": ["Erhöht die KRIT-Rate des Trägers um 18%. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, erhält er „Aufwind“. Aufwind erhöht die GES des Trägers um 24%. Wenn sich die eingesetzte Hochgefühl-Fähigkeit von der zuletzt eingesetzten unterscheidet, erhält er zusätzlich „Trend“. Trend erhöht das Hochgefühl des Trägers um 40%.\\nStellt zu Beginn jeder Kampfwelle oder nachdem der Träger jeweils 3-mal eine Hochgefühl-Fähigkeit eingesetzt hat, 1 Fertigkeitspunkt wieder her.", "Erhöht die KRIT-Rate des Trägers um 21%. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, erhält er „Aufwind“. Aufwind erhöht die GES des Trägers um 28%. Wenn sich die eingesetzte Hochgefühl-Fähigkeit von der zuletzt eingesetzten unterscheidet, erhält er zusätzlich „Trend“. Trend erhöht das Hochgefühl des Trägers um 55%.\\nStellt zu Beginn jeder Kampfwelle oder nachdem der Träger jeweils 3-mal eine Hochgefühl-Fähigkeit eingesetzt hat, 1 Fertigkeitspunkt wieder her.", "Erhöht die KRIT-Rate des Trägers um 24%. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, erhält er „Aufwind“. Aufwind erhöht die GES des Trägers um 32%. Wenn sich die eingesetzte Hochgefühl-Fähigkeit von der zuletzt eingesetzten unterscheidet, erhält er zusätzlich „Trend“. Trend erhöht das Hochgefühl des Trägers um 70%.\\nStellt zu Beginn jeder Kampfwelle oder nachdem der Träger jeweils 3-mal eine Hochgefühl-Fähigkeit eingesetzt hat, 1 Fertigkeitspunkt wieder her.", "Erhöht die KRIT-Rate des Trägers um 27%. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, erhält er „Aufwind“. Aufwind erhöht die GES des Trägers um 36%. Wenn sich die eingesetzte Hochgefühl-Fähigkeit von der zuletzt eingesetzten unterscheidet, erhält er zusätzlich „Trend“. Trend erhöht das Hochgefühl des Trägers um 85%.\\nStellt zu Beginn jeder Kampfwelle oder nachdem der Träger jeweils 3-mal eine Hochgefühl-Fähigkeit eingesetzt hat, 1 Fertigkeitspunkt wieder her.", "Erhöht die KRIT-Rate des Trägers um 30%. Wenn der Träger eine Hochgefühl-Fähigkeit einsetzt, erhält er „Aufwind“. Aufwind erhöht die GES des Trägers um 40%. Wenn sich die eingesetzte Hochgefühl-Fähigkeit von der zuletzt eingesetzten unterscheidet, erhält er zusätzlich „Trend“. Trend erhöht das Hochgefühl des Trägers um 100%.\\nStellt zu Beginn jeder Kampfwelle oder nachdem der Träger jeweils 3-mal eine Hochgefühl-Fähigkeit eingesetzt hat, 1 Fertigkeitspunkt wieder her."]}'),
  ('Höhnisches Lachen', 'Das Hochgefühl', 3, 'assets/images/light_cones/sneering.png', '{"name": "Ausgelassenheit", "text": ["Wenn der Aha-Moment ausgelöst wird, wird das Hochgefühl des Trägers um 16% erhöht, bis der Aha-Moment endet.", "Wenn der Aha-Moment ausgelöst wird, wird das Hochgefühl des Trägers um 20% erhöht, bis der Aha-Moment endet.", "Wenn der Aha-Moment ausgelöst wird, wird das Hochgefühl des Trägers um 24% erhöht, bis der Aha-Moment endet.", "Wenn der Aha-Moment ausgelöst wird, wird das Hochgefühl des Trägers um 28% erhöht, bis der Aha-Moment endet.", "Wenn der Aha-Moment ausgelöst wird, wird das Hochgefühl des Trägers um 32% erhöht, bis der Aha-Moment endet."]}'),
  ('Hölle der brennenden Ideale', 'Die Jagd', 5, 'assets/images/light_cones/the_hell_where_ideals_burn.png', '{"name": "Hrunting", "text": ["Erhöht die KRIT-Rate des Trägers um 16%. Wenn die max. Fertigkeitspunkte beim Kampfeintritt 6 oder mehr betragen, wird der ANG des Trägers um 40% erhöht. Jedes Mal, nachdem der Träger eine Fertigkeit eingesetzt hat, wird sein ANG um 10% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 20%. Wenn die max. Fertigkeitspunkte beim Kampfeintritt 6 oder mehr betragen, wird der ANG des Trägers um 50% erhöht. Jedes Mal, nachdem der Träger eine Fertigkeit eingesetzt hat, wird sein ANG um 13% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 24%. Wenn die max. Fertigkeitspunkte beim Kampfeintritt 6 oder mehr betragen, wird der ANG des Trägers um 60% erhöht. Jedes Mal, nachdem der Träger eine Fertigkeit eingesetzt hat, wird sein ANG um 15% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 28%. Wenn die max. Fertigkeitspunkte beim Kampfeintritt 6 oder mehr betragen, wird der ANG des Trägers um 70% erhöht. Jedes Mal, nachdem der Träger eine Fertigkeit eingesetzt hat, wird sein ANG um 18% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 32%. Wenn die max. Fertigkeitspunkte beim Kampfeintritt 6 oder mehr betragen, wird der ANG des Trägers um 80% erhöht. Jedes Mal, nachdem der Träger eine Fertigkeit eingesetzt hat, wird sein ANG um 20% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar."]}'),
  ('Ich bin, wie du mich siehst', 'Die Zerstörung', 5, 'assets/images/light_cones/i_am_as_you_behold.png', '{"name": "Nach Belieben", "text": ["Erhöht den ANG des Trägers um 18% und die Energie-Wiederherstellungsrate um 10%. Wenn der Träger seinen Ultimate einsetzt, wird der diesmal verursachte Ultimate-SCH für jeden verbrauchten Punkt Energie um 0,20% erhöht, bis zu 72%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate einsetzt, erhält er für 3 Rd. „Unterhaltung des Königs“. Solange der Träger Unterhaltung des Königs besitzt, wird der KRIT-SCH aller Verbündeten um 24% erhöht. Effekte desselben Typs können nicht gestapelt werden.", "Erhöht den ANG des Trägers um 21% und die Energie-Wiederherstellungsrate um 12,5%. Wenn der Träger seinen Ultimate einsetzt, wird der diesmal verursachte Ultimate-SCH für jeden verbrauchten Punkt Energie um 0,25% erhöht, bis zu 90%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate einsetzt, erhält er für 3 Rd. „Unterhaltung des Königs“. Solange der Träger Unterhaltung des Königs besitzt, wird der KRIT-SCH aller Verbündeten um 30% erhöht. Effekte desselben Typs können nicht gestapelt werden.", "Erhöht den ANG des Trägers um 24% und die Energie-Wiederherstellungsrate um 15%. Wenn der Träger seinen Ultimate einsetzt, wird der diesmal verursachte Ultimate-SCH für jeden verbrauchten Punkt Energie um 0,30% erhöht, bis zu 108%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate einsetzt, erhält er für 3 Rd. „Unterhaltung des Königs“. Solange der Träger Unterhaltung des Königs besitzt, wird der KRIT-SCH aller Verbündeten um 36% erhöht. Effekte desselben Typs können nicht gestapelt werden.", "Erhöht den ANG des Trägers um 27% und die Energie-Wiederherstellungsrate um 17,5%. Wenn der Träger seinen Ultimate einsetzt, wird der diesmal verursachte Ultimate-SCH für jeden verbrauchten Punkt Energie um 0,35% erhöht, bis zu 126%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate einsetzt, erhält er für 3 Rd. „Unterhaltung des Königs“. Solange der Träger Unterhaltung des Königs besitzt, wird der KRIT-SCH aller Verbündeten um 42% erhöht. Effekte desselben Typs können nicht gestapelt werden.", "Erhöht den ANG des Trägers um 30% und die Energie-Wiederherstellungsrate um 20%. Wenn der Träger seinen Ultimate einsetzt, wird der diesmal verursachte Ultimate-SCH für jeden verbrauchten Punkt Energie um 0,40% erhöht, bis zu 144%. Wenn der Träger in den Kampf eintritt oder seinen Ultimate einsetzt, erhält er für 3 Rd. „Unterhaltung des Königs“. Solange der Träger Unterhaltung des Königs besitzt, wird der KRIT-SCH aller Verbündeten um 48% erhöht. Effekte desselben Typs können nicht gestapelt werden."]}'),
  ('Ich wage die Jagd', 'Die Jagd', 5, 'assets/images/light_cones/i_venture_forth_to_hunt.png', '{"name": "Einschüchtern", "text": ["Erhöht die KRIT-Rate des Trägers um 15%. Wenn der Träger einen Folgeangriff ausführt, erhält er 1 Stapelung „Lichtfluss“, bis zu 2 Stapelungen. Mit jeder Stapelung von Lichtfluss ignoriert der vom Träger verursachte Ultimate-SCH 27% der VTD des Ziels. Wenn die Runde des Trägers endet, wird 1 Stapelung Lichtfluss entfernt.", "Erhöht die KRIT-Rate des Trägers um 17,5%. Wenn der Träger einen Folgeangriff ausführt, erhält er 1 Stapelung „Lichtfluss“, bis zu 2 Stapelungen. Mit jeder Stapelung von Lichtfluss ignoriert der vom Träger verursachte Ultimate-SCH 30% der VTD des Ziels. Wenn die Runde des Trägers endet, wird 1 Stapelung Lichtfluss entfernt.", "Erhöht die KRIT-Rate des Trägers um 20%. Wenn der Träger einen Folgeangriff ausführt, erhält er 1 Stapelung „Lichtfluss“, bis zu 2 Stapelungen. Mit jeder Stapelung von Lichtfluss ignoriert der vom Träger verursachte Ultimate-SCH 33% der VTD des Ziels. Wenn die Runde des Trägers endet, wird 1 Stapelung Lichtfluss entfernt.", "Erhöht die KRIT-Rate des Trägers um 22,5%. Wenn der Träger einen Folgeangriff ausführt, erhält er 1 Stapelung „Lichtfluss“, bis zu 2 Stapelungen. Mit jeder Stapelung von Lichtfluss ignoriert der vom Träger verursachte Ultimate-SCH 36% der VTD des Ziels. Wenn die Runde des Trägers endet, wird 1 Stapelung Lichtfluss entfernt.", "Erhöht die KRIT-Rate des Trägers um 25%. Wenn der Träger einen Folgeangriff ausführt, erhält er 1 Stapelung „Lichtfluss“, bis zu 2 Stapelungen. Mit jeder Stapelung von Lichtfluss ignoriert der vom Träger verursachte Ultimate-SCH 39% der VTD des Ziels. Wenn die Runde des Trägers endet, wird 1 Stapelung Lichtfluss entfernt."]}'),
  ('Ihre Augen sind bereits geschlossen', 'Die Bewahrung', 5, 'assets/images/light_cones/she_already_shut_her_eyes.png', '{"name": "Sicht", "text": ["Erhöht die max. LP des Trägers um 24% und Energie-Wiederherstellungsrate um 12%. Wenn die LP des Trägers reduziert werden, wird der von allen Verbündeten verursachte SCH für 2 Rd. um 9% erhöht.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten LP in Höhe von 80% der jeweiligen verlorenen LP wiederhergestellt.", "Erhöht die max. LP des Trägers um 28% und Energie-Wiederherstellungsrate um 14%. Wenn die LP des Trägers reduziert werden, wird der von allen Verbündeten verursachte SCH für 2 Rd. um 10,5% erhöht.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten LP in Höhe von 85% der jeweiligen verlorenen LP wiederhergestellt.", "Erhöht die max. LP des Trägers um 32% und Energie-Wiederherstellungsrate um 16%. Wenn die LP des Trägers reduziert werden, wird der von allen Verbündeten verursachte SCH für 2 Rd. um 12% erhöht.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten LP in Höhe von 90% der jeweiligen verlorenen LP wiederhergestellt.", "Erhöht die max. LP des Trägers um 36% und Energie-Wiederherstellungsrate um 18%. Wenn die LP des Trägers reduziert werden, wird der von allen Verbündeten verursachte SCH für 2 Rd. um 13,5% erhöht.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten LP in Höhe von 95% der jeweiligen verlorenen LP wiederhergestellt.", "Erhöht die max. LP des Trägers um 40% und Energie-Wiederherstellungsrate um 20%. Wenn die LP des Trägers reduziert werden, wird der von allen Verbündeten verursachte SCH für 2 Rd. um 15% erhöht.\\nZu Beginn jeder Kampfwelle werden bei allen Verbündeten LP in Höhe von 100% der jeweiligen verlorenen LP wiederhergestellt."]}'),
  ('Im Namen der Welt', 'Die Nichtigkeit', 5, 'assets/images/light_cones/in_the_name_of_the_world.png', '{"name": "Nachkomme", "text": ["Erhöht den verursachten SCH des Trägers gegen Gegner mit Debuff um 24%. Erhöht beim Einsatz der Fertigkeit seine Effekt-Trefferrate um 18% und seinen ANG um 24%.", "Erhöht den verursachten SCH des Trägers gegen Gegner mit Debuff um 28%. Erhöht beim Einsatz der Fertigkeit seine Effekt-Trefferrate um 21% und seinen ANG um 28%.", "Erhöht den verursachten SCH des Trägers gegen Gegner mit Debuff um 32%. Erhöht beim Einsatz der Fertigkeit seine Effekt-Trefferrate um 24% und seinen ANG um 32%.", "Erhöht den verursachten SCH des Trägers gegen Gegner mit Debuff um 36%. Erhöht beim Einsatz der Fertigkeit seine Effekt-Trefferrate um 27% und seinen ANG um 36%.", "Erhöht den verursachten SCH des Trägers gegen Gegner mit Debuff um 40%. Erhöht beim Einsatz der Fertigkeit seine Effekt-Trefferrate um 30% und seinen ANG um 40%."]}'),
  ('In Gold gewebte Zeit', 'Das Gedenken', 5, 'assets/images/light_cones/time_woven_into_gold.png', '{"name": "Gestalten", "text": ["Erhöht die Basis-GES des Trägers um 12. Nach einem Angriff durch den Träger oder seinen Memogeist erhält der Träger 1 Stapelung „Brokat“. Jede Stapelung von Brokat erhöht den KRIT-SCH des Trägers und seines Memogeistes um 9%, bis zu 6 Stapelungen. Wenn die max. Stapelzahl erreicht wird, erhöht jede Stapelung von Brokat den verursachten Standardangriff-SCH zusätzlich um 9%.", "Erhöht die Basis-GES des Trägers um 14. Nach einem Angriff durch den Träger oder seinen Memogeist erhält der Träger 1 Stapelung „Brokat“. Jede Stapelung von Brokat erhöht den KRIT-SCH des Trägers und seines Memogeistes um 10,5%, bis zu 6 Stapelungen. Wenn die max. Stapelzahl erreicht wird, erhöht jede Stapelung von Brokat den verursachten Standardangriff-SCH zusätzlich um 10,5%.", "Erhöht die Basis-GES des Trägers um 16. Nach einem Angriff durch den Träger oder seinen Memogeist erhält der Träger 1 Stapelung „Brokat“. Jede Stapelung von Brokat erhöht den KRIT-SCH des Trägers und seines Memogeistes um 12%, bis zu 6 Stapelungen. Wenn die max. Stapelzahl erreicht wird, erhöht jede Stapelung von Brokat den verursachten Standardangriff-SCH zusätzlich um 12%.", "Erhöht die Basis-GES des Trägers um 18. Nach einem Angriff durch den Träger oder seinen Memogeist erhält der Träger 1 Stapelung „Brokat“. Jede Stapelung von Brokat erhöht den KRIT-SCH des Trägers und seines Memogeistes um 13,5%, bis zu 6 Stapelungen. Wenn die max. Stapelzahl erreicht wird, erhöht jede Stapelung von Brokat den verursachten Standardangriff-SCH zusätzlich um 13,5%.", "Erhöht die Basis-GES des Trägers um 20. Nach einem Angriff durch den Träger oder seinen Memogeist erhält der Träger 1 Stapelung „Brokat“. Jede Stapelung von Brokat erhöht den KRIT-SCH des Trägers und seines Memogeistes um 15%, bis zu 6 Stapelungen. Wenn die max. Stapelzahl erreicht wird, erhöht jede Stapelung von Brokat den verursachten Standardangriff-SCH zusätzlich um 15%."]}'),
  ('In der Nacht', 'Die Jagd', 5, 'assets/images/light_cones/in_the_night.png', '{"name": "Blumen und Schmetterlinge", "text": ["Erhöht die KRIT-Rate des Trägers um 18%. Liegt die GES des Trägers im Kampf über 100, wird für jede weitere 10 Pkt. GES der durch Standardangriffe und Fertigkeiten verursachte SCH um 6% erhöht. Außerdem wird der KRIT-SCH des Ultimates um 12% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 21%. Liegt die GES des Trägers im Kampf über 100, wird für jede weitere 10 Pkt. GES der durch Standardangriffe und Fertigkeiten verursachte SCH um 7% erhöht. Außerdem wird der KRIT-SCH des Ultimates um 14% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 24%. Liegt die GES des Trägers im Kampf über 100, wird für jede weitere 10 Pkt. GES der durch Standardangriffe und Fertigkeiten verursachte SCH um 8% erhöht. Außerdem wird der KRIT-SCH des Ultimates um 16% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 27%. Liegt die GES des Trägers im Kampf über 100, wird für jede weitere 10 Pkt. GES der durch Standardangriffe und Fertigkeiten verursachte SCH um 9% erhöht. Außerdem wird der KRIT-SCH des Ultimates um 18% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar.", "Erhöht die KRIT-Rate des Trägers um 30%. Liegt die GES des Trägers im Kampf über 100, wird für jede weitere 10 Pkt. GES der durch Standardangriffe und Fertigkeiten verursachte SCH um 10% erhöht. Außerdem wird der KRIT-SCH des Ultimates um 20% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar."]}'),
  ('Jene unzähligen Frühlinge', 'Die Nichtigkeit', 5, 'assets/images/light_cones/those_many_springs.png', '{"name": "Weltliches hinterlässt keine Spur", "text": ["Erhöht die Effekt-Trefferrate des Trägers um 60%. Nachdem der Träger Standardangriff, Fertigkeit oder Ultimate auf einen Gegner angewendet hat, besteht eine Grundchance von 60%, diesen Gegner mit „Ungerüstet“ zu belegen. Mit diesem Status wird der erlittene SCH des Gegners für 2 Rd. um 10% erhöht. Wenn das Ziel sich im vom Träger verursachten DoT-Status befindet, besteht eine Grundchance von 60%, den vom Träger zugefügten Status Ungerüstet zu „In die Enge“ aufzuwerten, wodurch der erlittene SCH des Gegners für 2 Rd. zusätzlich um 14% erhöht wird. Während dieser Dauer kann der Träger beim Ziel nicht Ungerüstet verursachen.", "Erhöht die Effekt-Trefferrate des Trägers um 70%. Nachdem der Träger Standardangriff, Fertigkeit oder Ultimate auf einen Gegner angewendet hat, besteht eine Grundchance von 60%, diesen Gegner mit „Ungerüstet“ zu belegen. Mit diesem Status wird der erlittene SCH des Gegners für 2 Rd. um 12% erhöht. Wenn das Ziel sich im vom Träger verursachten DoT-Status befindet, besteht eine Grundchance von 60%, den vom Träger zugefügten Status Ungerüstet zu „In die Enge“ aufzuwerten, wodurch der erlittene SCH des Gegners für 2 Rd. zusätzlich um 16% erhöht wird. Während dieser Dauer kann der Träger beim Ziel nicht Ungerüstet verursachen.", "Erhöht die Effekt-Trefferrate des Trägers um 80%. Nachdem der Träger Standardangriff, Fertigkeit oder Ultimate auf einen Gegner angewendet hat, besteht eine Grundchance von 60%, diesen Gegner mit „Ungerüstet“ zu belegen. Mit diesem Status wird der erlittene SCH des Gegners für 2 Rd. um 14% erhöht. Wenn das Ziel sich im vom Träger verursachten DoT-Status befindet, besteht eine Grundchance von 60%, den vom Träger zugefügten Status Ungerüstet zu „In die Enge“ aufzuwerten, wodurch der erlittene SCH des Gegners für 2 Rd. zusätzlich um 18% erhöht wird. Während dieser Dauer kann der Träger beim Ziel nicht Ungerüstet verursachen.", "Erhöht die Effekt-Trefferrate des Trägers um 90%. Nachdem der Träger Standardangriff, Fertigkeit oder Ultimate auf einen Gegner angewendet hat, besteht eine Grundchance von 60%, diesen Gegner mit „Ungerüstet“ zu belegen. Mit diesem Status wird der erlittene SCH des Gegners für 2 Rd. um 16% erhöht. Wenn das Ziel sich im vom Träger verursachten DoT-Status befindet, besteht eine Grundchance von 60%, den vom Träger zugefügten Status Ungerüstet zu „In die Enge“ aufzuwerten, wodurch der erlittene SCH des Gegners für 2 Rd. zusätzlich um 20% erhöht wird. Während dieser Dauer kann der Träger beim Ziel nicht Ungerüstet verursachen.", "Erhöht die Effekt-Trefferrate des Trägers um 100%. Nachdem der Träger Standardangriff, Fertigkeit oder Ultimate auf einen Gegner angewendet hat, besteht eine Grundchance von 60%, diesen Gegner mit „Ungerüstet“ zu belegen. Mit diesem Status wird der erlittene SCH des Gegners für 2 Rd. um 18% erhöht. Wenn das Ziel sich im vom Träger verursachten DoT-Status befindet, besteht eine Grundchance von 60%, den vom Träger zugefügten Status Ungerüstet zu „In die Enge“ aufzuwerten, wodurch der erlittene SCH des Gegners für 2 Rd. zusätzlich um 22% erhöht wird. Während dieser Dauer kann der Träger beim Ziel nicht Ungerüstet verursachen."]}'),
  ('Jugend in Erwartung der Entflammung', 'Die Harmonie', 4, 'assets/images/light_cones/poised_to_bloom.png', '{"name": "Verliere nicht, vergiss nicht", "text": ["Erhöht den ANG des Trägers um 16%. Wenn beim Kampfeintritt zwei oder mehr Verbündete demselben Pfad folgen, wird der KRIT-SCH dieser Figuren um 16% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den ANG des Trägers um 20%. Wenn beim Kampfeintritt zwei oder mehr Verbündete demselben Pfad folgen, wird der KRIT-SCH dieser Figuren um 20% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den ANG des Trägers um 24%. Wenn beim Kampfeintritt zwei oder mehr Verbündete demselben Pfad folgen, wird der KRIT-SCH dieser Figuren um 24% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den ANG des Trägers um 28%. Wenn beim Kampfeintritt zwei oder mehr Verbündete demselben Pfad folgen, wird der KRIT-SCH dieser Figuren um 28% erhöht. Effekte desselben Typs sind nicht stapelbar.", "Erhöht den ANG des Trägers um 32%. Wenn beim Kampfeintritt zwei oder mehr Verbündete demselben Pfad folgen, wird der KRIT-SCH dieser Figuren um 32% erhöht. Effekte desselben Typs sind nicht stapelbar."]}'),
  ('Kleiner Kurzurlaub', 'Das Hochgefühl', 4, 'assets/images/light_cones/a_little_getaway.png', '{"name": "Geflüster", "text": ["Erhöht das Hochgefühl des Trägers um 20%. Beim Einsatz der Hochgefühl-Fähigkeit ignoriert der Träger 8% der VTD des Ziels.", "Erhöht das Hochgefühl des Trägers um 25%. Beim Einsatz der Hochgefühl-Fähigkeit ignoriert der Träger 10% der VTD des Ziels.", "Erhöht das Hochgefühl des Trägers um 30%. Beim Einsatz der Hochgefühl-Fähigkeit ignoriert der Träger 12% der VTD des Ziels.", "Erhöht das Hochgefühl des Trägers um 35%. Beim Einsatz der Hochgefühl-Fähigkeit ignoriert der Träger 14% der VTD des Ziels.", "Erhöht das Hochgefühl des Trägers um 40%. Beim Einsatz der Hochgefühl-Fähigkeit ignoriert der Träger 16% der VTD des Ziels."]}'),
  ('Konzert für zwei', 'Die Bewahrung', 4, 'assets/images/light_cones/concert_for_two.png', '{"name": "Inspirieren", "text": ["Erhöht die VTD des Trägers um 16%. Für jede Figur auf dem Kampffeld, die einen Schild trägt, wird der verursachte SCH des Trägers um 4% erhöht.", "Erhöht die VTD des Trägers um 20%. Für jede Figur auf dem Kampffeld, die einen Schild trägt, wird der verursachte SCH des Trägers um 5% erhöht.", "Erhöht die VTD des Trägers um 24%. Für jede Figur auf dem Kampffeld, die einen Schild trägt, wird der verursachte SCH des Trägers um 6% erhöht.", "Erhöht die VTD des Trägers um 28%. Für jede Figur auf dem Kampffeld, die einen Schild trägt, wird der verursachte SCH des Trägers um 7% erhöht.", "Erhöht die VTD des Trägers um 32%. Für jede Figur auf dem Kampffeld, die einen Schild trägt, wird der verursachte SCH des Trägers um 8% erhöht."]}'),
  ('Landaus Wahl', 'Die Bewahrung', 4, 'assets/images/light_cones/landau_s_choice.png', '{"name": "Die Zeit fliegt davon", "text": ["Erhöht die Chance, dass der Träger angegriffen wird. Verringert gleichzeitig den erlittenen SCH um 16%.", "Erhöht die Chance, dass der Träger angegriffen wird. Verringert gleichzeitig den erlittenen SCH um 18%.", "Erhöht die Chance, dass der Träger angegriffen wird. Verringert gleichzeitig den erlittenen SCH um 20%.", "Erhöht die Chance, dass der Träger angegriffen wird. Verringert gleichzeitig den erlittenen SCH um 22%.", "Erhöht die Chance, dass der Träger angegriffen wird. Verringert gleichzeitig den erlittenen SCH um 24%."]}'),
  ('Leere', 'Die Nichtigkeit', 3, 'assets/images/light_cones/void.png', '{"name": "Niedergang", "text": ["Erhöht zu Beginn des Kampfes die Effekt-Trefferrate des Trägers für 3 Rd. um 20%.", "Erhöht zu Beginn des Kampfes die Effekt-Trefferrate des Trägers für 3 Rd. um 25%.", "Erhöht zu Beginn des Kampfes die Effekt-Trefferrate des Trägers für 3 Rd. um 30%.", "Erhöht zu Beginn des Kampfes die Effekt-Trefferrate des Trägers für 3 Rd. um 35%.", "Erhöht zu Beginn des Kampfes die Effekt-Trefferrate des Trägers für 3 Rd. um 40%."]}'),
  ('Liebe, so ewig wie dieser Moment', 'Das Gedenken', 5, 'assets/images/light_cones/this_love_forever.png', '{"name": "Versprechen", "text": ["Erhöht die GES des Trägers um 18%. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Verbündeten anwendet, wird „Leer“ erhalten, was den erlittenen SCH aller Gegner um 10% erhöht. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Gegner anwendet, wird „Vers“ erhalten, was den KRIT-SCH aller Verbündeten um 16% erhöht. Wenn der Memogeist des Trägers Leer und Vers gleichzeitig besitzt, wird der Effekt von beiden um 60% erhöht.", "Erhöht die GES des Trägers um 21%. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Verbündeten anwendet, wird „Leer“ erhalten, was den erlittenen SCH aller Gegner um 12% erhöht. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Gegner anwendet, wird „Vers“ erhalten, was den KRIT-SCH aller Verbündeten um 19% erhöht. Wenn der Memogeist des Trägers Leer und Vers gleichzeitig besitzt, wird der Effekt von beiden um 65% erhöht.", "Erhöht die GES des Trägers um 24%. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Verbündeten anwendet, wird „Leer“ erhalten, was den erlittenen SCH aller Gegner um 14% erhöht. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Gegner anwendet, wird „Vers“ erhalten, was den KRIT-SCH aller Verbündeten um 22% erhöht. Wenn der Memogeist des Trägers Leer und Vers gleichzeitig besitzt, wird der Effekt von beiden um 70% erhöht.", "Erhöht die GES des Trägers um 27%. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Verbündeten anwendet, wird „Leer“ erhalten, was den erlittenen SCH aller Gegner um 16% erhöht. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Gegner anwendet, wird „Vers“ erhalten, was den KRIT-SCH aller Verbündeten um 25% erhöht. Wenn der Memogeist des Trägers Leer und Vers gleichzeitig besitzt, wird der Effekt von beiden um 75% erhöht.", "Erhöht die GES des Trägers um 30%. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Verbündeten anwendet, wird „Leer“ erhalten, was den erlittenen SCH aller Gegner um 18% erhöht. Wenn der Memogeist des Trägers eine Memogeist-Technik auf einen Gegner anwendet, wird „Vers“ erhalten, was den KRIT-SCH aller Verbündeten um 28% erhöht. Wenn der Memogeist des Trägers Leer und Vers gleichzeitig besitzt, wird der Effekt von beiden um 80% erhöht."]}'),
  ('Mehr Schwitzen, weniger Weinen', 'Das Gedenken', 4, 'assets/images/light_cones/sweat_now_cry_less.png', '{"name": "Komm trainieren!", "text": ["Erhöht die KRIT-Rate des Trägers um 12%. Wenn der Memogeist des Trägers auf dem Kampffeld ist, wird der von ihm und dem Memogeist verursachte SCH um 24% erhöht.", "Erhöht die KRIT-Rate des Trägers um 14%. Wenn der Memogeist des Trägers auf dem Kampffeld ist, wird der von ihm und dem Memogeist verursachte SCH um 27% erhöht.", "Erhöht die KRIT-Rate des Trägers um 16%. Wenn der Memogeist des Trägers auf dem Kampffeld ist, wird der von ihm und dem Memogeist verursachte SCH um 30% erhöht.", "Erhöht die KRIT-Rate des Trägers um 18%. Wenn der Memogeist des Trägers auf dem Kampffeld ist, wird der von ihm und dem Memogeist verursachte SCH um 33% erhöht.", "Erhöht die KRIT-Rate des Trägers um 20%. Wenn der Memogeist des Trägers auf dem Kampffeld ist, wird der von ihm und dem Memogeist verursachte SCH um 36% erhöht."]}'),
  ('Moment des Sieges', 'Die Bewahrung', 5, 'assets/images/light_cones/moment_of_victory.png', '{"name": "Urteilsspruch", "text": ["Erhöht die VTD des Trägers um 24% und die Effekt-Trefferrate um 24%. Erhöht die Chance, dass der Träger von Gegnern angegriffen wird. Wird der Träger angegriffen, wird die VTD bis zum Ende seiner Runde zusätzlich um 24% erhöht.", "Erhöht die VTD des Trägers um 28% und die Effekt-Trefferrate um 28%. Erhöht die Chance, dass der Träger von Gegnern angegriffen wird. Wird der Träger angegriffen, wird die VTD bis zum Ende seiner Runde zusätzlich um 28% erhöht.", "Erhöht die VTD des Trägers um 32% und die Effekt-Trefferrate um 32%. Erhöht die Chance, dass der Träger von Gegnern angegriffen wird. Wird der Träger angegriffen, wird die VTD bis zum Ende seiner Runde zusätzlich um 32% erhöht.", "Erhöht die VTD des Trägers um 36% und die Effekt-Trefferrate um 36%. Erhöht die Chance, dass der Träger von Gegnern angegriffen wird. Wird der Träger angegriffen, wird die VTD bis zum Ende seiner Runde zusätzlich um 36% erhöht.", "Erhöht die VTD des Trägers um 40% und die Effekt-Trefferrate um 40%. Erhöht die Chance, dass der Träger von Gegnern angegriffen wird. Wird der Träger angegriffen, wird die VTD bis zum Ende seiner Runde zusätzlich um 40% erhöht."]}'),
  ('Mögen Regenbögen am Himmel bleiben', 'Das Gedenken', 5, 'assets/images/light_cones/long_may_rainbows_adorn_the_sky.png', '{"name": "Tolerant", "text": ["Erhöht die GES des Trägers um 18%. Der Träger verbraucht beim Einsatz von Standardangriff, Fertigkeit oder Ultimate LP aller Verbündeten in Höhe von 1% ihrer aktuellen LP. Lässt den Memogeist des Trägers basierend auf seinem Typ nach seinem nächsten Angriff dem Angriffsziel 1-mal zusätzlichen SCH in Höhe von 250% der gesamten verbrauchten LP zufügen. Anschließend werden die verbrauchten LP zurückgesetzt. Wenn der Memogeist des Trägers seine Memogeist-Technik einsetzt, wird der erlittene SCH aller Gegner für 2 Rd. um 18% erhöht. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht die GES des Trägers um 21%. Der Träger verbraucht beim Einsatz von Standardangriff, Fertigkeit oder Ultimate LP aller Verbündeten in Höhe von 1,2% ihrer aktuellen LP. Lässt den Memogeist des Trägers basierend auf seinem Typ nach seinem nächsten Angriff dem Angriffsziel 1-mal zusätzlichen SCH in Höhe von 312,5% der gesamten verbrauchten LP zufügen. Anschließend werden die verbrauchten LP zurückgesetzt. Wenn der Memogeist des Trägers seine Memogeist-Technik einsetzt, wird der erlittene SCH aller Gegner für 2 Rd. um 22,5% erhöht. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht die GES des Trägers um 24%. Der Träger verbraucht beim Einsatz von Standardangriff, Fertigkeit oder Ultimate LP aller Verbündeten in Höhe von 1,5% ihrer aktuellen LP. Lässt den Memogeist des Trägers basierend auf seinem Typ nach seinem nächsten Angriff dem Angriffsziel 1-mal zusätzlichen SCH in Höhe von 375% der gesamten verbrauchten LP zufügen. Anschließend werden die verbrauchten LP zurückgesetzt. Wenn der Memogeist des Trägers seine Memogeist-Technik einsetzt, wird der erlittene SCH aller Gegner für 2 Rd. um 27% erhöht. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht die GES des Trägers um 27%. Der Träger verbraucht beim Einsatz von Standardangriff, Fertigkeit oder Ultimate LP aller Verbündeten in Höhe von 1,8% ihrer aktuellen LP. Lässt den Memogeist des Trägers basierend auf seinem Typ nach seinem nächsten Angriff dem Angriffsziel 1-mal zusätzlichen SCH in Höhe von 437,5% der gesamten verbrauchten LP zufügen. Anschließend werden die verbrauchten LP zurückgesetzt. Wenn der Memogeist des Trägers seine Memogeist-Technik einsetzt, wird der erlittene SCH aller Gegner für 2 Rd. um 31,5% erhöht. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht die GES des Trägers um 30%. Der Träger verbraucht beim Einsatz von Standardangriff, Fertigkeit oder Ultimate LP aller Verbündeten in Höhe von 2% ihrer aktuellen LP. Lässt den Memogeist des Trägers basierend auf seinem Typ nach seinem nächsten Angriff dem Angriffsziel 1-mal zusätzlichen SCH in Höhe von 500% der gesamten verbrauchten LP zufügen. Anschließend werden die verbrauchten LP zurückgesetzt. Wenn der Memogeist des Trägers seine Memogeist-Technik einsetzt, wird der erlittene SCH aller Gegner für 2 Rd. um 36% erhöht. Effekte der gleichen Art sind nicht stapelbar."]}'),
  ('Mögen Reisen für immer friedlich sein', 'Die Bewahrung', 4, 'assets/images/light_cones/journey_forever_peaceful.png', '{"name": "Glückstraum", "text": ["Erhöht die vom Träger gewährte Schildmenge um 12%. Wenn ein Verbündeter einen Schild hat, wird der verursachte SCH um 12% erhöht.", "Erhöht die vom Träger gewährte Schildmenge um 15%. Wenn ein Verbündeter einen Schild hat, wird der verursachte SCH um 14% erhöht.", "Erhöht die vom Träger gewährte Schildmenge um 18%. Wenn ein Verbündeter einen Schild hat, wird der verursachte SCH um 16% erhöht.", "Erhöht die vom Träger gewährte Schildmenge um 21%. Wenn ein Verbündeter einen Schild hat, wird der verursachte SCH um 18% erhöht.", "Erhöht die vom Träger gewährte Schildmenge um 24%. Wenn ein Verbündeter einen Schild hat, wird der verursachte SCH um 20% erhöht."]}'),
  ('Nach dem Fall der Harmonie', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/after_the_charmony_fall.png', '{"name": "Stille", "text": ["Erhöht den Brucheffekt des Trägers um 28%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird seine GES für 2 Rd. um 8% erhöht.", "Erhöht den Brucheffekt des Trägers um 35%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird seine GES für 2 Rd. um 10% erhöht.", "Erhöht den Brucheffekt des Trägers um 42%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird seine GES für 2 Rd. um 12% erhöht.", "Erhöht den Brucheffekt des Trägers um 49%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird seine GES für 2 Rd. um 14% erhöht.", "Erhöht den Brucheffekt des Trägers um 56%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird seine GES für 2 Rd. um 16% erhöht."]}'),
  ('Nacht auf der Milchstraße', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/night_on_the_milky_way.png', '{"name": "Meteoritenschwarm", "text": ["Erhöht für jeden Gegner auf dem Kampffeld den ANG des Trägers jeweils um 9%. Dieser Effekt ist bis zu 5-mal stapelbar. Wenn die Schwäche eines Gegners gebrochen wird, wird der durch den Träger verursachte SCH für 1 Rd. um 30% erhöht.", "Erhöht für jeden Gegner auf dem Kampffeld den ANG des Trägers jeweils um 10,5%. Dieser Effekt ist bis zu 5-mal stapelbar. Wenn die Schwäche eines Gegners gebrochen wird, wird der durch den Träger verursachte SCH für 1 Rd. um 35% erhöht.", "Erhöht für jeden Gegner auf dem Kampffeld den ANG des Trägers jeweils um 12%. Dieser Effekt ist bis zu 5-mal stapelbar. Wenn die Schwäche eines Gegners gebrochen wird, wird der durch den Träger verursachte SCH für 1 Rd. um 40% erhöht.", "Erhöht für jeden Gegner auf dem Kampffeld den ANG des Trägers jeweils um 13,5%. Dieser Effekt ist bis zu 5-mal stapelbar. Wenn die Schwäche eines Gegners gebrochen wird, wird der durch den Träger verursachte SCH für 1 Rd. um 45% erhöht.", "Erhöht für jeden Gegner auf dem Kampffeld den ANG des Trägers jeweils um 15%. Dieser Effekt ist bis zu 5-mal stapelbar. Wenn die Schwäche eines Gegners gebrochen wird, wird der durch den Träger verursachte SCH für 1 Rd. um 50% erhöht."]}'),
  ('Nacht der Angst', 'Der Überfluss', 5, 'assets/images/light_cones/night_of_fright.png', '{"name": "Atme tief durch", "text": ["Erhöht die Energie-Wiederherstellungsrate des Trägers um 12%. Wenn ein Verbündeter seinen Ultimate einsetzt, stellt der Träger bei einem Verbündeten mit dem niedrigsten LP-Prozentsatz LP in Höhe von 10% seiner max. LP wieder her. Wenn der Träger Verbündete heilt, wird der ANG des geheilten Verbündeten um 2,4% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar und hält 2 Rd. an.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 14%. Wenn ein Verbündeter seinen Ultimate einsetzt, stellt der Träger bei einem Verbündeten mit dem niedrigsten LP-Prozentsatz LP in Höhe von 11% seiner max. LP wieder her. Wenn der Träger Verbündete heilt, wird der ANG des geheilten Verbündeten um 2,8% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar und hält 2 Rd. an.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 16%. Wenn ein Verbündeter seinen Ultimate einsetzt, stellt der Träger bei einem Verbündeten mit dem niedrigsten LP-Prozentsatz LP in Höhe von 12% seiner max. LP wieder her. Wenn der Träger Verbündete heilt, wird der ANG des geheilten Verbündeten um 3,2% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar und hält 2 Rd. an.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 18%. Wenn ein Verbündeter seinen Ultimate einsetzt, stellt der Träger bei einem Verbündeten mit dem niedrigsten LP-Prozentsatz LP in Höhe von 13% seiner max. LP wieder her. Wenn der Träger Verbündete heilt, wird der ANG des geheilten Verbündeten um 3,6% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar und hält 2 Rd. an.", "Erhöht die Energie-Wiederherstellungsrate des Trägers um 20%. Wenn ein Verbündeter seinen Ultimate einsetzt, stellt der Träger bei einem Verbündeten mit dem niedrigsten LP-Prozentsatz LP in Höhe von 14% seiner max. LP wieder her. Wenn der Träger Verbündete heilt, wird der ANG des geheilten Verbündeten um 4% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar und hält 2 Rd. an."]}'),
  ('Neue Überreste des versengenden Fegefeuers', 'Die Nichtigkeit', 5, 'assets/images/light_cones/reforged_in_hellfire.png', '{"name": "Verfeinern", "text": ["Erhöht die max. LP des Trägers um 30%. Stellt zu Beginn der Runde des Trägers eine feste Menge von 20 Energie wieder her. Dieser Effekt kann 1-mal pro Kampfwelle ausgelöst werden. Nachdem der Träger mit der Fertigkeit angegriffen hat, wird das Ziel für 2 Rd. in den Status „Fegefeuer“ versetzt. Im Status Fegefeuer wird der erlittene KRIT-SCH des Ziels um 30% und sein erlittener KRIT-SCH, der durch den Träger verursacht wird, zusätzlich um 30% erhöht.", "Erhöht die max. LP des Trägers um 38%. Stellt zu Beginn der Runde des Trägers eine feste Menge von 20 Energie wieder her. Dieser Effekt kann 1-mal pro Kampfwelle ausgelöst werden. Nachdem der Träger mit der Fertigkeit angegriffen hat, wird das Ziel für 2 Rd. in den Status „Fegefeuer“ versetzt. Im Status Fegefeuer wird der erlittene KRIT-SCH des Ziels um 38% und sein erlittener KRIT-SCH, der durch den Träger verursacht wird, zusätzlich um 38% erhöht.", "Erhöht die max. LP des Trägers um 45%. Stellt zu Beginn der Runde des Trägers eine feste Menge von 20 Energie wieder her. Dieser Effekt kann 1-mal pro Kampfwelle ausgelöst werden. Nachdem der Träger mit der Fertigkeit angegriffen hat, wird das Ziel für 2 Rd. in den Status „Fegefeuer“ versetzt. Im Status Fegefeuer wird der erlittene KRIT-SCH des Ziels um 45% und sein erlittener KRIT-SCH, der durch den Träger verursacht wird, zusätzlich um 45% erhöht.", "Erhöht die max. LP des Trägers um 53%. Stellt zu Beginn der Runde des Trägers eine feste Menge von 20 Energie wieder her. Dieser Effekt kann 1-mal pro Kampfwelle ausgelöst werden. Nachdem der Träger mit der Fertigkeit angegriffen hat, wird das Ziel für 2 Rd. in den Status „Fegefeuer“ versetzt. Im Status Fegefeuer wird der erlittene KRIT-SCH des Ziels um 53% und sein erlittener KRIT-SCH, der durch den Träger verursacht wird, zusätzlich um 53% erhöht.", "Erhöht die max. LP des Trägers um 60%. Stellt zu Beginn der Runde des Trägers eine feste Menge von 20 Energie wieder her. Dieser Effekt kann 1-mal pro Kampfwelle ausgelöst werden. Nachdem der Träger mit der Fertigkeit angegriffen hat, wird das Ziel für 2 Rd. in den Status „Fegefeuer“ versetzt. Im Status Fegefeuer wird der erlittene KRIT-SCH des Ziels um 60% und sein erlittener KRIT-SCH, der durch den Träger verursacht wird, zusätzlich um 60% erhöht."]}'),
  ('Ninja-Aufzeichnung: Klangjagd', 'Die Zerstörung', 4, 'assets/images/light_cones/ninja_record_sound_hunt.png', '{"name": "Vorhang auf!", "text": ["Erhöht die max. LP des Trägers um 12%. Nachdem der Träger LP verloren oder wiederhergestellt hat, wird sein KRIT-SCH für 2 Rd. um 18% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 15%. Nachdem der Träger LP verloren oder wiederhergestellt hat, wird sein KRIT-SCH für 2 Rd. um 23% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 18%. Nachdem der Träger LP verloren oder wiederhergestellt hat, wird sein KRIT-SCH für 2 Rd. um 27% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 21%. Nachdem der Träger LP verloren oder wiederhergestellt hat, wird sein KRIT-SCH für 2 Rd. um 32% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden.", "Erhöht die max. LP des Trägers um 24%. Nachdem der Träger LP verloren oder wiederhergestellt hat, wird sein KRIT-SCH für 2 Rd. um 36% erhöht. Dieser Effekt kann nur 1-mal pro Runde ausgelöst werden."]}'),
  ('Ninja-Kodex: Blendender Schattenbrecher', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/ninjutsu_inscription_dazzling_evilbreaker.png', '{"name": "Exorzismus", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Stellt beim Kampfeintritt sofort 30 Pkt. Energie wieder her. Nach dem Einsatz des Ultimates erhält der Träger „Raiton“. Nachdem er 2-mal seinen Standardangriff eingesetzt hat, wird seine Aktion um 50% vorgezogen und Raiton entfernt. Nach dem Einsatz des Ultimates wird Raiton zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 70%. Stellt beim Kampfeintritt sofort 32,5 Pkt. Energie wieder her. Nach dem Einsatz des Ultimates erhält der Träger „Raiton“. Nachdem er 2-mal seinen Standardangriff eingesetzt hat, wird seine Aktion um 55% vorgezogen und Raiton entfernt. Nach dem Einsatz des Ultimates wird Raiton zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 80%. Stellt beim Kampfeintritt sofort 35 Pkt. Energie wieder her. Nach dem Einsatz des Ultimates erhält der Träger „Raiton“. Nachdem er 2-mal seinen Standardangriff eingesetzt hat, wird seine Aktion um 60% vorgezogen und Raiton entfernt. Nach dem Einsatz des Ultimates wird Raiton zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 90%. Stellt beim Kampfeintritt sofort 37,5 Pkt. Energie wieder her. Nach dem Einsatz des Ultimates erhält der Träger „Raiton“. Nachdem er 2-mal seinen Standardangriff eingesetzt hat, wird seine Aktion um 65% vorgezogen und Raiton entfernt. Nach dem Einsatz des Ultimates wird Raiton zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 100%. Stellt beim Kampfeintritt sofort 40 Pkt. Energie wieder her. Nach dem Einsatz des Ultimates erhält der Träger „Raiton“. Nachdem er 2-mal seinen Standardangriff eingesetzt hat, wird seine Aktion um 70% vorgezogen und Raiton entfernt. Nach dem Einsatz des Ultimates wird Raiton zurückgesetzt."]}'),
  ('Nirgends zu fliehen', 'Die Zerstörung', 4, 'assets/images/light_cones/nowhere_to_run.png', '{"name": "Krise", "text": ["Erhöht den ANG des Trägers um 24%. Besiegt der Träger einen Gegner, werden seine LP in Höhe von 12% seines ANG wiederhergestellt.", "Erhöht den ANG des Trägers um 30%. Besiegt der Träger einen Gegner, werden seine LP in Höhe von 15% seines ANG wiederhergestellt.", "Erhöht den ANG des Trägers um 36%. Besiegt der Träger einen Gegner, werden seine LP in Höhe von 18% seines ANG wiederhergestellt.", "Erhöht den ANG des Trägers um 42%. Besiegt der Träger einen Gegner, werden seine LP in Höhe von 21% seines ANG wiederhergestellt.", "Erhöht den ANG des Trägers um 48%. Besiegt der Träger einen Gegner, werden seine LP in Höhe von 24% seines ANG wiederhergestellt."]}'),
  ('Nur Geduld', 'Die Nichtigkeit', 5, 'assets/images/light_cones/patience_is_all_you_need.png', '{"name": "Spinnennetz", "text": ["Erhöht den vom Träger verursachten SCH um 24%. Nach jedem vom Träger eingesetzten Angriff wird seine GES um 4,8% erhöht, bis zu 3-fach stapelbar.\\nWenn der Träger einen Gegner trifft, der nicht von „Sommerfäden“ betroffen ist, besteht eine Grundchance von 100 %, dem Ziel „Sommerfäden“ zuzufügen. Gegner, die bereits von „Sommerfäden“ betroffen sind, gelten ebenfalls als geschockt. Gegner im Status „Sommerfäden“ erleiden zu Beginn jeder Runde Blitz-DoT in Höhe von 60% des ANG vom Träger für 1 Rd.", "Erhöht den vom Träger verursachten SCH um 28%. Nach jedem vom Träger eingesetzten Angriff wird seine GES um 5,6% erhöht, bis zu 3-fach stapelbar.\\nWenn der Träger einen Gegner trifft, der nicht von „Sommerfäden“ betroffen ist, besteht eine Grundchance von 100 %, dem Ziel „Sommerfäden“ zuzufügen. Gegner, die bereits von „Sommerfäden“ betroffen sind, gelten ebenfalls als geschockt. Gegner im Status „Sommerfäden“ erleiden zu Beginn jeder Runde Blitz-DoT in Höhe von 70% des ANG vom Träger für 1 Rd.", "Erhöht den vom Träger verursachten SCH um 32%. Nach jedem vom Träger eingesetzten Angriff wird seine GES um 6,4% erhöht, bis zu 3-fach stapelbar.\\nWenn der Träger einen Gegner trifft, der nicht von „Sommerfäden“ betroffen ist, besteht eine Grundchance von 100 %, dem Ziel „Sommerfäden“ zuzufügen. Gegner, die bereits von „Sommerfäden“ betroffen sind, gelten ebenfalls als geschockt. Gegner im Status „Sommerfäden“ erleiden zu Beginn jeder Runde Blitz-DoT in Höhe von 80% des ANG vom Träger für 1 Rd.", "Erhöht den vom Träger verursachten SCH um 36%. Nach jedem vom Träger eingesetzten Angriff wird seine GES um 7,2% erhöht, bis zu 3-fach stapelbar.\\nWenn der Träger einen Gegner trifft, der nicht von „Sommerfäden“ betroffen ist, besteht eine Grundchance von 100 %, dem Ziel „Sommerfäden“ zuzufügen. Gegner, die bereits von „Sommerfäden“ betroffen sind, gelten ebenfalls als geschockt. Gegner im Status „Sommerfäden“ erleiden zu Beginn jeder Runde Blitz-DoT in Höhe von 90% des ANG vom Träger für 1 Rd.", "Erhöht den vom Träger verursachten SCH um 40%. Nach jedem vom Träger eingesetzten Angriff wird seine GES um 8% erhöht, bis zu 3-fach stapelbar.\\nWenn der Träger einen Gegner trifft, der nicht von „Sommerfäden“ betroffen ist, besteht eine Grundchance von 100 %, dem Ziel „Sommerfäden“ zuzufügen. Gegner, die bereits von „Sommerfäden“ betroffen sind, gelten ebenfalls als geschockt. Gegner im Status „Sommerfäden“ erleiden zu Beginn jeder Runde Blitz-DoT in Höhe von 100% des ANG vom Träger für 1 Rd."]}'),
  ('Nur die Stille bleibt', 'Die Jagd', 4, 'assets/images/light_cones/only_silence_remains.png', '{"name": "Aufzeichnung", "text": ["Erhöht den ANG des Trägers um 16%. Befinden sich 2 oder weniger Gegner auf dem Kampffeld, wird die KRIT-Rate des Trägers um 12% erhöht.", "Erhöht den ANG des Trägers um 20%. Befinden sich 2 oder weniger Gegner auf dem Kampffeld, wird die KRIT-Rate des Trägers um 15% erhöht.", "Erhöht den ANG des Trägers um 24%. Befinden sich 2 oder weniger Gegner auf dem Kampffeld, wird die KRIT-Rate des Trägers um 18% erhöht.", "Erhöht den ANG des Trägers um 28%. Befinden sich 2 oder weniger Gegner auf dem Kampffeld, wird die KRIT-Rate des Trägers um 21% erhöht.", "Erhöht den ANG des Trägers um 32%. Befinden sich 2 oder weniger Gegner auf dem Kampffeld, wird die KRIT-Rate des Trägers um 24% erhöht."]}'),
  ('Nur ein Duft bleibt zurück', 'Der Überfluss', 5, 'assets/images/light_cones/scent_alone_stays_true.png', '{"name": "Erleichterung", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Nachdem der Träger einen Gegner mit seinem Ultimate angegriffen hat, wird das Ziel für 2 Rd. mit „Sorglos“ belegt. Der erlittene SCH von Gegnern mit „Sorglos“ wird um 10% erhöht. Der Effekt dieser SCH-Erhöhung wird zusätzlich um 8% erhöht, wenn der aktuelle Brucheffekt des Trägers 150% oder mehr beträgt.", "Erhöht den Brucheffekt des Trägers um 70%. Nachdem der Träger einen Gegner mit seinem Ultimate angegriffen hat, wird das Ziel für 2 Rd. mit „Sorglos“ belegt. Der erlittene SCH von Gegnern mit „Sorglos“ wird um 12% erhöht. Der Effekt dieser SCH-Erhöhung wird zusätzlich um 10% erhöht, wenn der aktuelle Brucheffekt des Trägers 150% oder mehr beträgt.", "Erhöht den Brucheffekt des Trägers um 80%. Nachdem der Träger einen Gegner mit seinem Ultimate angegriffen hat, wird das Ziel für 2 Rd. mit „Sorglos“ belegt. Der erlittene SCH von Gegnern mit „Sorglos“ wird um 14% erhöht. Der Effekt dieser SCH-Erhöhung wird zusätzlich um 12% erhöht, wenn der aktuelle Brucheffekt des Trägers 150% oder mehr beträgt.", "Erhöht den Brucheffekt des Trägers um 90%. Nachdem der Träger einen Gegner mit seinem Ultimate angegriffen hat, wird das Ziel für 2 Rd. mit „Sorglos“ belegt. Der erlittene SCH von Gegnern mit „Sorglos“ wird um 16% erhöht. Der Effekt dieser SCH-Erhöhung wird zusätzlich um 14% erhöht, wenn der aktuelle Brucheffekt des Trägers 150% oder mehr beträgt.", "Erhöht den Brucheffekt des Trägers um 100%. Nachdem der Träger einen Gegner mit seinem Ultimate angegriffen hat, wird das Ziel für 2 Rd. mit „Sorglos“ belegt. Der erlittene SCH von Gegnern mit „Sorglos“ wird um 18% erhöht. Der Effekt dieser SCH-Erhöhung wird zusätzlich um 16% erhöht, wenn der aktuelle Brucheffekt des Trägers 150% oder mehr beträgt."]}'),
  ('Perfektes Timing', 'Der Überfluss', 4, 'assets/images/light_cones/perfect_timing.png', '{"name": "Brechung der Sichtlinie", "text": ["Erhöht den Effekt-WDS des Trägers um 16% und erhöht die bewirkte Heilung um 33% des Effekt-WDS. Die bewirkte Heilung kann bis zu 15% erhöht werden.", "Erhöht den Effekt-WDS des Trägers um 20% und erhöht die bewirkte Heilung um 36% des Effekt-WDS. Die bewirkte Heilung kann bis zu 18% erhöht werden.", "Erhöht den Effekt-WDS des Trägers um 24% und erhöht die bewirkte Heilung um 39% des Effekt-WDS. Die bewirkte Heilung kann bis zu 21% erhöht werden.", "Erhöht den Effekt-WDS des Trägers um 28% und erhöht die bewirkte Heilung um 42% des Effekt-WDS. Die bewirkte Heilung kann bis zu 24% erhöht werden.", "Erhöht den Effekt-WDS des Trägers um 32% und erhöht die bewirkte Heilung um 45% des Effekt-WDS. Die bewirkte Heilung kann bis zu 27% erhöht werden."]}'),
  ('Pfeile', 'Die Jagd', 3, 'assets/images/light_cones/arrows.png', '{"name": "Krise", "text": ["Erhöht zu Beginn des Kampfes die KRIT-Rate des Trägers für 3 Rd. um 12%.", "Erhöht zu Beginn des Kampfes die KRIT-Rate des Trägers für 3 Rd. um 15%.", "Erhöht zu Beginn des Kampfes die KRIT-Rate des Trägers für 3 Rd. um 18%.", "Erhöht zu Beginn des Kampfes die KRIT-Rate des Trägers für 3 Rd. um 21%.", "Erhöht zu Beginn des Kampfes die KRIT-Rate des Trägers für 3 Rd. um 24%."]}'),
  ('Pionierarbeit', 'Die Bewahrung', 3, 'assets/images/light_cones/pioneering.png', '{"name": "IFK", "text": ["Stellt 12% der max. LP des Trägers wieder her, wenn er Schwächebruch an einem Gegner verursacht.", "Stellt 14% der max. LP des Trägers wieder her, wenn er Schwächebruch an einem Gegner verursacht.", "Stellt 16% der max. LP des Trägers wieder her, wenn er Schwächebruch an einem Gegner verursacht.", "Stellt 18% der max. LP des Trägers wieder her, wenn er Schwächebruch an einem Gegner verursacht.", "Stellt 20% der max. LP des Trägers wieder her, wenn er Schwächebruch an einem Gegner verursacht."]}'),
  ('Planetarisches Rendezvous', 'Die Harmonie', 4, 'assets/images/light_cones/planetary_rendezvous.png', '{"name": "Abreise", "text": ["Wenn ein Verbündeter nach Kampfeintritt denselben SCH-Typ wie der Träger verursacht, wird der zugefügte SCH um 12% erhöht.", "Wenn ein Verbündeter nach Kampfeintritt denselben SCH-Typ wie der Träger verursacht, wird der zugefügte SCH um 15% erhöht.", "Wenn ein Verbündeter nach Kampfeintritt denselben SCH-Typ wie der Träger verursacht, wird der zugefügte SCH um 18% erhöht.", "Wenn ein Verbündeter nach Kampfeintritt denselben SCH-Typ wie der Träger verursacht, wird der zugefügte SCH um 21% erhöht.", "Wenn ein Verbündeter nach Kampfeintritt denselben SCH-Typ wie der Träger verursacht, wird der zugefügte SCH um 24% erhöht."]}'),
  ('Quid pro quo', 'Der Überfluss', 4, 'assets/images/light_cones/quid_pro_quo.png', '{"name": "Im Rausch genießen", "text": ["Stellt zu Beginn der Runde des Trägers für einen zufälligen Verbündeten 8 Pkt. Energie wieder her, dessen aktuelle Energie unter 50% liegt.", "Stellt zu Beginn der Runde des Trägers für einen zufälligen Verbündeten 10 Pkt. Energie wieder her, dessen aktuelle Energie unter 50% liegt.", "Stellt zu Beginn der Runde des Trägers für einen zufälligen Verbündeten 12 Pkt. Energie wieder her, dessen aktuelle Energie unter 50% liegt.", "Stellt zu Beginn der Runde des Trägers für einen zufälligen Verbündeten 14 Pkt. Energie wieder her, dessen aktuelle Energie unter 50% liegt.", "Stellt zu Beginn der Runde des Trägers für einen zufälligen Verbündeten 16 Pkt. Energie wieder her, dessen aktuelle Energie unter 50% liegt."]}'),
  ('Restaurierte Erinnerung', 'Die Nichtigkeit', 5, 'assets/images/light_cones/reforged_remembrance.png', '{"name": "Kristallisiert", "text": ["Erhöht die Effekt-Trefferrate des Trägers um 40%. Wenn der Träger einem mit Windscherung, Brennen, Schock oder Bluten belegten Gegner SCH zufügt, erhalten sie jeweils 1 Stapelung „Prophet“ bis zu max. 4 Stapelungen. In einem Kampf kann jede Art von DoT nur 1 Stapelung Prophet verursachen. Jede Stapelung Prophet erhöht den ANG des Trägers um 5% und der verursachte DoT ignoriert 7,2% der VTD des Ziels.", "Erhöht die Effekt-Trefferrate des Trägers um 45%. Wenn der Träger einem mit Windscherung, Brennen, Schock oder Bluten belegten Gegner SCH zufügt, erhalten sie jeweils 1 Stapelung „Prophet“ bis zu max. 4 Stapelungen. In einem Kampf kann jede Art von DoT nur 1 Stapelung Prophet verursachen. Jede Stapelung Prophet erhöht den ANG des Trägers um 6% und der verursachte DoT ignoriert 7,9% der VTD des Ziels.", "Erhöht die Effekt-Trefferrate des Trägers um 50%. Wenn der Träger einem mit Windscherung, Brennen, Schock oder Bluten belegten Gegner SCH zufügt, erhalten sie jeweils 1 Stapelung „Prophet“ bis zu max. 4 Stapelungen. In einem Kampf kann jede Art von DoT nur 1 Stapelung Prophet verursachen. Jede Stapelung Prophet erhöht den ANG des Trägers um 7% und der verursachte DoT ignoriert 8,6% der VTD des Ziels.", "Erhöht die Effekt-Trefferrate des Trägers um 55%. Wenn der Träger einem mit Windscherung, Brennen, Schock oder Bluten belegten Gegner SCH zufügt, erhalten sie jeweils 1 Stapelung „Prophet“ bis zu max. 4 Stapelungen. In einem Kampf kann jede Art von DoT nur 1 Stapelung Prophet verursachen. Jede Stapelung Prophet erhöht den ANG des Trägers um 8% und der verursachte DoT ignoriert 9,3% der VTD des Ziels.", "Erhöht die Effekt-Trefferrate des Trägers um 60%. Wenn der Träger einem mit Windscherung, Brennen, Schock oder Bluten belegten Gegner SCH zufügt, erhalten sie jeweils 1 Stapelung „Prophet“ bis zu max. 4 Stapelungen. In einem Kampf kann jede Art von DoT nur 1 Stapelung Prophet verursachen. Jede Stapelung Prophet erhöht den ANG des Trägers um 9% und der verursachte DoT ignoriert 10% der VTD des Ziels."]}'),
  ('Rückblick', 'Das Gedenken', 3, 'assets/images/light_cones/reminiscence.png', '{"name": "Einschlafen", "text": ["Zu Beginn der Runde des Memogeists erhalten der Träger und der Memogeist jeweils eine Stapelung „Nachtrauern“. Jede Stapelung erhöht den verursachten SCH um 8%. Dieser Effekt ist bis zu 4-fach stapelbar. Wenn der Memogeist verschwindet, wird Nachtrauern vom Träger und vom Memogeist entfernt.", "Zu Beginn der Runde des Memogeists erhalten der Träger und der Memogeist jeweils eine Stapelung „Nachtrauern“. Jede Stapelung erhöht den verursachten SCH um 9%. Dieser Effekt ist bis zu 4-fach stapelbar. Wenn der Memogeist verschwindet, wird Nachtrauern vom Träger und vom Memogeist entfernt.", "Zu Beginn der Runde des Memogeists erhalten der Träger und der Memogeist jeweils eine Stapelung „Nachtrauern“. Jede Stapelung erhöht den verursachten SCH um 10%. Dieser Effekt ist bis zu 4-fach stapelbar. Wenn der Memogeist verschwindet, wird Nachtrauern vom Träger und vom Memogeist entfernt.", "Zu Beginn der Runde des Memogeists erhalten der Träger und der Memogeist jeweils eine Stapelung „Nachtrauern“. Jede Stapelung erhöht den verursachten SCH um 11%. Dieser Effekt ist bis zu 4-fach stapelbar. Wenn der Memogeist verschwindet, wird Nachtrauern vom Träger und vom Memogeist entfernt.", "Zu Beginn der Runde des Memogeists erhalten der Träger und der Memogeist jeweils eine Stapelung „Nachtrauern“. Jede Stapelung erhöht den verursachten SCH um 12%. Dieser Effekt ist bis zu 4-fach stapelbar. Wenn der Memogeist verschwindet, wird Nachtrauern vom Träger und vom Memogeist entfernt."]}'),
  ('Rückkehr auf langem Wege', 'Die Nichtigkeit', 5, 'assets/images/light_cones/long_road_leads_home.png', '{"name": "Wiedergeburt", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Wenn ein Gegner Schwächebruch erleidet, besteht eine Grundchance von 100%, ihn für 2 Rd. mit „Lichterloh“ zu belegen, was den erlittenen Bruch-SCH um 18% erhöht. Dieser Effekt ist bis zu 2-fach stapelbar.", "Erhöht den Brucheffekt des Trägers um 70%. Wenn ein Gegner Schwächebruch erleidet, besteht eine Grundchance von 100%, ihn für 2 Rd. mit „Lichterloh“ zu belegen, was den erlittenen Bruch-SCH um 21% erhöht. Dieser Effekt ist bis zu 2-fach stapelbar.", "Erhöht den Brucheffekt des Trägers um 80%. Wenn ein Gegner Schwächebruch erleidet, besteht eine Grundchance von 100%, ihn für 2 Rd. mit „Lichterloh“ zu belegen, was den erlittenen Bruch-SCH um 24% erhöht. Dieser Effekt ist bis zu 2-fach stapelbar.", "Erhöht den Brucheffekt des Trägers um 90%. Wenn ein Gegner Schwächebruch erleidet, besteht eine Grundchance von 100%, ihn für 2 Rd. mit „Lichterloh“ zu belegen, was den erlittenen Bruch-SCH um 27% erhöht. Dieser Effekt ist bis zu 2-fach stapelbar.", "Erhöht den Brucheffekt des Trägers um 100%. Wenn ein Gegner Schwächebruch erleidet, besteht eine Grundchance von 100%, ihn für 2 Rd. mit „Lichterloh“ zu belegen, was den erlittenen Bruch-SCH um 30% erhöht. Dieser Effekt ist bis zu 2-fach stapelbar."]}'),
  ('Rückkehr in die Dunkelheit', 'Die Jagd', 4, 'assets/images/light_cones/return_to_darkness.png', '{"name": "Tosende Wellen", "text": ["Erhöht die KRIT-Rate des Trägers um 12%. Nach einem Kritischen Treffer besteht eine feste Chance von 16%, 1 Buff auf dem anvisierten Gegner zu entfernen. Dieser Effekt kann nur 1-mal für jeden Angriff ausgelöst werden.", "Erhöht die KRIT-Rate des Trägers um 15%. Nach einem Kritischen Treffer besteht eine feste Chance von 20%, 1 Buff auf dem anvisierten Gegner zu entfernen. Dieser Effekt kann nur 1-mal für jeden Angriff ausgelöst werden.", "Erhöht die KRIT-Rate des Trägers um 18%. Nach einem Kritischen Treffer besteht eine feste Chance von 24%, 1 Buff auf dem anvisierten Gegner zu entfernen. Dieser Effekt kann nur 1-mal für jeden Angriff ausgelöst werden.", "Erhöht die KRIT-Rate des Trägers um 21%. Nach einem Kritischen Treffer besteht eine feste Chance von 28%, 1 Buff auf dem anvisierten Gegner zu entfernen. Dieser Effekt kann nur 1-mal für jeden Angriff ausgelöst werden.", "Erhöht die KRIT-Rate des Trägers um 24%. Nach einem Kritischen Treffer besteht eine feste Chance von 32%, 1 Buff auf dem anvisierten Gegner zu entfernen. Dieser Effekt kann nur 1-mal für jeden Angriff ausgelöst werden."]}'),
  ('Sache der Wahrheit', 'Der Überfluss', 4, 'assets/images/light_cones/what_is_real.png', '{"name": "Hypothese", "text": ["Erhöht den Brucheffekt des Trägers um 24%. Stellt nach dem Einsatz des Standardangriffs die LP des Trägers um 2% seiner max. LP plus 800 Pkt. wieder her.", "Erhöht den Brucheffekt des Trägers um 30%. Stellt nach dem Einsatz des Standardangriffs die LP des Trägers um 2,5% seiner max. LP plus 800 Pkt. wieder her.", "Erhöht den Brucheffekt des Trägers um 36%. Stellt nach dem Einsatz des Standardangriffs die LP des Trägers um 3% seiner max. LP plus 800 Pkt. wieder her.", "Erhöht den Brucheffekt des Trägers um 42%. Stellt nach dem Einsatz des Standardangriffs die LP des Trägers um 3,5% seiner max. LP plus 800 Pkt. wieder her.", "Erhöht den Brucheffekt des Trägers um 48%. Stellt nach dem Einsatz des Standardangriffs die LP des Trägers um 4% seiner max. LP plus 800 Pkt. wieder her."]}'),
  ('Schicksalsfaden', 'Die Bewahrung', 4, 'assets/images/light_cones/destiny_s_threads_forewoven.png', '{"name": "Einblick", "text": ["Erhöht den Effekt-WDS des Trägers um 12%. Erhöht für jede 100 Pkt. VTD des Trägers den verursachten SCH um 0,8% bis max. 32%.", "Erhöht den Effekt-WDS des Trägers um 14%. Erhöht für jede 100 Pkt. VTD des Trägers den verursachten SCH um 0,9% bis max. 36%.", "Erhöht den Effekt-WDS des Trägers um 16%. Erhöht für jede 100 Pkt. VTD des Trägers den verursachten SCH um 1% bis max. 40%.", "Erhöht den Effekt-WDS des Trägers um 18%. Erhöht für jede 100 Pkt. VTD des Trägers den verursachten SCH um 1,1% bis max. 44%.", "Erhöht den Effekt-WDS des Trägers um 20%. Erhöht für jede 100 Pkt. VTD des Trägers den verursachten SCH um 1,2% bis max. 48%."]}'),
  ('Schillernde Nacht', 'Die Harmonie', 5, 'assets/images/light_cones/flowing_nightglow.png', '{"name": "Trösten", "text": ["Jedes Mal, wenn ein Verbündeter angreift, erhält der Träger eine Stapelung „Gesang“. Jede Stapelung Gesang erhöht die Energie-Wiederherstellungsrate des Trägers um 3%, bis zu 5 Stapelungen. Wenn der Träger den Ultimate einsetzt, wird Gesang entfernt und er erhält „Farbenpracht“. Farbenpracht erhöht für 1 Rd. den ANG des Trägers um 48% und den verursachten SCH aller Verbündeten um 24%.", "Jedes Mal, wenn ein Verbündeter angreift, erhält der Träger eine Stapelung „Gesang“. Jede Stapelung Gesang erhöht die Energie-Wiederherstellungsrate des Trägers um 3,5%, bis zu 5 Stapelungen. Wenn der Träger den Ultimate einsetzt, wird Gesang entfernt und er erhält „Farbenpracht“. Farbenpracht erhöht für 1 Rd. den ANG des Trägers um 60% und den verursachten SCH aller Verbündeten um 28%.", "Jedes Mal, wenn ein Verbündeter angreift, erhält der Träger eine Stapelung „Gesang“. Jede Stapelung Gesang erhöht die Energie-Wiederherstellungsrate des Trägers um 4%, bis zu 5 Stapelungen. Wenn der Träger den Ultimate einsetzt, wird Gesang entfernt und er erhält „Farbenpracht“. Farbenpracht erhöht für 1 Rd. den ANG des Trägers um 72% und den verursachten SCH aller Verbündeten um 32%.", "Jedes Mal, wenn ein Verbündeter angreift, erhält der Träger eine Stapelung „Gesang“. Jede Stapelung Gesang erhöht die Energie-Wiederherstellungsrate des Trägers um 4,5%, bis zu 5 Stapelungen. Wenn der Träger den Ultimate einsetzt, wird Gesang entfernt und er erhält „Farbenpracht“. Farbenpracht erhöht für 1 Rd. den ANG des Trägers um 84% und den verursachten SCH aller Verbündeten um 36%.", "Jedes Mal, wenn ein Verbündeter angreift, erhält der Träger eine Stapelung „Gesang“. Jede Stapelung Gesang erhöht die Energie-Wiederherstellungsrate des Trägers um 5%, bis zu 5 Stapelungen. Wenn der Träger den Ultimate einsetzt, wird Gesang entfernt und er erhält „Farbenpracht“. Farbenpracht erhöht für 1 Rd. den ANG des Trägers um 96% und den verursachten SCH aller Verbündeten um 40%."]}'),
  ('Schlafen wie die Toten', 'Die Jagd', 5, 'assets/images/light_cones/sleep_like_the_dead.png', '{"name": "Süßer Traum", "text": ["Erhöht den KRIT-SCH des Trägers um 30%. Erzielt Standardangriff- oder Fertigkeits-SCH des Trägers keinen Kritischen Treffer, wird die KRIT-Rate für 1 Rd. um 36% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Erhöht den KRIT-SCH des Trägers um 35%. Erzielt Standardangriff- oder Fertigkeits-SCH des Trägers keinen Kritischen Treffer, wird die KRIT-Rate für 1 Rd. um 42% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Erhöht den KRIT-SCH des Trägers um 40%. Erzielt Standardangriff- oder Fertigkeits-SCH des Trägers keinen Kritischen Treffer, wird die KRIT-Rate für 1 Rd. um 48% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Erhöht den KRIT-SCH des Trägers um 45%. Erzielt Standardangriff- oder Fertigkeits-SCH des Trägers keinen Kritischen Treffer, wird die KRIT-Rate für 1 Rd. um 54% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden.", "Erhöht den KRIT-SCH des Trägers um 50%. Erzielt Standardangriff- oder Fertigkeits-SCH des Trägers keinen Kritischen Treffer, wird die KRIT-Rate für 1 Rd. um 60% erhöht. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden."]}'),
  ('Schleife', 'Die Nichtigkeit', 3, 'assets/images/light_cones/loop.png', '{"name": "Verfolgung", "text": ["Erhöht den vom Träger an verlangsamten Gegnern verursachten SCH um 24%.", "Erhöht den vom Träger an verlangsamten Gegnern verursachten SCH um 30%.", "Erhöht den vom Träger an verlangsamten Gegnern verursachten SCH um 36%.", "Erhöht den vom Träger an verlangsamten Gegnern verursachten SCH um 42%.", "Erhöht den vom Träger an verlangsamten Gegnern verursachten SCH um 48%."]}'),
  ('Schwertkampf', 'Die Jagd', 4, 'assets/images/light_cones/swordplay.png', '{"name": "Eigene Antworten", "text": ["Jedes Mal, wenn der Träger dasselbe Ziel trifft, wird der verursachte SCH um 8% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar. Wechselt der Träger das Angriffsziel, wird dieser Buff unmittelbar entfernt.", "Jedes Mal, wenn der Träger dasselbe Ziel trifft, wird der verursachte SCH um 10% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar. Wechselt der Träger das Angriffsziel, wird dieser Buff unmittelbar entfernt.", "Jedes Mal, wenn der Träger dasselbe Ziel trifft, wird der verursachte SCH um 12% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar. Wechselt der Träger das Angriffsziel, wird dieser Buff unmittelbar entfernt.", "Jedes Mal, wenn der Träger dasselbe Ziel trifft, wird der verursachte SCH um 14% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar. Wechselt der Träger das Angriffsziel, wird dieser Buff unmittelbar entfernt.", "Jedes Mal, wenn der Träger dasselbe Ziel trifft, wird der verursachte SCH um 16% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar. Wechselt der Träger das Angriffsziel, wird dieser Buff unmittelbar entfernt."]}'),
  ('Selbst über endlose Lande', 'Die Bewahrung', 5, 'assets/images/light_cones/though_worlds_apart.png', '{"name": "Neuschuppen", "text": ["Erhöht den ANG des Trägers um 64%. Wenn der Träger seinen Ultimate einsetzt, werden die LP aller Verbündeten um 10% des ANG des Trägers wiederhergestellt und die LP der Figur mit den niedrigsten LP zusätzlich um 10% des ANG des Trägers wiederhergestellt. Außerdem erhalten alle Verbündeten für 3 Rd. „Garnison“. Der verursachte SCH von Zielen mit Garnison wird um 24% erhöht. Falls das Ziel ein beschworenes Objekt besitzt, wird sein verursachter SCH zusätzlich um 12% erhöht.", "Erhöht den ANG des Trägers um 80%. Wenn der Träger seinen Ultimate einsetzt, werden die LP aller Verbündeten um 13% des ANG des Trägers wiederhergestellt und die LP der Figur mit den niedrigsten LP zusätzlich um 13% des ANG des Trägers wiederhergestellt. Außerdem erhalten alle Verbündeten für 3 Rd. „Garnison“. Der verursachte SCH von Zielen mit Garnison wird um 30% erhöht. Falls das Ziel ein beschworenes Objekt besitzt, wird sein verursachter SCH zusätzlich um 15% erhöht.", "Erhöht den ANG des Trägers um 96%. Wenn der Träger seinen Ultimate einsetzt, werden die LP aller Verbündeten um 15% des ANG des Trägers wiederhergestellt und die LP der Figur mit den niedrigsten LP zusätzlich um 15% des ANG des Trägers wiederhergestellt. Außerdem erhalten alle Verbündeten für 3 Rd. „Garnison“. Der verursachte SCH von Zielen mit Garnison wird um 36% erhöht. Falls das Ziel ein beschworenes Objekt besitzt, wird sein verursachter SCH zusätzlich um 18% erhöht.", "Erhöht den ANG des Trägers um 112%. Wenn der Träger seinen Ultimate einsetzt, werden die LP aller Verbündeten um 18% des ANG des Trägers wiederhergestellt und die LP der Figur mit den niedrigsten LP zusätzlich um 18% des ANG des Trägers wiederhergestellt. Außerdem erhalten alle Verbündeten für 3 Rd. „Garnison“. Der verursachte SCH von Zielen mit Garnison wird um 42% erhöht. Falls das Ziel ein beschworenes Objekt besitzt, wird sein verursachter SCH zusätzlich um 21% erhöht.", "Erhöht den ANG des Trägers um 128%. Wenn der Träger seinen Ultimate einsetzt, werden die LP aller Verbündeten um 20% des ANG des Trägers wiederhergestellt und die LP der Figur mit den niedrigsten LP zusätzlich um 20% des ANG des Trägers wiederhergestellt. Außerdem erhalten alle Verbündeten für 3 Rd. „Garnison“. Der verursachte SCH von Zielen mit Garnison wird um 48% erhöht. Falls das Ziel ein beschworenes Objekt besitzt, wird sein verursachter SCH zusätzlich um 24% erhöht."]}'),
  ('Sieg im Handumdrehen', 'Das Gedenken', 4, 'assets/images/light_cones/victory_in_a_blink.png', '{"name": "Letzter Schlag", "text": ["Erhöht den KRIT-SCH des Trägers um 12%. Wenn der Memogeist des Trägers eine Fähigkeit auf Verbündete anwendet, wird der verursachte SCH aller Verbündeten für 3 Rd. um 8% erhöht.", "Erhöht den KRIT-SCH des Trägers um 15%. Wenn der Memogeist des Trägers eine Fähigkeit auf Verbündete anwendet, wird der verursachte SCH aller Verbündeten für 3 Rd. um 10% erhöht.", "Erhöht den KRIT-SCH des Trägers um 18%. Wenn der Memogeist des Trägers eine Fähigkeit auf Verbündete anwendet, wird der verursachte SCH aller Verbündeten für 3 Rd. um 12% erhöht.", "Erhöht den KRIT-SCH des Trägers um 21%. Wenn der Memogeist des Trägers eine Fähigkeit auf Verbündete anwendet, wird der verursachte SCH aller Verbündeten für 3 Rd. um 14% erhöht.", "Erhöht den KRIT-SCH des Trägers um 24%. Wenn der Memogeist des Trägers eine Fähigkeit auf Verbündete anwendet, wird der verursachte SCH aller Verbündeten für 3 Rd. um 16% erhöht."]}'),
  ('Steh auf und sing', 'Das Gedenken', 5, 'assets/images/light_cones/rise_and_sing.png', '{"name": "Improvisation", "text": ["Erhöht die max. LP des Trägers um 30%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird 1 Fertigkeitspunkt für Verbündete wiederhergestellt. Zu Beginn des Kampfes wird die Aktion des Trägers um 30% vorgezogen und er erhält für 2 Rd. „Neue Stimme“. Wenn der Träger Neue Stimme besitzt, wird die GES aller Verbündeten um 20% erhöht.", "Erhöht die max. LP des Trägers um 38%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird 1 Fertigkeitspunkt für Verbündete wiederhergestellt. Zu Beginn des Kampfes wird die Aktion des Trägers um 33% vorgezogen und er erhält für 2 Rd. „Neue Stimme“. Wenn der Träger Neue Stimme besitzt, wird die GES aller Verbündeten um 25% erhöht.", "Erhöht die max. LP des Trägers um 45%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird 1 Fertigkeitspunkt für Verbündete wiederhergestellt. Zu Beginn des Kampfes wird die Aktion des Trägers um 35% vorgezogen und er erhält für 2 Rd. „Neue Stimme“. Wenn der Träger Neue Stimme besitzt, wird die GES aller Verbündeten um 30% erhöht.", "Erhöht die max. LP des Trägers um 53%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird 1 Fertigkeitspunkt für Verbündete wiederhergestellt. Zu Beginn des Kampfes wird die Aktion des Trägers um 38% vorgezogen und er erhält für 2 Rd. „Neue Stimme“. Wenn der Träger Neue Stimme besitzt, wird die GES aller Verbündeten um 35% erhöht.", "Erhöht die max. LP des Trägers um 60%. Nachdem der Träger seinen Ultimate eingesetzt hat, wird 1 Fertigkeitspunkt für Verbündete wiederhergestellt. Zu Beginn des Kampfes wird die Aktion des Trägers um 40% vorgezogen und er erhält für 2 Rd. „Neue Stimme“. Wenn der Träger Neue Stimme besitzt, wird die GES aller Verbündeten um 40% erhöht."]}'),
  ('Tag des kosmischen Kollapses', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/the_day_the_cosmos_fell.png', '{"name": "Strategem", "text": ["Erhöht den ANG des Trägers um 16%. Nach einem Angriff auf nicht weniger als 2 Gegner mit der entsprechenden Schwäche wird der KRIT-SCH des Trägers für 2 Rd. um 20% erhöht.", "Erhöht den ANG des Trägers um 18%. Nach einem Angriff auf nicht weniger als 2 Gegner mit der entsprechenden Schwäche wird der KRIT-SCH des Trägers für 2 Rd. um 25% erhöht.", "Erhöht den ANG des Trägers um 20%. Nach einem Angriff auf nicht weniger als 2 Gegner mit der entsprechenden Schwäche wird der KRIT-SCH des Trägers für 2 Rd. um 30% erhöht.", "Erhöht den ANG des Trägers um 22%. Nach einem Angriff auf nicht weniger als 2 Gegner mit der entsprechenden Schwäche wird der KRIT-SCH des Trägers für 2 Rd. um 35% erhöht.", "Erhöht den ANG des Trägers um 24%. Nach einem Angriff auf nicht weniger als 2 Gegner mit der entsprechenden Schwäche wird der KRIT-SCH des Trägers für 2 Rd. um 40% erhöht."]}'),
  ('Tanz im Sonnenuntergang', 'Die Zerstörung', 5, 'assets/images/light_cones/dance_at_sunset.png', '{"name": "Tief versunken", "text": ["Erhöht stark die Chance des Trägers, angegriffen zu werden und erhöht den KRIT-SCH des Trägers um 36%. Nachdem der Träger seinen Ultimate eingesetzt hat, erhält er für 2 Rd. 1 Stapelung „Feuertanz“, bis zu 2 Stapelungen. Jede Stapelung Feuertanz erhöht den vom Folgeangriff des Trägers verursachten SCH um 36%.", "Erhöht stark die Chance des Trägers, angegriffen zu werden und erhöht den KRIT-SCH des Trägers um 42%. Nachdem der Träger seinen Ultimate eingesetzt hat, erhält er für 2 Rd. 1 Stapelung „Feuertanz“, bis zu 2 Stapelungen. Jede Stapelung Feuertanz erhöht den vom Folgeangriff des Trägers verursachten SCH um 42%.", "Erhöht stark die Chance des Trägers, angegriffen zu werden und erhöht den KRIT-SCH des Trägers um 48%. Nachdem der Träger seinen Ultimate eingesetzt hat, erhält er für 2 Rd. 1 Stapelung „Feuertanz“, bis zu 2 Stapelungen. Jede Stapelung Feuertanz erhöht den vom Folgeangriff des Trägers verursachten SCH um 48%.", "Erhöht stark die Chance des Trägers, angegriffen zu werden und erhöht den KRIT-SCH des Trägers um 54%. Nachdem der Träger seinen Ultimate eingesetzt hat, erhält er für 2 Rd. 1 Stapelung „Feuertanz“, bis zu 2 Stapelungen. Jede Stapelung Feuertanz erhöht den vom Folgeangriff des Trägers verursachten SCH um 54%.", "Erhöht stark die Chance des Trägers, angegriffen zu werden und erhöht den KRIT-SCH des Trägers um 60%. Nachdem der Träger seinen Ultimate eingesetzt hat, erhält er für 2 Rd. 1 Stapelung „Feuertanz“, bis zu 2 Stapelungen. Jede Stapelung Feuertanz erhöht den vom Folgeangriff des Trägers verursachten SCH um 60%."]}'),
  ('Tanz! Tanz! Tanz!', 'Die Harmonie', 4, 'assets/images/light_cones/dance_dance_dance.png', '{"name": "Unaufhaltsam!", "text": ["Nach dem Einsatz des Ultimates des Trägers werden die Aktionen aller Verbündeten um 16% vorgezogen.", "Nach dem Einsatz des Ultimates des Trägers werden die Aktionen aller Verbündeten um 18% vorgezogen.", "Nach dem Einsatz des Ultimates des Trägers werden die Aktionen aller Verbündeten um 20% vorgezogen.", "Nach dem Einsatz des Ultimates des Trägers werden die Aktionen aller Verbündeten um 22% vorgezogen.", "Nach dem Einsatz des Ultimates des Trägers werden die Aktionen aller Verbündeten um 24% vorgezogen."]}'),
  ('Taufe des reinen Denkens', 'Die Jagd', 5, 'assets/images/light_cones/baptism_of_pure_thought.png', '{"name": "Denktraining", "text": ["Erhöht den KRIT-SCH des Trägers um 20%. Für jeden Debuff auf dem gegnerischen Ziel erhöht sich der KRIT-SCH des Trägers um 8%, bis zu einem Maximum von 3 Stapelungen. Wenn der Träger das Ziel mit seinem Ultimate angreift, erhält er den Effekt Debatte, der den zugefügten SCH um 36% erhöht, und seine Folgeangriffe ignorieren 24% der VTD des Ziels. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 23%. Für jeden Debuff auf dem gegnerischen Ziel erhöht sich der KRIT-SCH des Trägers um 9%, bis zu einem Maximum von 3 Stapelungen. Wenn der Träger das Ziel mit seinem Ultimate angreift, erhält er den Effekt Debatte, der den zugefügten SCH um 42% erhöht, und seine Folgeangriffe ignorieren 28% der VTD des Ziels. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 26%. Für jeden Debuff auf dem gegnerischen Ziel erhöht sich der KRIT-SCH des Trägers um 10%, bis zu einem Maximum von 3 Stapelungen. Wenn der Träger das Ziel mit seinem Ultimate angreift, erhält er den Effekt Debatte, der den zugefügten SCH um 48% erhöht, und seine Folgeangriffe ignorieren 32% der VTD des Ziels. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 29%. Für jeden Debuff auf dem gegnerischen Ziel erhöht sich der KRIT-SCH des Trägers um 11%, bis zu einem Maximum von 3 Stapelungen. Wenn der Träger das Ziel mit seinem Ultimate angreift, erhält er den Effekt Debatte, der den zugefügten SCH um 54% erhöht, und seine Folgeangriffe ignorieren 36% der VTD des Ziels. Dieser Effekt hält für 2 Rd. an.", "Erhöht den KRIT-SCH des Trägers um 32%. Für jeden Debuff auf dem gegnerischen Ziel erhöht sich der KRIT-SCH des Trägers um 12%, bis zu einem Maximum von 3 Stapelungen. Wenn der Träger das Ziel mit seinem Ultimate angreift, erhält er den Effekt Debatte, der den zugefügten SCH um 60% erhöht, und seine Folgeangriffe ignorieren 40% der VTD des Ziels. Dieser Effekt hält für 2 Rd. an."]}'),
  ('Textur der Erinnerungen', 'Die Bewahrung', 5, 'assets/images/light_cones/texture_of_memories.png', '{"name": "Schätzen", "text": ["Erhöht den Effekt-WDS des Trägers um 8%. Wenn der Träger angegriffen wird und keinen Schild hat, erhält er für 2 Rd. einen Schild in Höhe von 16% seiner max. LP. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden. Hat der Träger einen Schild, wird der von ihm erlittene SCH um 12% reduziert.", "Erhöht den Effekt-WDS des Trägers um 10%. Wenn der Träger angegriffen wird und keinen Schild hat, erhält er für 2 Rd. einen Schild in Höhe von 20% seiner max. LP. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden. Hat der Träger einen Schild, wird der von ihm erlittene SCH um 15% reduziert.", "Erhöht den Effekt-WDS des Trägers um 12%. Wenn der Träger angegriffen wird und keinen Schild hat, erhält er für 2 Rd. einen Schild in Höhe von 24% seiner max. LP. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden. Hat der Träger einen Schild, wird der von ihm erlittene SCH um 18% reduziert.", "Erhöht den Effekt-WDS des Trägers um 14%. Wenn der Träger angegriffen wird und keinen Schild hat, erhält er für 2 Rd. einen Schild in Höhe von 28% seiner max. LP. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden. Hat der Träger einen Schild, wird der von ihm erlittene SCH um 21% reduziert.", "Erhöht den Effekt-WDS des Trägers um 16%. Wenn der Träger angegriffen wird und keinen Schild hat, erhält er für 2 Rd. einen Schild in Höhe von 32% seiner max. LP. Dieser Effekt kann nur 1-mal alle 3 Rd. ausgelöst werden. Hat der Träger einen Schild, wird der von ihm erlittene SCH um 24% reduziert."]}'),
  ('Traummontage', 'Der Überfluss', 4, 'assets/images/light_cones/dream_s_montage.png', '{"name": "Akademischer Schnitt", "text": ["Erhöht die GES des Trägers um 8%. Stellt nach Angriffen auf Gegner mit Schwächebruch 3 Pkt. Energie wieder her. Dieser Effekt kann bis zu 2-mal pro Runde ausgelöst werden.", "Erhöht die GES des Trägers um 9%. Stellt nach Angriffen auf Gegner mit Schwächebruch 3,5 Pkt. Energie wieder her. Dieser Effekt kann bis zu 2-mal pro Runde ausgelöst werden.", "Erhöht die GES des Trägers um 10%. Stellt nach Angriffen auf Gegner mit Schwächebruch 4 Pkt. Energie wieder her. Dieser Effekt kann bis zu 2-mal pro Runde ausgelöst werden.", "Erhöht die GES des Trägers um 11%. Stellt nach Angriffen auf Gegner mit Schwächebruch 4,5 Pkt. Energie wieder her. Dieser Effekt kann bis zu 2-mal pro Runde ausgelöst werden.", "Erhöht die GES des Trägers um 12%. Stellt nach Angriffen auf Gegner mit Schwächebruch 5 Pkt. Energie wieder her. Dieser Effekt kann bis zu 2-mal pro Runde ausgelöst werden."]}'),
  ('Trend des universellen Markts', 'Die Bewahrung', 4, 'assets/images/light_cones/trend_of_the_universal_market.png', '{"name": "Für eine neue Runde mischen", "text": ["Erhöht die VTD des Trägers um 16%. Wenn der Träger angegriffen wird, besteht eine Grundchance von 100%, beim Gegner Brennen zu verursachen und für jede Runde DoT in Höhe von 40% der VTD des Trägers zuzufügen. Dieser Effekt hält 2 Rd. an.", "Erhöht die VTD des Trägers um 20%. Wenn der Träger angegriffen wird, besteht eine Grundchance von 105%, beim Gegner Brennen zu verursachen und für jede Runde DoT in Höhe von 50% der VTD des Trägers zuzufügen. Dieser Effekt hält 2 Rd. an.", "Erhöht die VTD des Trägers um 24%. Wenn der Träger angegriffen wird, besteht eine Grundchance von 110%, beim Gegner Brennen zu verursachen und für jede Runde DoT in Höhe von 60% der VTD des Trägers zuzufügen. Dieser Effekt hält 2 Rd. an.", "Erhöht die VTD des Trägers um 28%. Wenn der Träger angegriffen wird, besteht eine Grundchance von 115%, beim Gegner Brennen zu verursachen und für jede Runde DoT in Höhe von 70% der VTD des Trägers zuzufügen. Dieser Effekt hält 2 Rd. an.", "Erhöht die VTD des Trägers um 32%. Wenn der Träger angegriffen wird, besteht eine Grundchance von 120%, beim Gegner Brennen zu verursachen und für jede Runde DoT in Höhe von 80% der VTD des Trägers zuzufügen. Dieser Effekt hält 2 Rd. an."]}'),
  ('Träume von duftendem Weizen', 'Die Gelehrsamkeit', 4, 'assets/images/light_cones/a_dream_scented_in_wheat.png', '{"name": "Sehnsucht", "text": ["Erhöht die KRIT-Rate des Trägers um 12%. Erhöht den verursachten Ultimate- und Folgeangriff-SCH des Trägers um 24%.", "Erhöht die KRIT-Rate des Trägers um 14%. Erhöht den verursachten Ultimate- und Folgeangriff-SCH des Trägers um 28%.", "Erhöht die KRIT-Rate des Trägers um 16%. Erhöht den verursachten Ultimate- und Folgeangriff-SCH des Trägers um 32%.", "Erhöht die KRIT-Rate des Trägers um 18%. Erhöht den verursachten Ultimate- und Folgeangriff-SCH des Trägers um 36%.", "Erhöht die KRIT-Rate des Trägers um 20%. Erhöht den verursachten Ultimate- und Folgeangriff-SCH des Trägers um 40%."]}'),
  ('Unaufhörlicher Regen', 'Die Nichtigkeit', 5, 'assets/images/light_cones/incessant_rain.png', '{"name": "Trugbild der Realität", "text": ["Erhöht die Effekt-Trefferrate des Trägers um 24%. Wenn der Träger einem Gegner mit 3 oder mehr Debuffs SCH zufügt, wird die KRIT-Rate des Trägers um 12% erhöht. Nachdem der Träger seinen Standardangriff, seine Fertigkeit oder seinen Ultimate eingesetzt hat, besteht eine Grundchance von 100%, einem zufälligen Gegner „Äther-Code“ zuzufügen, der keinen „Äther-Code“ besitzt. Gegner mit „Äther-Code“ erleiden für 1 Rd. 12% mehr SCH.", "Erhöht die Effekt-Trefferrate des Trägers um 28%. Wenn der Träger einem Gegner mit 3 oder mehr Debuffs SCH zufügt, wird die KRIT-Rate des Trägers um 14% erhöht. Nachdem der Träger seinen Standardangriff, seine Fertigkeit oder seinen Ultimate eingesetzt hat, besteht eine Grundchance von 100%, einem zufälligen Gegner „Äther-Code“ zuzufügen, der keinen „Äther-Code“ besitzt. Gegner mit „Äther-Code“ erleiden für 1 Rd. 14% mehr SCH.", "Erhöht die Effekt-Trefferrate des Trägers um 32%. Wenn der Träger einem Gegner mit 3 oder mehr Debuffs SCH zufügt, wird die KRIT-Rate des Trägers um 16% erhöht. Nachdem der Träger seinen Standardangriff, seine Fertigkeit oder seinen Ultimate eingesetzt hat, besteht eine Grundchance von 100%, einem zufälligen Gegner „Äther-Code“ zuzufügen, der keinen „Äther-Code“ besitzt. Gegner mit „Äther-Code“ erleiden für 1 Rd. 16% mehr SCH.", "Erhöht die Effekt-Trefferrate des Trägers um 36%. Wenn der Träger einem Gegner mit 3 oder mehr Debuffs SCH zufügt, wird die KRIT-Rate des Trägers um 18% erhöht. Nachdem der Träger seinen Standardangriff, seine Fertigkeit oder seinen Ultimate eingesetzt hat, besteht eine Grundchance von 100%, einem zufälligen Gegner „Äther-Code“ zuzufügen, der keinen „Äther-Code“ besitzt. Gegner mit „Äther-Code“ erleiden für 1 Rd. 18% mehr SCH.", "Erhöht die Effekt-Trefferrate des Trägers um 40%. Wenn der Träger einem Gegner mit 3 oder mehr Debuffs SCH zufügt, wird die KRIT-Rate des Trägers um 20% erhöht. Nachdem der Träger seinen Standardangriff, seine Fertigkeit oder seinen Ultimate eingesetzt hat, besteht eine Grundchance von 100%, einem zufälligen Gegner „Äther-Code“ zuzufügen, der keinen „Äther-Code“ besitzt. Gegner mit „Äther-Code“ erleiden für 1 Rd. 20% mehr SCH."]}'),
  ('Unermüdliche Berechnung', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/eternal_calculus.png', '{"name": "Gedanken ohne Grenzen", "text": ["Erhöht den ANG des Trägers um 8%. Nach einem Angriff wird der ANG für jedes getroffene Ziel zusätzlich um 4% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar und dauert bis zum nächsten Angriff. Wenn 3 oder mehr Gegner getroffen werden, wird die GES dieser Einheit für 1 Rd. um 8% erhöht.", "Erhöht den ANG des Trägers um 9%. Nach einem Angriff wird der ANG für jedes getroffene Ziel zusätzlich um 5% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar und dauert bis zum nächsten Angriff. Wenn 3 oder mehr Gegner getroffen werden, wird die GES dieser Einheit für 1 Rd. um 10% erhöht.", "Erhöht den ANG des Trägers um 10%. Nach einem Angriff wird der ANG für jedes getroffene Ziel zusätzlich um 6% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar und dauert bis zum nächsten Angriff. Wenn 3 oder mehr Gegner getroffen werden, wird die GES dieser Einheit für 1 Rd. um 12% erhöht.", "Erhöht den ANG des Trägers um 11%. Nach einem Angriff wird der ANG für jedes getroffene Ziel zusätzlich um 7% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar und dauert bis zum nächsten Angriff. Wenn 3 oder mehr Gegner getroffen werden, wird die GES dieser Einheit für 1 Rd. um 14% erhöht.", "Erhöht den ANG des Trägers um 12%. Nach einem Angriff wird der ANG für jedes getroffene Ziel zusätzlich um 8% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar und dauert bis zum nächsten Angriff. Wenn 3 oder mehr Gegner getroffen werden, wird die GES dieser Einheit für 1 Rd. um 16% erhöht."]}'),
  ('Unerreichbares Jenseits', 'Die Zerstörung', 5, 'assets/images/light_cones/the_unreachable_side.png', '{"name": "Unerfüllte Sehnsucht", "text": ["Erhöht die KRIT-Rate des Trägers um 18% und seine max. LP um 18%. Wenn der Träger angegriffen wird oder die eigenen LP verbraucht, wird der verursachte SCH um 24% erhöht. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht die KRIT-Rate des Trägers um 21% und seine max. LP um 21%. Wenn der Träger angegriffen wird oder die eigenen LP verbraucht, wird der verursachte SCH um 28% erhöht. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht die KRIT-Rate des Trägers um 24% und seine max. LP um 24%. Wenn der Träger angegriffen wird oder die eigenen LP verbraucht, wird der verursachte SCH um 32% erhöht. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht die KRIT-Rate des Trägers um 27% und seine max. LP um 27%. Wenn der Träger angegriffen wird oder die eigenen LP verbraucht, wird der verursachte SCH um 36% erhöht. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat.", "Erhöht die KRIT-Rate des Trägers um 30% und seine max. LP um 30%. Wenn der Träger angegriffen wird oder die eigenen LP verbraucht, wird der verursachte SCH um 40% erhöht. Dieser Effekt wird entfernt, nachdem der Träger einen Angriff ausgeführt hat."]}'),
  ('Ungerechtes Schicksal', 'Die Bewahrung', 5, 'assets/images/light_cones/inherently_unjust_destiny.png', '{"name": "Alles auf den Tisch", "text": ["Erhöht die VTD des Trägers um 40%. Wenn der Träger Verbündeten einen Schild erzeugt, wird der KRIT-SCH des Trägers für 2 Rd. um 40% erhöht. Wenn der Träger einen Gegner durch Folgeangriff trifft, besteht eine Grundchance von 100%, dass der vom angegriffenen Gegner erlittene SCH für 2 Rd. um 10% erhöht wird.", "Erhöht die VTD des Trägers um 46%. Wenn der Träger Verbündeten einen Schild erzeugt, wird der KRIT-SCH des Trägers für 2 Rd. um 46% erhöht. Wenn der Träger einen Gegner durch Folgeangriff trifft, besteht eine Grundchance von 115%, dass der vom angegriffenen Gegner erlittene SCH für 2 Rd. um 11,5% erhöht wird.", "Erhöht die VTD des Trägers um 52%. Wenn der Träger Verbündeten einen Schild erzeugt, wird der KRIT-SCH des Trägers für 2 Rd. um 52% erhöht. Wenn der Träger einen Gegner durch Folgeangriff trifft, besteht eine Grundchance von 130%, dass der vom angegriffenen Gegner erlittene SCH für 2 Rd. um 13% erhöht wird.", "Erhöht die VTD des Trägers um 58%. Wenn der Träger Verbündeten einen Schild erzeugt, wird der KRIT-SCH des Trägers für 2 Rd. um 58% erhöht. Wenn der Träger einen Gegner durch Folgeangriff trifft, besteht eine Grundchance von 145%, dass der vom angegriffenen Gegner erlittene SCH für 2 Rd. um 14,5% erhöht wird.", "Erhöht die VTD des Trägers um 64%. Wenn der Träger Verbündeten einen Schild erzeugt, wird der KRIT-SCH des Trägers für 2 Rd. um 64% erhöht. Wenn der Träger einen Gegner durch Folgeangriff trifft, besteht eine Grundchance von 160%, dass der vom angegriffenen Gegner erlittene SCH für 2 Rd. um 16% erhöht wird."]}'),
  ('Unter dem blauen Himmel', 'Die Zerstörung', 4, 'assets/images/light_cones/under_the_blue_sky.png', '{"name": "Wogender Weizen unter der Sonne", "text": ["Erhöht den ANG des Trägers um 16%. Besiegt der Träger einen Gegner, wird seine KRIT-Rate für 3 Rd. um 12% erhöht.", "Erhöht den ANG des Trägers um 20%. Besiegt der Träger einen Gegner, wird seine KRIT-Rate für 3 Rd. um 15% erhöht.", "Erhöht den ANG des Trägers um 24%. Besiegt der Träger einen Gegner, wird seine KRIT-Rate für 3 Rd. um 18% erhöht.", "Erhöht den ANG des Trägers um 28%. Besiegt der Träger einen Gegner, wird seine KRIT-Rate für 3 Rd. um 21% erhöht.", "Erhöht den ANG des Trägers um 32%. Besiegt der Träger einen Gegner, wird seine KRIT-Rate für 3 Rd. um 24% erhöht."]}'),
  ('Verborgener Schatten', 'Die Nichtigkeit', 3, 'assets/images/light_cones/hidden_shadow.png', '{"name": "Mechanismus", "text": ["Nach dem Einsatz der Fertigkeit fügt der nächste Standardangriff des Trägers dem Gegner zusätzlichen SCH in Höhe von 60% seines ANG zu.", "Nach dem Einsatz der Fertigkeit fügt der nächste Standardangriff des Trägers dem Gegner zusätzlichen SCH in Höhe von 75% seines ANG zu.", "Nach dem Einsatz der Fertigkeit fügt der nächste Standardangriff des Trägers dem Gegner zusätzlichen SCH in Höhe von 90% seines ANG zu.", "Nach dem Einsatz der Fertigkeit fügt der nächste Standardangriff des Trägers dem Gegner zusätzlichen SCH in Höhe von 105% seines ANG zu.", "Nach dem Einsatz der Fertigkeit fügt der nächste Standardangriff des Trägers dem Gegner zusätzlichen SCH in Höhe von 120% seines ANG zu."]}'),
  ('Verewigtes Versprechen', 'Die Zerstörung', 4, 'assets/images/light_cones/indelible_promise.png', '{"name": "Erbe", "text": ["Erhöht den Brucheffekt des Trägers um 28%. Wenn der Träger seinen Ultimate einsetzt, wird die KRIT-Rate für 2 Rd. um 15% erhöht.", "Erhöht den Brucheffekt des Trägers um 35%. Wenn der Träger seinen Ultimate einsetzt, wird die KRIT-Rate für 2 Rd. um 19% erhöht.", "Erhöht den Brucheffekt des Trägers um 42%. Wenn der Träger seinen Ultimate einsetzt, wird die KRIT-Rate für 2 Rd. um 23% erhöht.", "Erhöht den Brucheffekt des Trägers um 49%. Wenn der Träger seinen Ultimate einsetzt, wird die KRIT-Rate für 2 Rd. um 26% erhöht.", "Erhöht den Brucheffekt des Trägers um 56%. Wenn der Träger seinen Ultimate einsetzt, wird die KRIT-Rate für 2 Rd. um 30% erhöht."]}'),
  ('Vergangenheit und Zukunft', 'Die Harmonie', 4, 'assets/images/light_cones/past_and_future.png', '{"name": "Drachen aus der Vergangenheit", "text": ["Erhöht den verursachten SCH des nächsten aktiven Verbündeten (außer dem Träger) für 1 Rd. um 16%, nachdem der Träger seine Fertigkeit eingesetzt hat.", "Erhöht den verursachten SCH des nächsten aktiven Verbündeten (außer dem Träger) für 1 Rd. um 20%, nachdem der Träger seine Fertigkeit eingesetzt hat.", "Erhöht den verursachten SCH des nächsten aktiven Verbündeten (außer dem Träger) für 1 Rd. um 24%, nachdem der Träger seine Fertigkeit eingesetzt hat.", "Erhöht den verursachten SCH des nächsten aktiven Verbündeten (außer dem Träger) für 1 Rd. um 28%, nachdem der Träger seine Fertigkeit eingesetzt hat.", "Erhöht den verursachten SCH des nächsten aktiven Verbündeten (außer dem Träger) für 1 Rd. um 32%, nachdem der Träger seine Fertigkeit eingesetzt hat."]}'),
  ('Vergiss ihre Flamme niemals', 'Die Nichtigkeit', 5, 'assets/images/light_cones/never_forget_her_flame.png', '{"name": "Selbstverbrennung", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Beim Kampfeintritt wird der verursachte Bruch-SCH des Trägers sowie eines weiteren Teammitglieds, das den Kampf begonnen hat, um 32% erhöht. Wenn kein anderes Teammitglied den Kampf begonnen hat, gilt dieser Effekt für den Träger und das Teammitglied mit dem höchsten Brucheffekt. Effekte desselben Typs sind nicht stapelbar. Wenn der Träger einem Gegner eine Schwäche implantiert, wird 1 Fertigkeitspunkt wiederhergestellt. Dieser Effekt kann bis zu 1-mal ausgelöst werden und die Auslösungsanzahl wird beim Einsatz des Ultimates zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 75%. Beim Kampfeintritt wird der verursachte Bruch-SCH des Trägers sowie eines weiteren Teammitglieds, das den Kampf begonnen hat, um 42% erhöht. Wenn kein anderes Teammitglied den Kampf begonnen hat, gilt dieser Effekt für den Träger und das Teammitglied mit dem höchsten Brucheffekt. Effekte desselben Typs sind nicht stapelbar. Wenn der Träger einem Gegner eine Schwäche implantiert, wird 1 Fertigkeitspunkt wiederhergestellt. Dieser Effekt kann bis zu 1-mal ausgelöst werden und die Auslösungsanzahl wird beim Einsatz des Ultimates zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 90%. Beim Kampfeintritt wird der verursachte Bruch-SCH des Trägers sowie eines weiteren Teammitglieds, das den Kampf begonnen hat, um 52% erhöht. Wenn kein anderes Teammitglied den Kampf begonnen hat, gilt dieser Effekt für den Träger und das Teammitglied mit dem höchsten Brucheffekt. Effekte desselben Typs sind nicht stapelbar. Wenn der Träger einem Gegner eine Schwäche implantiert, wird 1 Fertigkeitspunkt wiederhergestellt. Dieser Effekt kann bis zu 1-mal ausgelöst werden und die Auslösungsanzahl wird beim Einsatz des Ultimates zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 105%. Beim Kampfeintritt wird der verursachte Bruch-SCH des Trägers sowie eines weiteren Teammitglieds, das den Kampf begonnen hat, um 62% erhöht. Wenn kein anderes Teammitglied den Kampf begonnen hat, gilt dieser Effekt für den Träger und das Teammitglied mit dem höchsten Brucheffekt. Effekte desselben Typs sind nicht stapelbar. Wenn der Träger einem Gegner eine Schwäche implantiert, wird 1 Fertigkeitspunkt wiederhergestellt. Dieser Effekt kann bis zu 1-mal ausgelöst werden und die Auslösungsanzahl wird beim Einsatz des Ultimates zurückgesetzt.", "Erhöht den Brucheffekt des Trägers um 120%. Beim Kampfeintritt wird der verursachte Bruch-SCH des Trägers sowie eines weiteren Teammitglieds, das den Kampf begonnen hat, um 72% erhöht. Wenn kein anderes Teammitglied den Kampf begonnen hat, gilt dieser Effekt für den Träger und das Teammitglied mit dem höchsten Brucheffekt. Effekte desselben Typs sind nicht stapelbar. Wenn der Träger einem Gegner eine Schwäche implantiert, wird 1 Fertigkeitspunkt wiederhergestellt. Dieser Effekt kann bis zu 1-mal ausgelöst werden und die Auslösungsanzahl wird beim Einsatz des Ultimates zurückgesetzt."]}'),
  ('Vermittlung', 'Die Harmonie', 3, 'assets/images/light_cones/mediation.png', '{"name": "Familie", "text": ["Erhöht beim Kampfeintritt die GES aller Verbündeten für 1 Rd. um 12 Pkt.", "Erhöht beim Kampfeintritt die GES aller Verbündeten für 1 Rd. um 14 Pkt.", "Erhöht beim Kampfeintritt die GES aller Verbündeten für 1 Rd. um 16 Pkt.", "Erhöht beim Kampfeintritt die GES aller Verbündeten für 1 Rd. um 18 Pkt.", "Erhöht beim Kampfeintritt die GES aller Verbündeten für 1 Rd. um 20 Pkt."]}'),
  ('Verteidigung', 'Die Bewahrung', 3, 'assets/images/light_cones/defense.png', '{"name": "Wiederbelebung", "text": ["Stellt beim Einsatz des Ultimates 18% der max. LP des Trägers wieder her.", "Stellt beim Einsatz des Ultimates 21% der max. LP des Trägers wieder her.", "Stellt beim Einsatz des Ultimates 24% der max. LP des Trägers wieder her.", "Stellt beim Einsatz des Ultimates 27% der max. LP des Trägers wieder her.", "Stellt beim Einsatz des Ultimates 30% der max. LP des Trägers wieder her."]}'),
  ('Verweilende Träne', 'Das Hochgefühl', 3, 'assets/images/light_cones/lingering_tear.png', '{"name": "Trauer", "text": ["Wenn die Anzahl der vorhandenen Lachpunkte 10 oder mehr beträgt, wird der KRIT-SCH des Trägers um 20% erhöht.", "Wenn die Anzahl der vorhandenen Lachpunkte 10 oder mehr beträgt, wird der KRIT-SCH des Trägers um 25% erhöht.", "Wenn die Anzahl der vorhandenen Lachpunkte 10 oder mehr beträgt, wird der KRIT-SCH des Trägers um 30% erhöht.", "Wenn die Anzahl der vorhandenen Lachpunkte 10 oder mehr beträgt, wird der KRIT-SCH des Trägers um 35% erhöht.", "Wenn die Anzahl der vorhandenen Lachpunkte 10 oder mehr beträgt, wird der KRIT-SCH des Trägers um 40% erhöht."]}'),
  ('Vom Winde verwehte Lügen', 'Die Nichtigkeit', 5, 'assets/images/light_cones/lies_dance_on_the_breeze.png', '{"name": "Betrug", "text": ["Erhöht die GES des Trägers um 18%. Nach einem Angriff des Trägers besteht eine Grundchance von 120%, bei jedem Ziel „Verwirrung“ zu verursachen. Die VTD der Gegner im Status Verwirrung wird für 2 Rd. um 16% reduziert. Wenn die GES des Trägers 170 oder höher beträgt, besteht eine Grundchance von 120%, bei jedem Ziel „Gestohlen“ zu verursachen. Die VTD der Gegner im Status Gestohlen wird für 2 Rd. um 8% reduziert. Wenn Verwirrung oder Gestohlen wiederholt verursacht wird, wird nur der letzte Effekt wirksam.", "Erhöht die GES des Trägers um 21%. Nach einem Angriff des Trägers besteht eine Grundchance von 120%, bei jedem Ziel „Verwirrung“ zu verursachen. Die VTD der Gegner im Status Verwirrung wird für 2 Rd. um 18% reduziert. Wenn die GES des Trägers 170 oder höher beträgt, besteht eine Grundchance von 120%, bei jedem Ziel „Gestohlen“ zu verursachen. Die VTD der Gegner im Status Gestohlen wird für 2 Rd. um 9% reduziert. Wenn Verwirrung oder Gestohlen wiederholt verursacht wird, wird nur der letzte Effekt wirksam.", "Erhöht die GES des Trägers um 24%. Nach einem Angriff des Trägers besteht eine Grundchance von 120%, bei jedem Ziel „Verwirrung“ zu verursachen. Die VTD der Gegner im Status Verwirrung wird für 2 Rd. um 20% reduziert. Wenn die GES des Trägers 170 oder höher beträgt, besteht eine Grundchance von 120%, bei jedem Ziel „Gestohlen“ zu verursachen. Die VTD der Gegner im Status Gestohlen wird für 2 Rd. um 10% reduziert. Wenn Verwirrung oder Gestohlen wiederholt verursacht wird, wird nur der letzte Effekt wirksam.", "Erhöht die GES des Trägers um 27%. Nach einem Angriff des Trägers besteht eine Grundchance von 120%, bei jedem Ziel „Verwirrung“ zu verursachen. Die VTD der Gegner im Status Verwirrung wird für 2 Rd. um 22% reduziert. Wenn die GES des Trägers 170 oder höher beträgt, besteht eine Grundchance von 120%, bei jedem Ziel „Gestohlen“ zu verursachen. Die VTD der Gegner im Status Gestohlen wird für 2 Rd. um 11% reduziert. Wenn Verwirrung oder Gestohlen wiederholt verursacht wird, wird nur der letzte Effekt wirksam.", "Erhöht die GES des Trägers um 30%. Nach einem Angriff des Trägers besteht eine Grundchance von 120%, bei jedem Ziel „Verwirrung“ zu verursachen. Die VTD der Gegner im Status Verwirrung wird für 2 Rd. um 24% reduziert. Wenn die GES des Trägers 170 oder höher beträgt, besteht eine Grundchance von 120%, bei jedem Ziel „Gestohlen“ zu verursachen. Die VTD der Gegner im Status Gestohlen wird für 2 Rd. um 12% reduziert. Wenn Verwirrung oder Gestohlen wiederholt verursacht wird, wird nur der letzte Effekt wirksam."]}'),
  ('Vor der Dämmerung', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/before_dawn.png', '{"name": "Lange Nacht", "text": ["Erhöht den KRIT-SCH des Trägers um 36%. Erhöht den durch Fertigkeiten und Ultimates verursachten SCH um 18%. Nach dem Einsatz der Fertigkeit oder des Ultimates erhält der Träger Somnus Corpus. Beim Auslösen eines Folgeangriffs wird Somnus Corpus verbraucht und der vom Folgeangriff verursachte SCH wird um 48% erhöht.", "Erhöht den KRIT-SCH des Trägers um 42%. Erhöht den durch Fertigkeiten und Ultimates verursachten SCH um 21%. Nach dem Einsatz der Fertigkeit oder des Ultimates erhält der Träger Somnus Corpus. Beim Auslösen eines Folgeangriffs wird Somnus Corpus verbraucht und der vom Folgeangriff verursachte SCH wird um 56% erhöht.", "Erhöht den KRIT-SCH des Trägers um 48%. Erhöht den durch Fertigkeiten und Ultimates verursachten SCH um 24%. Nach dem Einsatz der Fertigkeit oder des Ultimates erhält der Träger Somnus Corpus. Beim Auslösen eines Folgeangriffs wird Somnus Corpus verbraucht und der vom Folgeangriff verursachte SCH wird um 64% erhöht.", "Erhöht den KRIT-SCH des Trägers um 54%. Erhöht den durch Fertigkeiten und Ultimates verursachten SCH um 27%. Nach dem Einsatz der Fertigkeit oder des Ultimates erhält der Träger Somnus Corpus. Beim Auslösen eines Folgeangriffs wird Somnus Corpus verbraucht und der vom Folgeangriff verursachte SCH wird um 72% erhöht.", "Erhöht den KRIT-SCH des Trägers um 60%. Erhöht den durch Fertigkeiten und Ultimates verursachten SCH um 30%. Nach dem Einsatz der Fertigkeit oder des Ultimates erhält der Träger Somnus Corpus. Beim Auslösen eines Folgeangriffs wird Somnus Corpus verbraucht und der vom Folgeangriff verursachte SCH wird um 80% erhöht."]}'),
  ('Vorhang auf', 'Die Nichtigkeit', 4, 'assets/images/light_cones/it_s_showtime.png', '{"name": "Selbstbelustigung", "text": ["Wenn der Träger einem Gegner einen Debuff zufügt, erhält er eine Stapelung „Trick“. Jede Stapelung erhöht den verursachten SCH des Trägers für 1 Rd. um 6% bis max. 3 Stapelungen. Wenn die Effekt-Trefferrate des Trägers 80% oder höher ist, wird der ANG um 20% erhöht.", "Wenn der Träger einem Gegner einen Debuff zufügt, erhält er eine Stapelung „Trick“. Jede Stapelung erhöht den verursachten SCH des Trägers für 1 Rd. um 7% bis max. 3 Stapelungen. Wenn die Effekt-Trefferrate des Trägers 80% oder höher ist, wird der ANG um 24% erhöht.", "Wenn der Träger einem Gegner einen Debuff zufügt, erhält er eine Stapelung „Trick“. Jede Stapelung erhöht den verursachten SCH des Trägers für 1 Rd. um 8% bis max. 3 Stapelungen. Wenn die Effekt-Trefferrate des Trägers 80% oder höher ist, wird der ANG um 28% erhöht.", "Wenn der Träger einem Gegner einen Debuff zufügt, erhält er eine Stapelung „Trick“. Jede Stapelung erhöht den verursachten SCH des Trägers für 1 Rd. um 9% bis max. 3 Stapelungen. Wenn die Effekt-Trefferrate des Trägers 80% oder höher ist, wird der ANG um 32% erhöht.", "Wenn der Träger einem Gegner einen Debuff zufügt, erhält er eine Stapelung „Trick“. Jede Stapelung erhöht den verursachten SCH des Trägers für 1 Rd. um 10% bis max. 3 Stapelungen. Wenn die Effekt-Trefferrate des Trägers 80% oder höher ist, wird der ANG um 36% erhöht."]}'),
  ('Warme Nächte dauern nicht lange', 'Der Überfluss', 4, 'assets/images/light_cones/warmth_shortens_cold_nights.png', '{"name": "Kleines Licht", "text": ["Erhöht die max. LP des Trägers um 16%. Stellt nach dem Einsatz des Standardangriffs oder der Fertigkeit die LP aller Verbündeten um 2% ihrer jeweiligen max. LP wieder her.", "Erhöht die max. LP des Trägers um 20%. Stellt nach dem Einsatz des Standardangriffs oder der Fertigkeit die LP aller Verbündeten um 2,5% ihrer jeweiligen max. LP wieder her.", "Erhöht die max. LP des Trägers um 24%. Stellt nach dem Einsatz des Standardangriffs oder der Fertigkeit die LP aller Verbündeten um 3% ihrer jeweiligen max. LP wieder her.", "Erhöht die max. LP des Trägers um 28%. Stellt nach dem Einsatz des Standardangriffs oder der Fertigkeit die LP aller Verbündeten um 3,5% ihrer jeweiligen max. LP wieder her.", "Erhöht die max. LP des Trägers um 32%. Stellt nach dem Einsatz des Standardangriffs oder der Fertigkeit die LP aller Verbündeten um 4% ihrer jeweiligen max. LP wieder her."]}'),
  ('Warum singt der Ozean', 'Die Nichtigkeit', 5, 'assets/images/light_cones/why_does_the_ocean_sing.png', '{"name": "Solo", "text": ["Erhöht die Effekt-Trefferrate des Trägers um 40%. Wenn ein Gegner vom Träger mit einem Debuff belegt wurde, besteht eine Grundchance von 80%, das Ziel für 3 Rd. in den Status „Seelenverwirrung“ zu versetzen. Effekte desselben Typs sind nicht stapelbar. Im Status Seelenverwirrung wird der DoT für jeden vom Träger belegten Debuff um 5% erhöht. Dieser Effekt ist bis zu 6-fach stapelbar. Wenn das Ziel von einem Verbündeten angegriffen wird, wird die GES des Angreifers für 3 Rd. um 10% erhöht. Wenn der Träger handlungsunfähig wird, werden alle Stapelungen von Seelenverwirrung entfernt.", "Erhöht die Effekt-Trefferrate des Trägers um 45%. Wenn ein Gegner vom Träger mit einem Debuff belegt wurde, besteht eine Grundchance von 80%, das Ziel für 3 Rd. in den Status „Seelenverwirrung“ zu versetzen. Effekte desselben Typs sind nicht stapelbar. Im Status Seelenverwirrung wird der DoT für jeden vom Träger belegten Debuff um 6,2% erhöht. Dieser Effekt ist bis zu 6-fach stapelbar. Wenn das Ziel von einem Verbündeten angegriffen wird, wird die GES des Angreifers für 3 Rd. um 12,5% erhöht. Wenn der Träger handlungsunfähig wird, werden alle Stapelungen von Seelenverwirrung entfernt.", "Erhöht die Effekt-Trefferrate des Trägers um 50%. Wenn ein Gegner vom Träger mit einem Debuff belegt wurde, besteht eine Grundchance von 80%, das Ziel für 3 Rd. in den Status „Seelenverwirrung“ zu versetzen. Effekte desselben Typs sind nicht stapelbar. Im Status Seelenverwirrung wird der DoT für jeden vom Träger belegten Debuff um 7,5% erhöht. Dieser Effekt ist bis zu 6-fach stapelbar. Wenn das Ziel von einem Verbündeten angegriffen wird, wird die GES des Angreifers für 3 Rd. um 15% erhöht. Wenn der Träger handlungsunfähig wird, werden alle Stapelungen von Seelenverwirrung entfernt.", "Erhöht die Effekt-Trefferrate des Trägers um 55%. Wenn ein Gegner vom Träger mit einem Debuff belegt wurde, besteht eine Grundchance von 80%, das Ziel für 3 Rd. in den Status „Seelenverwirrung“ zu versetzen. Effekte desselben Typs sind nicht stapelbar. Im Status Seelenverwirrung wird der DoT für jeden vom Träger belegten Debuff um 8,8% erhöht. Dieser Effekt ist bis zu 6-fach stapelbar. Wenn das Ziel von einem Verbündeten angegriffen wird, wird die GES des Angreifers für 3 Rd. um 17,5% erhöht. Wenn der Träger handlungsunfähig wird, werden alle Stapelungen von Seelenverwirrung entfernt.", "Erhöht die Effekt-Trefferrate des Trägers um 60%. Wenn ein Gegner vom Träger mit einem Debuff belegt wurde, besteht eine Grundchance von 80%, das Ziel für 3 Rd. in den Status „Seelenverwirrung“ zu versetzen. Effekte desselben Typs sind nicht stapelbar. Im Status Seelenverwirrung wird der DoT für jeden vom Träger belegten Debuff um 10% erhöht. Dieser Effekt ist bis zu 6-fach stapelbar. Wenn das Ziel von einem Verbündeten angegriffen wird, wird die GES des Angreifers für 3 Rd. um 20% erhöht. Wenn der Träger handlungsunfähig wird, werden alle Stapelungen von Seelenverwirrung entfernt."]}'),
  ('Weisheit', 'Die Gelehrsamkeit', 3, 'assets/images/light_cones/sagacity.png', '{"name": "Genie", "text": ["Erhöht beim Einsatz des Ultimates den ANG des Trägers für 2 Rd. um 24%.", "Erhöht beim Einsatz des Ultimates den ANG des Trägers für 2 Rd. um 30%.", "Erhöht beim Einsatz des Ultimates den ANG des Trägers für 2 Rd. um 36%.", "Erhöht beim Einsatz des Ultimates den ANG des Trägers für 2 Rd. um 42%.", "Erhöht beim Einsatz des Ultimates den ANG des Trägers für 2 Rd. um 48%."]}'),
  ('Wenn Zeit eine Blume wäre', 'Die Harmonie', 5, 'assets/images/light_cones/if_time_were_a_flower.png', '{"name": "Hoffnung", "text": ["Erhöht den KRIT-SCH des Trägers um 36%. Nachdem der Träger einen Folgeangriff ausgeführt hat, wird zusätzlich 12 Pkt. Energie wiederhergestellt und „Orakel“ für 2 Rd. erhalten. Wenn der Träger Orakel besitzt, wird der KRIT-SCH aller Verbündeten um 48% erhöht. Beim Kampfeintritt stellt der Träger 21 Pkt. Energie wieder her und erhält für 2 Rd. Orakel.", "Erhöht den KRIT-SCH des Trägers um 42%. Nachdem der Träger einen Folgeangriff ausgeführt hat, wird zusätzlich 12 Pkt. Energie wiederhergestellt und „Orakel“ für 2 Rd. erhalten. Wenn der Träger Orakel besitzt, wird der KRIT-SCH aller Verbündeten um 60% erhöht. Beim Kampfeintritt stellt der Träger 21 Pkt. Energie wieder her und erhält für 2 Rd. Orakel.", "Erhöht den KRIT-SCH des Trägers um 48%. Nachdem der Träger einen Folgeangriff ausgeführt hat, wird zusätzlich 12 Pkt. Energie wiederhergestellt und „Orakel“ für 2 Rd. erhalten. Wenn der Träger Orakel besitzt, wird der KRIT-SCH aller Verbündeten um 72% erhöht. Beim Kampfeintritt stellt der Träger 21 Pkt. Energie wieder her und erhält für 2 Rd. Orakel.", "Erhöht den KRIT-SCH des Trägers um 54%. Nachdem der Träger einen Folgeangriff ausgeführt hat, wird zusätzlich 12 Pkt. Energie wiederhergestellt und „Orakel“ für 2 Rd. erhalten. Wenn der Träger Orakel besitzt, wird der KRIT-SCH aller Verbündeten um 84% erhöht. Beim Kampfeintritt stellt der Träger 21 Pkt. Energie wieder her und erhält für 2 Rd. Orakel.", "Erhöht den KRIT-SCH des Trägers um 60%. Nachdem der Träger einen Folgeangriff ausgeführt hat, wird zusätzlich 12 Pkt. Energie wiederhergestellt und „Orakel“ für 2 Rd. erhalten. Wenn der Träger Orakel besitzt, wird der KRIT-SCH aller Verbündeten um 96% erhöht. Beim Kampfeintritt stellt der Träger 21 Pkt. Energie wieder her und erhält für 2 Rd. Orakel."]}'),
  ('Wenn ein Stern den Nachthimmel erhellt', 'Die Gelehrsamkeit', 5, 'assets/images/light_cones/a_star_that_lights_the_night.png', '{"name": "Erster Wunsch", "text": ["Der Träger ignoriert beim Verursachen von SCH 32% der VTD des Ziels. Wenn der Träger die Unterstützungsfertigkeit einsetzt, stellt er 6 Energie wieder her und erhält „Segeln“, der 2 Rd. anhält und bis zu 3-fach stapelbar ist. Jede Stapelung von Segeln erhöht den Unterstützungsfertigkeits-SCH um 20%. Erreicht Segeln 3 Stapelungen, erhöht jede Stapelung von Segeln den Ultimate-SCH um 20%.", "Der Träger ignoriert beim Verursachen von SCH 36% der VTD des Ziels. Wenn der Träger die Unterstützungsfertigkeit einsetzt, stellt er 6 Energie wieder her und erhält „Segeln“, der 2 Rd. anhält und bis zu 3-fach stapelbar ist. Jede Stapelung von Segeln erhöht den Unterstützungsfertigkeits-SCH um 25%. Erreicht Segeln 3 Stapelungen, erhöht jede Stapelung von Segeln den Ultimate-SCH um 25%.", "Der Träger ignoriert beim Verursachen von SCH 40% der VTD des Ziels. Wenn der Träger die Unterstützungsfertigkeit einsetzt, stellt er 6 Energie wieder her und erhält „Segeln“, der 2 Rd. anhält und bis zu 3-fach stapelbar ist. Jede Stapelung von Segeln erhöht den Unterstützungsfertigkeits-SCH um 30%. Erreicht Segeln 3 Stapelungen, erhöht jede Stapelung von Segeln den Ultimate-SCH um 30%.", "Der Träger ignoriert beim Verursachen von SCH 44% der VTD des Ziels. Wenn der Träger die Unterstützungsfertigkeit einsetzt, stellt er 6 Energie wieder her und erhält „Segeln“, der 2 Rd. anhält und bis zu 3-fach stapelbar ist. Jede Stapelung von Segeln erhöht den Unterstützungsfertigkeits-SCH um 35%. Erreicht Segeln 3 Stapelungen, erhöht jede Stapelung von Segeln den Ultimate-SCH um 35%.", "Der Träger ignoriert beim Verursachen von SCH 48% der VTD des Ziels. Wenn der Träger die Unterstützungsfertigkeit einsetzt, stellt er 6 Energie wieder her und erhält „Segeln“, der 2 Rd. anhält und bis zu 3-fach stapelbar ist. Jede Stapelung von Segeln erhöht den Unterstützungsfertigkeits-SCH um 40%. Erreicht Segeln 3 Stapelungen, erhöht jede Stapelung von Segeln den Ultimate-SCH um 40%."]}'),
  ('Wettrennen zum Horizont', 'Die Jagd', 4, 'assets/images/light_cones/race_to_the_horizon.png', '{"name": "Überholen", "text": ["Erhöht den ANG des Trägers um 12%. Nachdem der Träger seinen Folgeangriff ausgeführt hat, wird sein KRIT-SCH für 2 Rd. um 3% erhöht. Dieser Effekt ist bis zu 10-fach stapelbar.", "Erhöht den ANG des Trägers um 15%. Nachdem der Träger seinen Folgeangriff ausgeführt hat, wird sein KRIT-SCH für 2 Rd. um 3,5% erhöht. Dieser Effekt ist bis zu 10-fach stapelbar.", "Erhöht den ANG des Trägers um 18%. Nachdem der Träger seinen Folgeangriff ausgeführt hat, wird sein KRIT-SCH für 2 Rd. um 4% erhöht. Dieser Effekt ist bis zu 10-fach stapelbar.", "Erhöht den ANG des Trägers um 21%. Nachdem der Träger seinen Folgeangriff ausgeführt hat, wird sein KRIT-SCH für 2 Rd. um 4,5% erhöht. Dieser Effekt ist bis zu 10-fach stapelbar.", "Erhöht den ANG des Trägers um 24%. Nachdem der Träger seinen Folgeangriff ausgeführt hat, wird sein KRIT-SCH für 2 Rd. um 5% erhöht. Dieser Effekt ist bis zu 10-fach stapelbar."]}'),
  ('Wie die Morgendämmerung brennt', 'Die Zerstörung', 5, 'assets/images/light_cones/thus_burns_the_dawn.png', '{"name": "Verloren", "text": ["Erhöht die Basis-GES des Trägers um 12 und ignoriert beim Verursachen von SCH 18% der VTD des Ziels. Nach dem Einsatz des Ultimates erhält der Träger „Gleißende Sonne“, die zu Beginn der Runde entfernt wird. Wenn der Träger Gleißende Sonne besitzt, wird sein verursachter SCH um 60% erhöht.", "Erhöht die Basis-GES des Trägers um 14 und ignoriert beim Verursachen von SCH 23% der VTD des Ziels. Nach dem Einsatz des Ultimates erhält der Träger „Gleißende Sonne“, die zu Beginn der Runde entfernt wird. Wenn der Träger Gleißende Sonne besitzt, wird sein verursachter SCH um 78% erhöht.", "Erhöht die Basis-GES des Trägers um 16 und ignoriert beim Verursachen von SCH 27% der VTD des Ziels. Nach dem Einsatz des Ultimates erhält der Träger „Gleißende Sonne“, die zu Beginn der Runde entfernt wird. Wenn der Träger Gleißende Sonne besitzt, wird sein verursachter SCH um 96% erhöht.", "Erhöht die Basis-GES des Trägers um 18 und ignoriert beim Verursachen von SCH 32% der VTD des Ziels. Nach dem Einsatz des Ultimates erhält der Träger „Gleißende Sonne“, die zu Beginn der Runde entfernt wird. Wenn der Träger Gleißende Sonne besitzt, wird sein verursachter SCH um 114% erhöht.", "Erhöht die Basis-GES des Trägers um 20 und ignoriert beim Verursachen von SCH 36% der VTD des Ziels. Nach dem Einsatz des Ultimates erhält der Träger „Gleißende Sonne“, die zu Beginn der Runde entfernt wird. Wenn der Träger Gleißende Sonne besitzt, wird sein verursachter SCH um 132% erhöht."]}'),
  ('Wiedersehen an der Ziellinie', 'Die Jagd', 4, 'assets/images/light_cones/see_you_at_the_end.png', '{"name": "Beharrlichkeit", "text": ["Erhöht den KRIT-SCH des Trägers um 24%. Erhöht den verursachten Fertigkeits- und Folgeangriff-SCH des Trägers um 24%.", "Erhöht den KRIT-SCH des Trägers um 28%. Erhöht den verursachten Fertigkeits- und Folgeangriff-SCH des Trägers um 28%.", "Erhöht den KRIT-SCH des Trägers um 32%. Erhöht den verursachten Fertigkeits- und Folgeangriff-SCH des Trägers um 32%.", "Erhöht den KRIT-SCH des Trägers um 36%. Erhöht den verursachten Fertigkeits- und Folgeangriff-SCH des Trägers um 36%.", "Erhöht den KRIT-SCH des Trägers um 40%. Erhöht den verursachten Fertigkeits- und Folgeangriff-SCH des Trägers um 40%."]}'),
  ('Willkommen in der kosmischen Stadt', 'Das Hochgefühl', 5, 'assets/images/light_cones/welcome_to_the_cosmic_city.png', '{"name": "Garantierter Sieg", "text": ["Erhöht die GES des Trägers um 18%. Der verursachte Hochgefühl-SCH ignoriert 20% der VTD des Ziels. Wenn der Träger den Ultimate auf sich selbst als Einzelziel anwendet, erhält er 20 Lachpunkte. Dieser Effekt kann bis zu 1-mal ausgelöst werden. Nach 3-maligem Einsatz des Standardangriffs wird die Auslösungsanzahl zurückgesetzt.", "Erhöht die GES des Trägers um 21%. Der verursachte Hochgefühl-SCH ignoriert 24% der VTD des Ziels. Wenn der Träger den Ultimate auf sich selbst als Einzelziel anwendet, erhält er 25 Lachpunkte. Dieser Effekt kann bis zu 1-mal ausgelöst werden. Nach 3-maligem Einsatz des Standardangriffs wird die Auslösungsanzahl zurückgesetzt.", "Erhöht die GES des Trägers um 24%. Der verursachte Hochgefühl-SCH ignoriert 28% der VTD des Ziels. Wenn der Träger den Ultimate auf sich selbst als Einzelziel anwendet, erhält er 30 Lachpunkte. Dieser Effekt kann bis zu 1-mal ausgelöst werden. Nach 3-maligem Einsatz des Standardangriffs wird die Auslösungsanzahl zurückgesetzt.", "Erhöht die GES des Trägers um 27%. Der verursachte Hochgefühl-SCH ignoriert 32% der VTD des Ziels. Wenn der Träger den Ultimate auf sich selbst als Einzelziel anwendet, erhält er 35 Lachpunkte. Dieser Effekt kann bis zu 1-mal ausgelöst werden. Nach 3-maligem Einsatz des Standardangriffs wird die Auslösungsanzahl zurückgesetzt.", "Erhöht die GES des Trägers um 30%. Der verursachte Hochgefühl-SCH ignoriert 36% der VTD des Ziels. Wenn der Träger den Ultimate auf sich selbst als Einzelziel anwendet, erhält er 40 Lachpunkte. Dieser Effekt kann bis zu 1-mal ausgelöst werden. Nach 3-maligem Einsatz des Standardangriffs wird die Auslösungsanzahl zurückgesetzt."]}'),
  ('Wir sehen uns am Ende der Welt!', 'Das Hochgefühl', 4, 'assets/images/light_cones/see_you_at_the_world_s_end.png', '{"name": "Verschwörer", "text": ["Für jede Figur auf dem Pfad des Hochgefühls im Team wird der KRIT-SCH des Trägers um 6% erhöht. Wenn sich Äonin ★ Aha auf dem Kampffeld befindet, wird der KRIT-SCH des Trägers zusätzlich um 12% erhöht.", "Für jede Figur auf dem Pfad des Hochgefühls im Team wird der KRIT-SCH des Trägers um 7% erhöht. Wenn sich Äonin ★ Aha auf dem Kampffeld befindet, wird der KRIT-SCH des Trägers zusätzlich um 14% erhöht.", "Für jede Figur auf dem Pfad des Hochgefühls im Team wird der KRIT-SCH des Trägers um 8% erhöht. Wenn sich Äonin ★ Aha auf dem Kampffeld befindet, wird der KRIT-SCH des Trägers zusätzlich um 16% erhöht.", "Für jede Figur auf dem Pfad des Hochgefühls im Team wird der KRIT-SCH des Trägers um 9% erhöht. Wenn sich Äonin ★ Aha auf dem Kampffeld befindet, wird der KRIT-SCH des Trägers zusätzlich um 18% erhöht.", "Für jede Figur auf dem Pfad des Hochgefühls im Team wird der KRIT-SCH des Trägers um 10% erhöht. Wenn sich Äonin ★ Aha auf dem Kampffeld befindet, wird der KRIT-SCH des Trägers zusätzlich um 20% erhöht."]}'),
  ('Wir sind Wildfeuer', 'Die Bewahrung', 4, 'assets/images/light_cones/we_are_wildfire.png', '{"name": "Mit tränenden Augen", "text": ["Verringert zu Beginn des Kampfes erlittenen SCH aller Verbündeten für 5 Rd. um 8%. Stellt unmittelbar LP für alle Verbündeten in Höhe von 30% des jeweiligen LP-Verlusts wieder her.", "Verringert zu Beginn des Kampfes erlittenen SCH aller Verbündeten für 5 Rd. um 10%. Stellt unmittelbar LP für alle Verbündeten in Höhe von 35% des jeweiligen LP-Verlusts wieder her.", "Verringert zu Beginn des Kampfes erlittenen SCH aller Verbündeten für 5 Rd. um 12%. Stellt unmittelbar LP für alle Verbündeten in Höhe von 40% des jeweiligen LP-Verlusts wieder her.", "Verringert zu Beginn des Kampfes erlittenen SCH aller Verbündeten für 5 Rd. um 14%. Stellt unmittelbar LP für alle Verbündeten in Höhe von 45% des jeweiligen LP-Verlusts wieder her.", "Verringert zu Beginn des Kampfes erlittenen SCH aller Verbündeten für 5 Rd. um 16%. Stellt unmittelbar LP für alle Verbündeten in Höhe von 50% des jeweiligen LP-Verlusts wieder her."]}'),
  ('Wir werden uns wiedersehen', 'Die Nichtigkeit', 4, 'assets/images/light_cones/we_will_meet_again.png', '{"name": "Ein Diskurs in Waffen", "text": ["Nach dem Einsatz des Standardangriffs oder der Fertigkeit fügt der Träger einem zufälligen angegriffen Gegner zusätzlichen SCH in Höhe von 48% seines ANG zu.", "Nach dem Einsatz des Standardangriffs oder der Fertigkeit fügt der Träger einem zufälligen angegriffen Gegner zusätzlichen SCH in Höhe von 60% seines ANG zu.", "Nach dem Einsatz des Standardangriffs oder der Fertigkeit fügt der Träger einem zufälligen angegriffen Gegner zusätzlichen SCH in Höhe von 72% seines ANG zu.", "Nach dem Einsatz des Standardangriffs oder der Fertigkeit fügt der Träger einem zufälligen angegriffen Gegner zusätzlichen SCH in Höhe von 84% seines ANG zu.", "Nach dem Einsatz des Standardangriffs oder der Fertigkeit fügt der Träger einem zufälligen angegriffen Gegner zusätzlichen SCH in Höhe von 96% seines ANG zu."]}'),
  ('Wirrgarten-Restaurant für immer', 'Die Harmonie', 4, 'assets/images/light_cones/the_forever_victual.png', '{"name": "Mmm, lecker!", "text": ["Erhöht den ANG des Trägers um 16%. Nachdem der Träger seine Fertigkeit eingesetzt hat, wird sein ANG um 8% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar.", "Erhöht den ANG des Trägers um 20%. Nachdem der Träger seine Fertigkeit eingesetzt hat, wird sein ANG um 10% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar.", "Erhöht den ANG des Trägers um 24%. Nachdem der Träger seine Fertigkeit eingesetzt hat, wird sein ANG um 12% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar.", "Erhöht den ANG des Trägers um 28%. Nachdem der Träger seine Fertigkeit eingesetzt hat, wird sein ANG um 14% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar.", "Erhöht den ANG des Trägers um 32%. Nachdem der Träger seine Fertigkeit eingesetzt hat, wird sein ANG um 16% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar."]}'),
  ('Wohin sollen die Träume gehen', 'Die Zerstörung', 5, 'assets/images/light_cones/whereabouts_should_dreams_rest.png', '{"name": "Metamorphose", "text": ["Erhöht den Brucheffekt des Trägers um 60%. Wenn der Träger bei einem Gegner Bruch-SCH verursacht, wird dieser für 2 Rd. mit „Niedergeschmettert“ belegt. Gegner mit Niedergeschmettert erleiden durch den Träger 24% mehr Bruch-SCH und ihre GES wird um 20% reduziert. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 70%. Wenn der Träger bei einem Gegner Bruch-SCH verursacht, wird dieser für 2 Rd. mit „Niedergeschmettert“ belegt. Gegner mit Niedergeschmettert erleiden durch den Träger 28% mehr Bruch-SCH und ihre GES wird um 20% reduziert. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 80%. Wenn der Träger bei einem Gegner Bruch-SCH verursacht, wird dieser für 2 Rd. mit „Niedergeschmettert“ belegt. Gegner mit Niedergeschmettert erleiden durch den Träger 32% mehr Bruch-SCH und ihre GES wird um 20% reduziert. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 90%. Wenn der Träger bei einem Gegner Bruch-SCH verursacht, wird dieser für 2 Rd. mit „Niedergeschmettert“ belegt. Gegner mit Niedergeschmettert erleiden durch den Träger 36% mehr Bruch-SCH und ihre GES wird um 20% reduziert. Effekte der gleichen Art sind nicht stapelbar.", "Erhöht den Brucheffekt des Trägers um 100%. Wenn der Träger bei einem Gegner Bruch-SCH verursacht, wird dieser für 2 Rd. mit „Niedergeschmettert“ belegt. Gegner mit Niedergeschmettert erleiden durch den Träger 40% mehr Bruch-SCH und ihre GES wird um 20% reduziert. Effekte der gleichen Art sind nicht stapelbar."]}'),
  ('Wuff! Zeit zum Laufen!', 'Die Zerstörung', 4, 'assets/images/light_cones/woof_walk_time.png', '{"name": "Lauf!", "text": ["Erhöht den ANG des Trägers um 10% und den SCH, der Gegnern im Status Brennen oder Bluten zugefügt wird, um 16%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den ANG des Trägers um 13% und den SCH, der Gegnern im Status Brennen oder Bluten zugefügt wird, um 20%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den ANG des Trägers um 15% und den SCH, der Gegnern im Status Brennen oder Bluten zugefügt wird, um 24%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den ANG des Trägers um 18% und den SCH, der Gegnern im Status Brennen oder Bluten zugefügt wird, um 28%. Dieser Effekt gilt ebenfalls für DoT.", "Erhöht den ANG des Trägers um 20% und den SCH, der Gegnern im Status Brennen oder Bluten zugefügt wird, um 32%. Dieser Effekt gilt ebenfalls für DoT."]}'),
  ('Wurfpfeil', 'Die Jagd', 3, 'assets/images/light_cones/darting_arrow.png', '{"name": "Kriegsschrei", "text": ["Erhöht den ANG des Trägers für 3 Rd. um 24%, nachdem er einen Gegner besiegt hat.", "Erhöht den ANG des Trägers für 3 Rd. um 30%, nachdem er einen Gegner besiegt hat.", "Erhöht den ANG des Trägers für 3 Rd. um 36%, nachdem er einen Gegner besiegt hat.", "Erhöht den ANG des Trägers für 3 Rd. um 42%, nachdem er einen Gegner besiegt hat.", "Erhöht den ANG des Trägers für 3 Rd. um 48%, nachdem er einen Gegner besiegt hat."]}'),
  ('Zeitalter des goldenen Blutes', 'Die Harmonie', 5, 'assets/images/light_cones/epoch_etched_in_golden_blood.png', '{"name": "Erobern", "text": ["Erhöht den ANG des Trägers um 64%. Stellt nach dem Einsatz des Ultimates 1 Fertigkeitspunkt wieder her. Nachdem der Träger eine Fertigkeit auf eine verbündete Figur eingesetzt hat, wird der Fertigkeits-SCH des Ziels für 3 Rd. um 54% erhöht.", "Erhöht den ANG des Trägers um 80%. Stellt nach dem Einsatz des Ultimates 1 Fertigkeitspunkt wieder her. Nachdem der Träger eine Fertigkeit auf eine verbündete Figur eingesetzt hat, wird der Fertigkeits-SCH des Ziels für 3 Rd. um 67,5% erhöht.", "Erhöht den ANG des Trägers um 96%. Stellt nach dem Einsatz des Ultimates 1 Fertigkeitspunkt wieder her. Nachdem der Träger eine Fertigkeit auf eine verbündete Figur eingesetzt hat, wird der Fertigkeits-SCH des Ziels für 3 Rd. um 81% erhöht.", "Erhöht den ANG des Trägers um 112%. Stellt nach dem Einsatz des Ultimates 1 Fertigkeitspunkt wieder her. Nachdem der Träger eine Fertigkeit auf eine verbündete Figur eingesetzt hat, wird der Fertigkeits-SCH des Ziels für 3 Rd. um 94,5% erhöht.", "Erhöht den ANG des Trägers um 128%. Stellt nach dem Einsatz des Ultimates 1 Fertigkeitspunkt wieder her. Nachdem der Träger eine Fertigkeit auf eine verbündete Figur eingesetzt hat, wird der Fertigkeits-SCH des Ziels für 3 Rd. um 108% erhöht."]}'),
  ('Zerstörtes Zuhause', 'Die Zerstörung', 3, 'assets/images/light_cones/shattered_home.png', '{"name": "Ausrottung", "text": ["Verursacht 20% zusätzlichen SCH an allen Gegnern, deren LP-Prozentsatz über 50% liegt.", "Verursacht 25% zusätzlichen SCH an allen Gegnern, deren LP-Prozentsatz über 50% liegt.", "Verursacht 30% zusätzlichen SCH an allen Gegnern, deren LP-Prozentsatz über 50% liegt.", "Verursacht 35% zusätzlichen SCH an allen Gegnern, deren LP-Prozentsatz über 50% liegt.", "Verursacht 40% zusätzlichen SCH an allen Gegnern, deren LP-Prozentsatz über 50% liegt."]}'),
  ('Zusammenbruch des Himmels', 'Die Zerstörung', 3, 'assets/images/light_cones/collapsing_sky.png', '{"name": "Verwüstung", "text": ["Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 20%.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 25%.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 30%.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 35%.", "Erhöht den durch Standardangriffe und Fertigkeiten verursachten SCH des Trägers um 40%."]}')
INSERT INTO relic_sets (name, kind, bonus_2pc, bonus_4pc, icon_path, pieces_json) VALUES
  ('AVZ des Subraums', 'Ornament', 'Erhöht die GES des Trägers um 6%. Wenn die GES des Trägers 145 oder höher beträgt, wird der Brucheffekt aller Verbündeten nach Kampfeintritt um 18% erhöht. Dieser Effekt ist nicht stapelbar.', NULL, 'assets/images/relic_sets/subspace_asc_center.png', '{"Planarsphäre": ["Negativfilmrolle des AVZ"], "Verbindungsseil": ["Dunkler Riss des AVZ"]}'),
  ('Amphoreus, Land der Ewigkeit', 'Ornament', 'Erhöht die KRIT-Rate des Trägers um 8%. Wenn sich der Memogeist des Trägers auf dem Kampffeld befindet, wird die GES aller Verbündeten um 8% erhöht. Dieser Effekt ist nicht stapelbar.', NULL, 'assets/images/relic_sets/amphoreus_the_eternal_land.png', '{"Planarsphäre": ["Die ewigen Verse von Amphoreus"], "Verbindungsseil": ["Das Ende von Amphoreus’ Westwind"]}'),
  ('Ankerplatz des gefallenen Sterns', 'Ornament', 'Erhöht die KRIT-Rate des Trägers um 8%. Wenn beim Kampfeintritt sowohl der Träger als auch ein weiteres Teammitglied Trailblaze-Gefährten sind, wird der KRIT-SCH des Trägers um 32% erhöht.', NULL, 'assets/images/relic_sets/fallen_star_anchorage.png', '{"Planarsphäre": ["Silberne Schienen des Ankerplatzes"], "Verbindungsseil": ["Gestrandeter Express am Ankerplatz"]}'),
  ('Belobog der Architekten', 'Ornament', 'Erhöht die VTD des Trägers um 15%. Wenn die Effekt-Trefferrate des Trägers 50% oder höher erreicht, wird seine VTD zusätzlich um 15% erhöht.', NULL, 'assets/images/relic_sets/belobog_of_the_architects.png', '{"Planarsphäre": ["Belobogs eiserne Verteidigung"], "Verbindungsseil": ["Belobogs Festung der Bewahrung"]}'),
  ('Duran, Dynastie der rennenden Wölfe', 'Ornament', 'Wenn ein Verbündeter einen Folgeangriff ausführt, erhält der Träger 1 Stapelung „Verdienst“, bis zu 5 Stapelungen. Jede Stapelung Verdienst erhöht den durch Folgeangriffe verursachten SCH des Trägers um 5%. Werden 5 Stapelungen erreicht, wird der KRIT-SCH des Trägers zusätzlich um 25% erhöht.', NULL, 'assets/images/relic_sets/duran_dynasty_of_running_wolves.png', '{"Planarsphäre": ["Zügel von Durans Mechabestie"], "Verbindungsseil": ["Durans Zelt des goldenen Himmels"]}'),
  ('Etappe Nr. Null von Punklorde', 'Ornament', 'Erhöht das Hochgefühl des Trägers um 8%. Wenn das Hochgefühl im Kampf zum ersten Mal 40%/80% erreicht, wird der KRIT-SCH des Trägers um 20%/32% erhöht.', NULL, 'assets/images/relic_sets/punklorde_stage_zero.png', '{"Planarsphäre": ["Datenflut von Punklorde"], "Verbindungsseil": ["Die Regenbogenstadt von Punklorde"]}'),
  ('Flotte der Alterslosen', 'Ornament', 'Erhöht die max. LP des Trägers um 12%. Wenn die GES des Trägers 120 oder höher erreicht, wird der ANG aller Verbündeten zusätzlich um 8% erhöht.', NULL, 'assets/images/relic_sets/fleet_of_the_ageless.png', '{"Planarsphäre": ["Himmelsbaumranken der Xianzhou Luofu"], "Verbindungsseil": ["Die Himmlische Arche der Xianzhou Luofu"]}'),
  ('Gebrochener Kiel', 'Ornament', 'Der Effekt-WDS des Trägers wird um 10% erhöht. Wenn der Effekt-WDS des Trägers 30% oder mehr beträgt, wird der KRIT-SCH aller Verbündeten um 10% erhöht.', NULL, 'assets/images/relic_sets/broken_keel.png', '{"Planarsphäre": ["Gerissenes Tauwerk von Insumousu"], "Verbindungsseil": ["Walfänger von Insumousu"]}'),
  ('Gottes Moment der Freude', 'Ornament', 'Erhöht die GES des Trägers um 6%. Wenn das Hochgefühl des Trägers 40% oder höher beträgt, wird seine Aktion beim Kampfeintritt sofort um 40% vorgezogen.', NULL, 'assets/images/relic_sets/god_s_moment_of_joy.png', '{"Planarsphäre": ["Magische Requisite des Moments der Freude"], "Verbindungsseil": ["Ewige Bühne des Moments der Freude"]}'),
  ('Himmelsfront Glamoth', 'Ornament', 'Erhöht den ANG des Trägers um 12%. Wenn die GES des Trägers 135/160 oder höher erreicht, wird sein verursachter SCH um 12%/18% erhöht.', NULL, 'assets/images/relic_sets/firmament_frontline_glamoth.png', '{"Planarsphäre": ["Glamoths stiller Grabstein"], "Verbindungsseil": ["Glamoths eisernes Kavallerieregiment"]}'),
  ('Himmlischer Differenziator', 'Ornament', 'Erhöht den KRIT-SCH des Trägers um 16%. Wenn der aktuelle KRIT-SCH des Trägers 120% oder höher erreicht, wird die KRIT-Rate nach Kampfeintritt um 60% erhöht, bis zum Ende seines ersten Angriffs.', NULL, 'assets/images/relic_sets/celestial_differentiator.png', '{"Planarsphäre": ["Ringsystem des Planeten Screwllum"], "Verbindungsseil": ["Die mechanische Sonne des Planeten Screwllum"]}'),
  ('Institut für kosmische Biowissenschaften', 'Ornament', 'Wenn die max. Energie des Trägers beim Kampfeintritt mindestens 200 Pkt. beträgt, wird der verursachte SCH des Trägers für jeden überschüssigen Pkt. um 0.2% erhöht, bis zu einem Maximum von 32%.', NULL, 'assets/images/relic_sets/cosmic_life_sciences_institute.png', '{"Planarsphäre": ["Periphere Leitung des Instituts für Biowissenschaften"], "Verbindungsseil": ["Zentrale Drehscheibe des Instituts für Biowissenschaften"]}'),
  ('Izumo-Gensei und Takama-Himmelreich', 'Ornament', 'Erhöht den ANG des Trägers um 12%. Wenn beim Kampfeintritt mindestens ein Verbündeter dem gleichen Pfad wie der Träger folgt, wird die KRIT-Rate des Trägers um 12% erhöht.', NULL, 'assets/images/relic_sets/izumo_gensei_and_takama_divine_realm.png', '{"Planarsphäre": ["Izumos Klingen von Ende und Anfang"], "Verbindungsseil": ["Izumos Magatsu-no-Morokami"]}'),
  ('Küste der Weintrunkenheit', 'Ornament', 'Erhöht den ANG des Trägers um 12%. Wenn der ANG des Trägers 2400/3600 oder höher beträgt, wird sein verursachter DoT zusätzlich um 12%/24% erhöht.', NULL, 'assets/images/relic_sets/revelry_by_the_sea.png', '{"Planarsphäre": ["Gesangspfad der singenden Küste"], "Verbindungsseil": ["Flammendes Leuchtfeuer der singenden Küste"]}'),
  ('Lebhaftes Vonwacq', 'Ornament', 'Erhöht die Energie-Wiederherstellungsrate des Trägers um 5%. Wenn die GES des Trägers 120 oder höher erreicht, wird seine Aktion beim Kampfeintritt um 40% vorgezogen.', NULL, 'assets/images/relic_sets/sprightly_vonwacq.png', '{"Planarsphäre": ["Vonwacqs Inselküste"], "Verbindungsseil": ["Vonwacqs Geburtsinsel"]}'),
  ('Lushaka, die versunkene See', 'Ornament', 'Erhöht Die Energie-Wiederherstellungsrate des Trägers um 5%. Wenn der Träger nicht die erste Figur in der Teamformation ist, wird der ANG der ersten Figur in der Teamformation um 12% erhöht.', NULL, 'assets/images/relic_sets/lushaka_the_sunken_seas.png', '{"Planarsphäre": ["Die symbiotischen Seewege von Lushaka"], "Verbindungsseil": ["Die versunkene, azurblaue Hauptstadt von Lushaka"]}'),
  ('Pangalaktische Handelsgesellschaft', 'Ornament', 'Erhöht die Effekt-Trefferrate des Trägers um 10%. Erhöht gleichzeitig den ANG des Trägers in Höhe von 25% der Effekt-Trefferrate, bis zu einem Höchstwert von 25%.', NULL, 'assets/images/relic_sets/pan_cosmic_commercial_enterprise.png', '{"Planarsphäre": ["Handelsroute der IFK"], "Verbindungsseil": ["Das Mega-Hauptquartier der IFK"]}'),
  ('Penacony, Land der Träume', 'Ornament', 'Erhöht die Energie-Wiederherstellungsrate des Trägers um 5%. Erhöht den SCH aller anderen Verbündeten im Team mit dem gleichen Typ wie der Träger um 10%.', NULL, 'assets/images/relic_sets/penacony_land_of_the_dreams.png', '{"Planarsphäre": ["Penaconys Traumsuchspuren"], "Verbindungsseil": ["Penaconys Grandhotel"]}'),
  ('Raumstation für Versiegelung', 'Ornament', 'Erhöht ANG des Trägers um 12%. Wenn die GES des Trägers 120 oder höher erreicht, wird sein ANG zusätzlich um 12% erhöht.', NULL, 'assets/images/relic_sets/space_sealing_station.png', '{"Planarsphäre": ["Hertas Wanderschaft"], "Verbindungsseil": ["Hertas Raumstation"]}'),
  ('Regloses Salsotto', 'Ornament', 'Erhöht die KRIT-Rate des Trägers um 8%. Wenn die aktuelle KRIT-Rate des Trägers 50% oder höher erreicht, wird der durch Ultimates und Folgeangriffe verursachte SCH um 15% erhöht.', NULL, 'assets/images/relic_sets/inert_salsotto.png', '{"Planarsphäre": ["Tag-Nacht-Grenze von Salsotto"], "Verbindungsseil": ["Die fliegende Stadt von Salsotto"]}'),
  ('Riesenbaum des versunkenen Grübelns', 'Ornament', 'Erhöht die GES des Trägers um 6%. Wenn die GES des Trägers 135/180 oder höher erreicht, wird die bewirkte Heilung des Trägers und seines Memogeists um 12%/20% erhöht.', NULL, 'assets/images/relic_sets/giant_tree_of_rapt_brooding.png', '{"Planarsphäre": ["Verbindungsnetz des Hains der Erleuchtung"], "Verbindungsseil": ["Nachdenklicher Riesenbaum des Hains der Erleuchtung"]}'),
  ('Ruhiges Anwesen für die Gebeine der Toten', 'Ornament', 'Erhöht die max. LP des Trägers um 12%. Wenn die max. LP des Trägers 5000 oder mehr betragen, wird der KRIT-SCH des Trägers und seines Memogeistes um 28% erhöht.', NULL, 'assets/images/relic_sets/bone_collection_s_serene_demesne.png', '{"Planarsphäre": ["Todes-Knochenketten von Aidonia"], "Verbindungsseil": ["Grabsteine von Aidonia"]}'),
  ('Schmiede der Kalpagni-Laterne', 'Ornament', 'Erhöht die GES des Trägers um 6%. Trifft der Träger einen Gegner mit Feuer-Schwäche, wird sein Brucheffekt für 1 Rd. um 40% erhöht.', NULL, 'assets/images/relic_sets/forge_of_the_kalpagni_lantern.png', '{"Planarsphäre": ["Flammende Himmelsseide des Schmiedepalastes"], "Verbindungsseil": ["Lotus-Lampendocht des Schmiedepalastes"]}'),
  ('Stadt der unzähligen Sterne', 'Ornament', 'Wenn der Träger einen Folgeangriff einsetzt, wird sein ANG für 2 Rd. um 24% erhöht. Wenn ein Gegner besiegt wird, wird der KRIT-SCH aller Verbündeten im aktuellen Kampf um 12% erhöht. Dieser Effekt ist nicht stapelbar.', NULL, 'assets/images/relic_sets/city_of_converging_stars.png', '{"Planarsphäre": ["Mitarbeiterausweis von Astropolis"], "Verbindungsseil": ["Medienhauptquartier von Astropolis"]}'),
  ('Sternenarena', 'Ornament', 'Erhöht die KRIT-Rate des Trägers um 8%. Wenn die aktuelle KRIT-Rate des Trägers einen Wert von 70% oder höher erreicht, wird der durch Standardangriffe und Fertigkeiten verursachte SCH um 20% erhöht.', NULL, 'assets/images/relic_sets/rutilant_arena.png', '{"Planarsphäre": ["Lichtbogen-Rennbahn auf Taikiyan"], "Verbindungsseil": ["Laser-Stadion auf Taikiyan"]}'),
  ('Talia – Königreich der Banditen', 'Ornament', 'Erhöht den Brucheffekt des Trägers um 16%. Wenn die GES des Trägers 145 oder höher erreicht, wird der Brucheffekt des Trägers zusätzlich um 20% erhöht.', NULL, 'assets/images/relic_sets/talia_kingdom_of_banditry.png', '{"Planarsphäre": ["Freiliegendes Kabel aus Talia"], "Verbindungsseil": ["Alteisenstadt auf Talia"]}'),
  ('Tengoku@Livestream', 'Ornament', 'Erhöht den KRIT-SCH des Trägers um 16%. Wenn in derselben Runde mindestens 3 Fertigkeitspunkte verbraucht werden, wird der KRIT-SCH des Trägers für 3 Rd. zusätzlich um 32% erhöht.', NULL, 'assets/images/relic_sets/tengoku_livestream.png', '{"Planarsphäre": ["Die tausend Gespräche im Livestream"], "Verbindungsseil": ["Die tausend Gesichter im Livestream"]}'),
  ('Traumwebendes Feenreich', 'Ornament', 'Wenn die aktuelle Anzahl der Verbündeten auf dem Kampffeld nicht 4 beträgt, wird für jeden Verbündeten über/unter 4 der verursachte SCH des Trägers sowie seines Memogeists um 9%/12% erhöht. Dieser Effekt ist bis zu 4/3-fach stapelbar.', NULL, 'assets/images/relic_sets/arcadia_of_woven_dreams.png', '{"Planarsphäre": ["Wunschflöte des Wirrgartens"], "Verbindungsseil": ["Ruhiges Baumhaus des Wirrgartens"]}'),
  ('Verlassenes Sigonien', 'Ornament', 'Erhöht die KRIT-Rate des Trägers um 4%. Wenn Gegner besiegt werden, wird der KRIT-SCH des Trägers bis zu 10-mal um 4% erhöht.', NULL, 'assets/images/relic_sets/sigonia_the_unclaimed_desolation.png', '{"Planarsphäre": ["Sigonischer Knoten des Kreislaufs"], "Verbindungsseil": ["Liege der sigonischen Muttergöttin"]}'),
  ('Wunbanana-Park', 'Ornament', 'Erhöht den KRIT-SCH des Trägers um 16%. Befindet sich ein vom Träger beschworenes Objekt auf dem Kampffeld, wird der KRIT-SCH zusätzlich um 32% erhöht.', NULL, 'assets/images/relic_sets/the_wondrous_bananamusement_park.png', '{"Planarsphäre": ["Memetische Kabel im Banana-Park"], "Verbindungsseil": ["Kernplatz im Banana-Park"]}'),
  ('Adler des Zwielichts', 'Relikt', 'Erhöht Wind-SCH um 10%.', 'Nach dem Einsatz des Ultimates wird die Aktion des Trägers um 25% vorgezogen.', 'assets/images/relic_sets/eagle_of_twilight_line.png', '{"Kopf": ["Schnabelhelm des Adlers"], "Hände": ["Flugring des Adlers"], "Körper": ["Fluggeschirr des Adlers"], "Füße": ["Steppgamaschen des Adlers"]}'),
  ('Band des knisternden Donners', 'Relikt', 'Erhöht Blitz-SCH um 10%.', 'Erhöht beim Einsatz der Fertigkeit den ANG des Trägers für 1 Rd. um 20%.', 'assets/images/relic_sets/band_of_sizzling_thunder.png', '{"Kopf": ["Verspiegelte Sonnenbrille der Band"], "Hände": ["Tourarmband der Band"], "Körper": ["Nietenbesetzte Lederjacke der Band"], "Füße": ["Nietenbesetzte Boots der Band"]}'),
  ('Bote im Hackerspace', 'Relikt', 'Erhöht GES um 6%.', 'Wenn der Träger ein Ultimate auf einen Verbündeten anwendet, erhöht sich die GES aller Verbündeten für 1 Rd. um 12%. Dieser Effekt ist nicht stapelbar.', 'assets/images/relic_sets/messenger_traversing_hackerspace.png', '{"Kopf": ["Holobrille des Boten"], "Hände": ["Transformationsarm des Boten"], "Körper": ["Geheime Umhängetasche des Boten"], "Füße": ["Coole Turnschuhe des Boten"]}'),
  ('Champion des Straßenboxens', 'Relikt', 'Erhöht physischen SCH um 10%.', 'Wenn der Träger einen Angriff ausführt oder getroffen wird, wird sein ANG im aktuellen Kampf um 5% erhöht. Dieser Effekt ist bis zu 5-fach stapelbar.', 'assets/images/relic_sets/champion_of_streetwise_boxing.png', '{"Kopf": ["Kopfschutz des Champions"], "Hände": ["Schwere Handschuhe des Champions"], "Körper": ["Brustschutz des Champions"], "Füße": ["Leichtfüßige Stiefel des Champions"]}'),
  ('Der eingeäscherte Erzherzog', 'Relikt', 'Erhöht den durch Folgeangriffe verursachte SCH um 20%.', 'Wenn der Träger einen Folgeangriff einsetzt, wird sein ANG für jedes Mal, das der Folgeangriff SCH zufügt, um 6% erhöht. Dieser Effekt ist bis zu 8-mal stapelbar und hält 3 Rd. an. Das nächste Mal, dass der Träger einen Folgeangriff einsetzt, wird der Effekt entfernt.', 'assets/images/relic_sets/the_ashblazing_grand_duke.png', '{"Kopf": ["Infernokrone des Erzherzogs"], "Hände": ["Lodernde Samthandschuhe des Erzherzogs"], "Körper": ["Anmutige Robe des Erzherzogs"], "Füße": ["Elegante Feststiefel des Erzherzogs"]}'),
  ('Die Traumlicht-Mimen', 'Relikt', 'Erhöht die GES um 6%.', 'Wenn der Träger eine Fertigkeit oder einen Ultimate auf einen anderen Verbündeten einsetzt, wird das Hochgefühl des Ziels der Fähigkeit für 3 Rd. um 16% erhöht. Wenn der Träger mindestens 10 Pkt. „Verdiente Leistung“ besitzt, wird der KRIT-SCH aller Verbündeten zusätzlich für 3 Rd. um 12% erhöht.', 'assets/images/relic_sets/dreamlit_actor.png', '{"Kopf": ["Weinende Maske einer Mimin"], "Hände": ["Farbenfroher Fächer eines Mimen"], "Körper": ["Komisches Kostüm eines Mimen"], "Füße": ["Mondsichel-Tanzstiefel einer Mimin"]}'),
  ('Die gefräßige Ketzerin', 'Relikt', 'Erhöht den KRIT-SCH um 16%.', 'Erhöht den durch Standardangriffe verursachten SCH des Trägers um 36%. Wenn der Träger einen Standardangriff ausführt, wird sein ANG für 2 Rd. um 20% erhöht.', 'assets/images/relic_sets/the_edacious_heretic.png', '{"Kopf": ["Kranialapparat der Ketzerin"], "Hände": ["Injektionshandschuhe der Ketzerin"], "Körper": ["Vernunftszwangsjacke der Ketzerin"], "Füße": ["Hungerstiefel der Ketzerin"]}'),
  ('Dieb des fallenden Meteors', 'Relikt', 'Erhöht Brucheffekt um 16%.', 'Erhöht den Brucheffekt des Trägers um 16%. Wenn der Träger bei einem Gegner Schwächebruch verursacht, wird 3 Pkt. Energie wiederhergestellt.', 'assets/images/relic_sets/thief_of_shooting_meteor.png', '{"Kopf": ["Vielgesichtige Maske des Diebs"], "Hände": ["Bemalte Handschuhe des Diebs"], "Körper": ["Stählerner Wurfhaken des Diebs"], "Füße": ["Meteor-Stiefel des Diebs"]}'),
  ('Eiserne Kavallerie gegen die Plage', 'Relikt', 'Erhöht Brucheffekt um 16%.', 'Wenn der Brucheffekt des Trägers 150% oder mehr beträgt, wird beim Verursachen von Bruch-SCH 10% der VTD des gegnerischen Ziels ignoriert. Wenn der Brucheffekt des Trägers 250% oder mehr beträgt, wird beim Verursachen von Super-Bruch-SCH zusätzlich 15% der VTD des gegnerischen Ziels ignoriert.', 'assets/images/relic_sets/iron_cavalry_against_the_scourge.png', '{"Kopf": ["Zielsuchender Helm der Eisernen Kavallerie"], "Hände": ["Vernichtende Faust der Eisernen Kavallerie"], "Körper": ["Silberne Panzerung der Eisernen Kavallerie"], "Füße": ["Himmlische Beinschienen der Eisernen Kavallerie"]}'),
  ('Erlöserin/Erlöser der Weltneuschöpfung', 'Relikt', 'Erhöht die KRIT-Rate um 8%.', 'Wenn sich nach dem Einsatz eines Standardangriffs oder einer Fertigkeit des Trägers dessen Memogeist auf dem Kampffeld befindet, werden die max. LP des Trägers und seines Memogeists um 24% sowie der verursachte SCH aller Verbündeten um 15% erhöht, bis der Träger seinen nächsten Standardangriff oder seine nächste Fertigkeit einsetzt.', 'assets/images/relic_sets/world_remaking_deliverer.png', '{"Kopf": ["Reisekapuze der Erlöserin/des Erlösers"], "Hände": ["Schutzhandschuhe der Erlöserin/des Erlösers"], "Körper": ["Erbgewand der Erlöserin/des Erlösers"], "Füße": ["Pionierstiefel der Erlöserin/des Erlösers"]}'),
  ('Feuerschmied der Lavaglut', 'Relikt', 'Erhöht Feuer-SCH um 10%.', 'Erhöht den durch Fertigkeiten verursachten SCH des Trägers um 12%. Erhöht nach dem Einsatz des Ultimates den verursachten Feuer-SCH durch den nächsten Angriff um 12%.', 'assets/images/relic_sets/firesmith_of_lava_forging.png', '{"Kopf": ["Obsidianbrille des Feuerschmieds"], "Hände": ["Flammenmeisterring des Feuerschmieds"], "Körper": ["Flammenfeste Schürze des Feuerschmieds"], "Füße": ["Metallbein des Feuerschmieds"]}'),
  ('Gefangene in tiefem Gewahrsam', 'Relikt', 'Erhöht den ANG um 12%.', 'Für jeden DoT-Effekt, den der Gegner erleidet, ignoriert der Träger 6% der VTD dieses Gegners, wenn er diesem SCH zufügt. Bis zu 3 DoT-Effekte werden gezählt.', 'assets/images/relic_sets/prisoner_in_deep_confinement.png', '{"Kopf": ["Maulkorb der Gefangenen"], "Hände": ["Bleisteinschellen der Gefangenen"], "Körper": ["Versiegelte Fesseln der Gefangenen"], "Füße": ["Bindungsfesseln der Gefangenen"]}'),
  ('Genie der strahlenden Sterne', 'Relikt', 'Erhöht Quanten-SCH um 10%.', 'Wenn der Träger einem Gegner SCH zufügt, ignoriert er 10% der VTD des Gegners. Wenn das Ziel Quanten-Schwäche hat, ignoriert der Träger zusätzlich 10% der VTD des Gegners.', 'assets/images/relic_sets/genius_of_brilliant_stars.png', '{"Kopf": ["Ultrasignalbrille des Genies"], "Hände": ["Frequenzerfasser des Genies"], "Körper": ["Metafeldanzug des Genies"], "Füße": ["Gravitationsgleiter des Genies"]}'),
  ('Götterbefragender Meisterschmied', 'Relikt', 'Erhöht die max. LP um 12%.', 'Erhöht den KRIT-SCH, den der Träger Gegnern im Status „VTD-Reduktion“ zufügt, um 28%. Nachdem der Träger einem Gegner den Status VTD-Reduktion zugefügt hat, erhalten alle Verbündeten für 2 Rd. „Brandbeschleuniger“. Dieser Effekt ist nicht stapelbar. Der von Verbündeten mit Brandbeschleuniger verursachte SCH wird um 15% erhöht. Dieser Effekt kann erneut ausgelöst werden, nachdem der Träger einen Angriff ausgeführt hat.', 'assets/images/relic_sets/divine_querying_master_smith.png', '{"Kopf": ["Feuerbestienmaske des Schmieds"], "Hände": ["Panzerhandschuhe des Schmieds"], "Körper": ["Feuerfestes Gewand des Schmieds"], "Füße": ["Unbändige Stiefel des Schmieds"]}'),
  ('Held des Lobgesangs', 'Relikt', 'Erhöht ANG um 12%.', 'Während der Memogeist des Trägers sich auf dem Kampffeld befindet, wird die GES des Trägers um 6% erhöht. Wenn der Memogeist des Trägers angreift, wird der KRIT-SCH von Träger und Memogeist für 2 Rd. um 30% erhöht.', 'assets/images/relic_sets/hero_of_triumphant_song.png', '{"Kopf": ["Siegerkranz des Helden"], "Hände": ["Glänzende Armrüstung des Helden"], "Körper": ["Goldene Kriegsrüstung des Helden"], "Füße": ["Feuerfeste Schienbeinschoner des Helden"]}'),
  ('Himmelweitreichender Wahrsager', 'Relikt', 'Erhöht GES um 6%.', 'Wenn die GES des Trägers vor dem Kampfeintritt größer oder gleich 120/160 ist, wird seine KRIT-Rate um 10%/18% erhöht. Jedes Mal, wenn der Träger im Kampf zum ersten Mal seine Hochgefühl-Fähigkeit einsetzt, wird das Hochgefühl aller Verbündeten um 10% erhöht. Dieser Effekt ist nicht stapelbar.', 'assets/images/relic_sets/diviner_of_distant_reach.png', '{"Kopf": ["Berechnungs-Jade-Abakus des Wahrsagers"], "Hände": ["Ingenium-Armprothese des Wahrsagers"], "Körper": ["Sternengewand des Wahrsagers"], "Füße": ["Fliegende Wolkenstiefel des Wahrsagers"]}'),
  ('Im Wissen verlorene Gelehrte', 'Relikt', 'Erhöht KRIT-Rate um 8%.', 'Erhöht den durch Fertigkeiten und Ultimates verursachten SCH um 20%. Nach dem Einsatz des Ultimates wird der SCH beim nächsten Einsatz der Fertigkeit zusätzlich um 25% erhöht.', 'assets/images/relic_sets/scholar_lost_in_erudition.png', '{"Kopf": ["Silberrandmonokel des Gelehrten"], "Hände": ["Hilfsfinger der Gelehrten"], "Körper": ["Tweedjacke des Gelehrten"], "Füße": ["Filz-Schneestiefel der Gelehrten"]}'),
  ('Jäger aus dem Gletscherwald', 'Relikt', 'Erhöht Eis-SCH um 10%.', 'Erhöht beim Einsatz des Ultimates den KRIT-SCH des Trägers für 2 Rd. um 25%.', 'assets/images/relic_sets/hunter_of_glacial_forest.png', '{"Kopf": ["Artaius-Hut des Jägers"], "Hände": ["Echsenhandschuhe des Jägers"], "Körper": ["Eisdrachenumhang des Jägers"], "Füße": ["Weiche Elchlederstiefel des Jägers"]}'),
  ('Kapitän über den verfluchten Wellen', 'Relikt', 'Erhöht KRIT-SCH um 16%.', 'Wenn der Träger zum Ziel der Fähigkeit eines anderen Verbündeten wird, erhält er 1 Stapelung „Unterstützen“, bis zu 2 Stapelungen. Verbraucht beim Einsatz des Ultimates alle Stapelungen von Unterstützen und erhöht den ANG des Trägers für 1 Rd. um 48%, wenn 2 Stapelungen vorhanden sind.', 'assets/images/relic_sets/wavestrider_captain.png', '{"Kopf": ["Navigatorhut des Kapitäns"], "Hände": ["Sternhöhenmesser des Kapitäns"], "Körper": ["Windmantel des Kapitäns"], "Füße": ["Wellenreiterstiefel des Kapitäns"]}'),
  ('Klagende Dichterin', 'Relikt', 'Erhöht Quanten-SCH um 10%.', 'Reduziert die GES des Trägers um 8%. Wenn die GES des Trägers vor dem Kampfeintritt unter 110/95 liegt, wird die KRIT-Rate des Trägers um 20%/32% erhöht. Dieser Effekt wirkt auch auf den Memogeist des Trägers.', 'assets/images/relic_sets/poet_of_mourning_collapse.png', '{"Kopf": ["Dillkranz der Dichterin"], "Hände": ["Armreif der Dichterin"], "Körper": ["Sternengewand der Dichterin"], "Füße": ["Silberschuhe der Dichterin"]}'),
  ('Kriegsgöttin der lodernden Sonne und des Donners', 'Relikt', 'Erhöht GES um 6%.', 'Erhält „Sanfter Regen“, nachdem der Träger oder sein Memogeist Verbündete außer sich selbst Heilung geleistet hat. Dieser Effekt kann bis zu 1-mal pro Runde ausgelöst werden und hält 2 Rd. an. Wenn der Träger Sanfter Regen besitzt, wird seine GES um 6% und der KRIT-SCH aller Verbündeten um 15% erhöht. Dieser Effekt ist nicht stapelbar.', 'assets/images/relic_sets/warrior_goddess_of_sun_and_thunder.png', '{"Kopf": ["Geflügelter Helm der Kriegsgöttin"], "Hände": ["Reiterstulpen der Kriegsgöttin"], "Körper": ["Dämmerumhang der Kriegsgöttin"], "Füße": ["Tapferkeitssporen der Kriegsgöttin"]}'),
  ('Langlebige Jüngerin', 'Relikt', 'Erhöht die max. LP um 12%.', 'Wenn der Träger getroffen wird oder seine LP von einem Verbündeten verbraucht werden, wird seine KRIT-Rate für 2 Rd. um 8% erhöht. Dieser Effekt ist bis zu 2-fach stapelbar.', 'assets/images/relic_sets/longevous_disciple.png', '{"Kopf": ["Augenprothese der Jüngerin"], "Hände": ["Mechanische Hand der Jüngerin"], "Körper": ["Taubedecktes Federkleid der Jüngerin"], "Füße": ["Himmlische Seidensandalen der Jüngerin"]}'),
  ('Magisches Mädchen mit glänzendem Verdienst', 'Relikt', 'Erhöht KRIT-SCH um 16%.', 'Der vom Träger und seinem Memogeist verursachte Hochgefühl-SCH ignoriert 10% der VTD des Ziels. Für je 5 von Verbündeten gesammelte Lachpunkte ignoriert der verursachte Hochgefühl-SCH zusätzlich 1% der VTD des Ziels. Dieser Effekt ist bis zu 10-fach stapelbar.', 'assets/images/relic_sets/ever_glorious_magical_girl.png', '{"Kopf": ["Glänzende Medaille des Magischen Mädchens"], "Hände": ["Schutzhandschuhe des Magischen Mädchens"], "Körper": ["Ewigtanz-Kampfkleid des Magischen Mädchens"], "Füße": ["Vertragsstiefel des Magischen Mädchens"]}'),
  ('Musketierin des wilden Weizens', 'Relikt', 'Erhöht ANG um 12%.', 'Erhöht die GES des Trägers um 6% und den durch Standardangriffe verursachten SCH um 10%.', 'assets/images/relic_sets/musketeer_of_wild_wheat.png', '{"Kopf": ["Wildweizen-Filzhut der Musketierin"], "Hände": ["Grobe Lederhandschuhe der Musketierin"], "Körper": ["Windjäger-Umhang der Musketierin"], "Füße": ["Nietenbesetzte Reitstiefel der Musketierin"]}'),
  ('Pioniertaucherin toter Gewässer', 'Relikt', 'Erhöht den bei Gegnern mit Debuff verursachten SCH um 12%.', 'Erhöht die KRIT-Rate um 4%. Der bei Gegnern mit nicht weniger als 2/3 Debuffs verursachte KRIT-SCH des Trägers wird um jeweils 8%/12% erhöht. Nachdem er dem Gegner einen Debuff zugefügt hat, werden diese Effekte für 1 Rd. um 100 % erhöht.', 'assets/images/relic_sets/pioneer_diver_of_dead_waters.png', '{"Kopf": ["Hitzefester Panzer der Pionierin"], "Hände": ["Hohler Kompass der Pionierin"], "Körper": ["Versiegelter Bleimantel der Pionierin"], "Füße": ["Astraler Anker der Pionierin"]}'),
  ('Ritterin vom Palast der Reinheit', 'Relikt', 'Erhöht VTD um 15%.', 'Erhöht die vom Träger gewährte Schildmenge um 20%.', 'assets/images/relic_sets/knight_of_purity_palace.png', '{"Kopf": ["Vergebungsvoller Helm der Ritterin"], "Hände": ["Ring des stillen Eides der Ritterin"], "Körper": ["Feierliche Brustplatte der Ritterin"], "Füße": ["Eiserne Stiefel der Ordnung der Ritterin"]}'),
  ('Sternenverhüllter Einsiedler', 'Relikt', 'Erhöht die gewährte Schildmenge um 10%.', 'Erhöht die vom Träger gewährte Schildmenge um 12%. Wenn ein Verbündeter einen vom Träger gewährten Schild hat, wird sein KRIT-SCH um 15% erhöht.', 'assets/images/relic_sets/self_enshrouded_recluse.png', '{"Kopf": ["Breitrandiger Filzhut des Einsiedlers"], "Hände": ["Schlichte Uhr des Einsiedlers"], "Körper": ["Kamelfarbene Jacke des Einsiedlers"], "Füße": ["Weiche Wildlederstiefel des Einsiedlers"]}'),
  ('Tapferer Krieger des Winds', 'Relikt', 'Erhöht den ANG um 12%.', 'Erhöht die KRIT-Rate des Trägers um 6%. Wenn der Träger einen Folgeangriff einsetzt, wird der durch Ultimates verursachte SCH für 1 Rd. um 36% erhöht.', 'assets/images/relic_sets/the_wind_soaring_valorous.png', '{"Kopf": ["Tapfere Maske des Nordhimmels"], "Hände": ["Tapfere Armschiene der Klaue"], "Körper": ["Tapfere Rüstung des Segelflugs"], "Füße": ["Tapfere Beinschienen der Beutejagd"]}'),
  ('Uhrmacher der maschinellen Traumspiele', 'Relikt', 'Erhöht Brucheffekt um 16%.', 'Wenn der Träger seinen Ultimate auf einen Verbündeten anwendet, wird der Brucheffekt aller Verbündeten für 2 Rd. um 30% erhöht. Dieser Effekt ist nicht stapelbar.', 'assets/images/relic_sets/watchmaker_master_of_dream_machinations.png', '{"Kopf": ["Polare Linse des Uhrmachers"], "Hände": ["Glückbringende Armbanduhr des Uhrmachers"], "Körper": ["Illusorischer Anzug des Uhrmachers"], "Füße": ["Traumverbergende Lederschuhe des Uhrmachers"]}'),
  ('Wachen des stürmischen Schnees', 'Relikt', 'Verringert erlittenen SCH um 8%.', 'Liegt der LP-Prozentsatz des Trägers zu Beginn seiner Runde bei 50% oder niedriger, werden LP in Höhe von 8% seiner max. LP und 5 Pkt. Energie wiederhergestellt.', 'assets/images/relic_sets/guard_of_wuthering_snow.png', '{"Kopf": ["Gusseiserner Helm der Wache"], "Hände": ["Strahlende Kampfhandschuhe der Wache"], "Körper": ["Traditionelle Uniform der Wache"], "Füße": ["Silberne Beinschienen der Wache"]}'),
  ('Wanderer der vorbeiziehenden Wolke', 'Relikt', 'Erhöht bewirkte Heilung um 10%.', 'Stellt zu Kampfbeginn sofort 1 Fertigkeitspunkt wieder her.', 'assets/images/relic_sets/passerby_of_wandering_cloud.png', '{"Kopf": ["Verjüngter hölzerner Haarstab des Wanderers"], "Hände": ["Wanderdrachen-Armschutz des Wanderers"], "Körper": ["Zerlumpter bestickter Mantel des Wanderers"], "Füße": ["Düstere Wanderstiefel des Wanderers"]}'),
  ('Wie Navigator Isee es sieht', 'Relikt', 'Erhöht den ANG um 12%.', 'Wenn der Träger den Kampf betritt oder seine Fertigkeit einsetzt, wird der verursachte SCH durch Fertigkeiten und Ultimates um 18% erhöht. Dieser Effekt ist bis zu 3-fach stapelbar. Entfernt zu Beginn der Runde des Trägers bzw. nach dem Einsatz des Ultimates 1 Stapelung dieses Effekts.', 'assets/images/relic_sets/as_navigator_isee_sees_it.png', '{"Kopf": ["Tiefenraumteleskop des Navigators"], "Hände": ["Spielwürfel des Navigators"], "Körper": ["Sternenkarten-Uniform des Navigators"], "Füße": ["Zauberstiefel des Navigators"]}'),
  ('Wiedererlebte Tortur des Priesters', 'Relikt', 'Erhöht GES um 6%.', 'Wenn eine Fertigkeit oder ein Ultimate auf einen Verbündeten eingesetzt wird, wird der KRIT-SCH des Ziels für 2 Rd. um 18% erhöht. Dieser Effekt ist bis zu 2-mal stapelbar.', 'assets/images/relic_sets/sacerdos_relived_ordeal.png', '{"Kopf": ["Melodische Ohrringe des Priesters"], "Hände": ["Begrüßungshandschuhe des Priesters"], "Körper": ["Zeremonielles Gewand des Priesters"], "Füße": ["Beschwerliche Stiefel des Priesters"]}'),
  ('Ödländer aus der Räuberwüste', 'Relikt', 'Erhöht imaginären SCH um 10%.', 'Wenn der Träger Gegnern mit Debuff SCH zufügt, wird KRIT-Rate um 10% erhöht. Wenn der Träger Gegnern im Status Gefangenschaft SCH zufügt, wird KRIT-SCH um 20% erhöht.', 'assets/images/relic_sets/wastelander_of_banditry_desert.png', '{"Kopf": ["Atemmaske des Ödländers"], "Hände": ["Wüstenterminal des Ödländers"], "Körper": ["Mönchsgewand des Ödländers"], "Füße": ["Motorbeinschienen des Ödländers"]}')
